            $scope.newAssessmentObj.GeneralDiagnosisStatusName = "Active";
            $scope.newAssessmentObj.GeneralDiagnosisStatusId = 2;
            $scope.newAssessmentObj.LDiagnosisStatusId = '';
            $scope.newAssessmentObj.RDiagnosisStatusId = '';
