        $scope.compareGonioscopyDetails = function () {
            let oldItem = angular.copy($scope.ExamLogObj.GonioscopyDetails[0]);
            let newItem = angular.copy($scope.FinalGonioscopyDetails[0]);

            let oldChanges = [];
            let newChanges = [];

            // ---------- Compare OD ----------
            if (oldItem.RightEye && newItem.RightEye) {
                let fields = [
                    "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                    "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                ];

                let odOld = [];
                let odNew = [];

                fields.forEach(f => {
                    if (oldItem.RightEye[f] != newItem.RightEye[f]) {
                        odOld.push(`${f}: ${oldItem.RightEye[f] || ''}`);
                        odNew.push(`${f}: ${newItem.RightEye[f] || ''}`);
                    }
                });

                // ✅ RightEyeRemarks
                if (oldItem.RightEyeRemarks != newItem.RightEyeRemarks) {
                    odOld.push(`Remarks: ${oldItem.RightEyeRemarks || ''}`);
                    odNew.push(`Remarks: ${newItem.RightEyeRemarks || ''}`);
                }

                let oldDiag = (oldItem.RightEye.RightEyePossibleDiagnosisArray || [])
                    .filter(d => d.DeleteInd === 'N')
                    .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`).join(', ');
                let newDiag = (newItem.RightEye.RightEyePossibleDiagnosisArray || [])
                    .filter(d => d.DeleteInd === 'N')
                    .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`).join(', ');

                if (oldDiag !== newDiag) {
                    odOld.push(`ODPossibleDiagnosis: ${oldDiag}`);
                    odNew.push(`ODPossibleDiagnosis: ${newDiag}`);
                }
                if (odOld.length > 0 || odNew.length > 0) {
                    oldChanges.push(`OD - ${odOld.join(', ')}`);
                    newChanges.push(`OD - ${odNew.join(', ')}`);
                }
            }

            // ---------- Compare OS ----------
            if (oldItem.LeftEye && newItem.LeftEye) {
                let fields = [
                    "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                    "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                ];

                let osOld = [];
                let osNew = [];

                fields.forEach(f => {
                    if (oldItem.LeftEye[f] != newItem.LeftEye[f]) {
                        osOld.push(`${f}: ${oldItem.LeftEye[f] || ''}`);
                        osNew.push(`${f}: ${newItem.LeftEye[f] || ''}`);
                    }
                });

                // ✅ LeftEyeRemarks
                if (oldItem.LeftEyeRemarks != newItem.LeftEyeRemarks) {
                    osOld.push(`Remarks: ${oldItem.LeftEyeRemarks || ''}`);
                    osNew.push(`Remarks: ${newItem.LeftEyeRemarks || ''}`);
                }

                let oldDiag = (oldItem.LeftEye.LeftEyePossibleDiagnosisArray || [])
                    .filter(d => d.DeleteInd === 'N')
                    .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`).join(', ');
                let newDiag = (newItem.LeftEye.LeftEyePossibleDiagnosisArray || [])
                    .filter(d => d.DeleteInd === 'N')
                    .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`).join(', ');

                if (oldDiag !== newDiag) {
                    osOld.push(`OSPossibleDiagnosis: ${oldDiag}`);
                    osNew.push(`OSPossibleDiagnosis: ${newDiag}`);
                }

                if (osOld.length > 0 || osNew.length > 0) {
                    oldChanges.push(`OS - ${osOld.join(', ')}`);
                    newChanges.push(`OS - ${osNew.join(', ')}`);
                }
            }

            if (newChanges.length > 0) {
                let log = {
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Gonioscopy",
                    ActionType: "Edited",
                    OldActionDescription: oldChanges.join(', '),
                    NewActionDescription: newChanges.join(', '),
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                };
                $scope.ExamLogObj.LogArray.push(log);
            }
        };

