            if (activeList.length === 0) return '';

            let values = activeList.map(x => `${x.ICD10CODE}-${x.BVPossibleDiagnosis}`);

            let desc = `Possible Diagnosis :\n`;
            desc += ` ${values.join(', ')}`;

