        $scope.generateCopyLog = function (AnteriorArray, organId) {

            // Title map
            const TITLE = {
                6: "MRD - Marginal Reflex Distance",
                23: "Lids",
                24: "Conjunctiva",
                25: "Sclera",
                26: "Cornea",
                27: "Anterior Chamber",
                28: "Iris",
                29: "Pupil",
                30: "Lens",
                744: "Lashes",
                746: "Adnexa"
            };

            // IDs to be included
            const ALL_IDS = [6, 23, 24, 25, 26, 27, 28, 29, 30, 744, 746];

            const oppositeOrgan = organId == 1 ? 2 : 1;

            function isSameValue(item, organ, r) {

                let match = (item.RemarksArray || []).find(x =>
                    x.InvFindingId == r.InvFindingId &&
                    x.OrganId == oppositeOrgan &&
                    x.ActiveInd == "Y" &&
                    (x.FindingValue || "") == (r.FindingValue || "") &&
                    (x.Notes || "") == (r.Notes || "")
                );

                return !!match;
            }

            // Extract values
            function getValues(it, organ) {

                if (it.InvestigationId == 6) {

                    let right = `MRD1 : ${it.RMRD1 || ''}, MRDcNS : ${it.RMRDcNS || ''}, MRD2 : ${it.RMRD2 || ''}, LF : ${it.RLF || ''}, PFH : ${it.RPFH || ''}`;
                    let left = `MRD1 : ${it.LMRD1 || ''}, MRDcNS : ${it.LMRDcNS || ''}, MRD2 : ${it.LMRD2 || ''}, LF : ${it.LLF || ''}, PFH : ${it.LPFH || ''}`;

                    let rightEmpty = !it.RMRD1 && !it.RMRDcNS && !it.RMRD2 && !it.RLF && !it.RPFH;
                    let leftEmpty = !it.LMRD1 && !it.LMRDcNS && !it.LMRD2 && !it.LLF && !it.LPFH;

                    if (organ == 1 && rightEmpty) return "";

                    if (organ == 2 && leftEmpty) return "";

                    if (organ == 1) return right;
                    if (organ == 2) return left;

                    return "";
                }


                let arr = [];

                (it.RemarksArray || []).forEach(r => {

                    if (r.OrganId == organ && r.ActiveInd == "Y") {

                        if (isSameValue(it, organ, r)) return;

                        let txt = r.FindingValue || "";
                        if (r.Notes) txt += ` (Notes : ${r.Notes})`;

                        arr.push(txt);
                    }
                });

                return arr.join(", ");
            }

            let sections = [];

            ALL_IDS.forEach(ID => {

                // Find item
                let it = AnteriorArray.find(a => a.InvestigationId == ID);

                if (!it) return;

                // Get OD/OS values
                let result = getValues(it, organId);

                if (result && result.trim() !== "") {
                    sections.push(`${TITLE[ID]} :\n${result}`);
                }
            });

            if (sections.length == 0) return;

            let buttonName = organId == 1 ? "Copy to OS" : "Copy to OD";

            let description =
                `Click on ${buttonName} button

                   Copied Values :

                 ${sections.join("\n\n")}`;

            // Push log

            let LogItem = {
                "LogId": 0,
                "ModuleId": 1,
                "ModuleName": "OUTPatient",
                "SubModuleId": 52,
                "SubModuleName": "Examination",
                "ScreenType": "Exam(Anterior Segment)",
                "ActionType": "Accessed",
                "OldActionDescription": "",
                "NewActionDescription": description.trim(),
            }
            $scope.AddAuditLogNew(LogItem);

        };
        $scope.generatePosteriorCopyLog = function (PosteriorArray, organId) {

            const TITLE = {
                32: "CDR",
                34: "Vitreous",
                35: "Retina",
                33: "Macula",
                2144: "Disc / ON",
                2146: "Choroid",
                39: "Blood Vessels",
                40: "Periphery"
            };

            const ALL_POST_IDS = [32, 34, 35, 33, 2144, 2146, 39, 40];

            const oppositeOrgan = organId == 1 ? 2 : 1;

            // Check OS already has same value → skip in log
            function isSameValue(item, organ, r) {

                let match = (item.RemarksArray || []).find(x =>
                    x.InvFindingId == r.InvFindingId &&
                    x.OrganId == oppositeOrgan &&
                    x.ActiveInd == "Y" &&
                    (x.FindingValue || "") == (r.FindingValue || "") &&
                    (x.Notes || "") == (r.Notes || "")
                );

                return !!match;
            }

            // ---- extract OD/OS values for each investigation ----
            function getValues(it, organ) {

                if (it.InvestigationId == 32) {

                    let right = `VT: ${it.RVertical || ''}, HZ: ${it.RHorizontal || ''}, DPS: ${it.RDPS || ''}`;
                    let left = `VT: ${it.LVertical || ''}, HZ: ${it.LHorizontal || ''}, DPS: ${it.LDPS || ''}`;

                    let rightEmpty = !it.RVertical && !it.RHorizontal && !it.RDPS;
                    let leftEmpty = !it.LVertical && !it.LHorizontal && !it.LDPS;

                    // Skip entire CDR section
                    if (rightEmpty && leftEmpty) return "";

                    // OD requested
                    if (organ == 1 && !rightEmpty) return right;
                    if (organ == 1 && rightEmpty) return "";

                    // OS requested
                    if (organ == 2 && !leftEmpty) return left;
                    if (organ == 2 && leftEmpty) return "";

                    return "";
                }

                let arr = [];

                (it.RemarksArray || []).forEach(r => {

                    if (r.OrganId == organ && r.ActiveInd == "Y") {

                        // Skip duplicates already present
                        if (isSameValue(it, organ, r)) return;

                        let txt = r.FindingValue || "";
                        if (r.Notes) txt += ` (Notes : ${r.Notes})`;

                        arr.push(txt);
                    }
                });

                return arr.join(", ");
            }

            // Build log
            let sections = [];

            ALL_POST_IDS.forEach(ID => {

                let it = PosteriorArray.find(a => a.InvestigationId == ID);
                if (!it) return;

                let result = getValues(it, organId);

                // Skip empty sections
                if (result && result.trim() !== "") {
                    sections.push(`${TITLE[ID]} :\n${result}`);
                }
            });

            if (sections.length == 0) return; // nothing new copied

            let buttonName = organId == 1 ? "Copy to OS" : "Copy to OD";

            let description =
                `Click on ${buttonName} button

                    Copied Values :

                  ${sections.join("\n\n")}`;

            // Final log push
            let LogItem = {
                "LogId": 0,
                "ModuleId": 1,
                "ModuleName": "OUTPatient",
                "SubModuleId": 52,
                "SubModuleName": "Examination",
                "ScreenType": "Exam(Posterior Segment)",
                "ActionType": "Accessed",
                "OldActionDescription": "",
                "NewActionDescription": description.trim(),
            }
            $scope.AddAuditLogNew(LogItem);
        };
        $scope.compareOtherData = function () {

            // ✅ FIXED pushLog (ONLY CHANGE HERE)
            function pushLog(oldDesc, newDesc, screenType) {

                oldDesc = (oldDesc || "").trim();
                newDesc = (newDesc || "").trim();

                // 🔥 Fix for Lacrimal empty structure
                function isLacrimalEmpty(desc) {
                    return !desc ||
                        desc === "Lacrimal Patency\nOD :\nOS :" ||
                        desc === "Lacrimal Patency\nOD :" ||
                        desc === "Lacrimal Patency\nOS :" ||
                        desc === "OD :" ||
                        desc === "OS :";
                }

                if (oldDesc !== newDesc) {

                    let actionType = "";

                    // ✅ SPECIAL FIX ONLY FOR LACRIMAL
                    if (screenType === "Lacrimal Patency") {

                        if (isLacrimalEmpty(oldDesc) && newDesc) {
                            actionType = "Added";
                        }
                        else if (oldDesc && isLacrimalEmpty(newDesc)) {
                            actionType = "Deleted";
                        }
                        else {
                            actionType = "Edited";
                        }

                    } else {
                        // ✅ Existing logic for other modules
                        actionType = oldDesc ? "Edited" : "Added";
                    }

                    $scope.ExamLogObj.LogArray.push({
                        LogId: 0,
                        ModuleId: 1,
                        ModuleName: "OUTPatient",
                        SubModuleId: 52,
                        SubModuleName: "Examination",
                        ScreenType: screenType,
                        ActionType: actionType,
                        OldActionDescription: oldDesc,
                        NewActionDescription: newDesc,
                        ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                    });
                }
            }

            function addSection(oldText, newText, header, obj) {
                let oldHas = sectionHasValues(oldText, header);
                let newHas = sectionHasValues(newText, header);

                if (oldHas || newHas) {
                    if (oldText !== newText) {
                        obj.old += (obj.old ? "\n\n" : "") + oldText;
                        obj.new += (obj.new ? "\n\n" : "") + (newHas ? newText : "");
                    }
                }
            }

            // ================= DRY EYE =================
            let dry = { old: "", new: "" };

            let oldData = angular.copy($scope.ExamLogObj.DryEyeEvaluationData) || [];
            let newData = angular.copy($scope.FinalDryEyeEvaluationData) || [];

            let ids = [2079, 2082, 2103, 2166];

            ids.forEach(id => {
                let oldItem = oldData.find(x => x.InvestigationId === id);
                let newItem = newData.find(x => x.InvestigationId === id);

                let oldDesc = "", newDesc = "";

                if (id === 2079) {
                    oldDesc = oldItem ? $scope.formatSchirmersTestDesc(oldItem) : "";
                    newDesc = newItem ? $scope.formatSchirmersTestDesc(newItem) : "";
                    addSection(oldDesc, newDesc, "Schirmers Test", dry);
                }
                if (id === 2082) {
                    oldDesc = oldItem ? $scope.formatTVTDesc(oldItem) : "";
                    newDesc = newItem ? $scope.formatTVTDesc(newItem) : "";
                    addSection(oldDesc, newDesc, "TVT", dry);
                }
                if (id === 2103) {
                    oldDesc = oldItem ? $scope.formatTODesc(oldItem) : "";
                    newDesc = newItem ? $scope.formatTODesc(newItem) : "";
                    addSection(oldDesc, newDesc, "TO", dry);
                }
                if (id === 2166) {
                    oldDesc = oldItem ? $scope.formatTBUTDesc(oldItem) : "";
                    newDesc = newItem ? $scope.formatTBUTDesc(newItem) : "";
                    addSection(oldDesc, newDesc, "TBUT", dry);
                }
            });

            pushLog(dry.old, dry.new, "Dry Eye Evaluation");


            // ================= HERTEL =================
            let oldH = ($scope.ExamLogObj.HertelsExaminationDetails || []).find(x => x.InvestigationId === 2159);
            let newH = ($scope.FinalHertelsExaminationArray || []).find(x => x.InvestigationId === 2159);

            let oldHDesc = oldH ? $scope.formatHertelsDesc(oldH) : "";
            let newHDesc = newH ? $scope.formatHertelsDesc(newH) : "";

            pushLog(oldHDesc, newHDesc, "Hertel’s Examination");


            // ================= COLOR VISION =================
            let oldCVArr = $scope.ExamLogObj.ColorVisionDetails || [];
            let newCVArr = $scope.FinalColorVisionDetails || [];

            let cvOld = "";
            let cvNew = "";

            oldCVArr.forEach(oldItem => {
                let newItem = newCVArr.find(x => x.InvestigationId === oldItem.InvestigationId);

                let oldBlock = $scope.formatColorVisionDesc(oldItem);
                let newBlock = newItem ? $scope.formatColorVisionDesc(newItem) : "";

                if (oldBlock !== newBlock) {
                    if (!cvOld) {
                        cvOld += "Colour Vision Test\n";
                        cvNew += "Colour Vision Test\n";
                    }
                    cvOld += oldBlock + "\n";
                    cvNew += (newBlock || "") + "\n";
                }
            });

            if (oldCVArr.length === 0 && newCVArr.length > 0) {
                cvNew = "Colour Vision Test\n";
                newCVArr.forEach(x => {
                    let block = $scope.formatColorVisionDesc(x);
                    if (block) cvNew += block + "\n";
                });
            }

            pushLog(cvOld.trim(), cvNew.trim(), "Colour Vision Test");


            // ================= LACRIMAL =================
            let oldLacArr = $scope.ExamLogObj.LacrimalPatiencyDetails || [];
            let newLacArr = $scope.FinalLacrimalPatiencyDetails || [];

            let oldSec = $scope.formatLacrimalPatencySections(oldLacArr);
            let newSec = $scope.formatLacrimalPatencySections(newLacArr);

            let oldLac = "";
            let newLac = "";

            if (oldSec.od !== newSec.od || oldSec.os !== newSec.os) {

                if (oldSec.od.trim() !== "OD :") oldLac += oldSec.od + "\n";
                if (oldSec.os.trim() !== "OS :") oldLac += oldSec.os + "\n";

                if (newSec.od.trim() !== "OD :") newLac += newSec.od + "\n";
                if (newSec.os.trim() !== "OS :") newLac += newSec.os + "\n";

                // ✅ FIX HERE
                if (oldLac.trim() !== "") {
                    oldLac = "Lacrimal Patency\n" + oldLac.trim();
                } else {
                    oldLac = ""; // no heading if empty
                }

                if (newLac.trim() !== "") {
                    newLac = "Lacrimal Patency\n" + newLac.trim();
                } else {
                    newLac = "";
                }
            }

            pushLog(oldLac.trim(), newLac.trim(), "Lacrimal Patency");
        };
