        $scope.formatSchirmersTestDesc = function (item) {

            let header = "Schirmers Test";

            let od = "";
            let os = "";

            // OD
            if (item.ODValue2 || item.ODvalue3 || item.ODValue21 || item.ODvalue31) {
                od = `OD : I - ${item.ODValue2 || ''} Mm in ${item.ODvalue3 || ''} Min , ` +
                    `II - ${item.ODValue21 || ''} Mm in ${item.ODvalue31 || ''} Min`;
            }

            // OS
            if (item.OSValue2 || item.OSvalue3 || item.OSValue21 || item.OSvalue31) {
                os = `OS : I - ${item.OSValue2 || ''} Mm in ${item.OSvalue3 || ''} Min , ` +
                    `II - ${item.OSValue21 || ''} Mm in ${item.OSvalue31 || ''} Min`;
            }
            let notes = item.Remarks ? `Notes : ${item.Remarks}` : "";

            return [
                header,
                od,
                os,
                notes
            ].filter(Boolean).join("\n");
        };
        $scope.formatTVTDesc = function (item) {

            let header = "TVT";

            let od = item.ODValue1 ? `OD : ${item.ODValue1} Mm` : "";
            let os = item.OSValue1 ? `OS : ${item.OSValue1} Mm` : "";
            let notes = item.Remarks ? `Notes : ${item.Remarks}` : "";

            return [
                header,
                od,
                os,
                notes
            ].filter(Boolean).join("\n");
        };
        $scope.formatTODesc = function (item) {

            let header = "TO";

            let od = item.ODValue2 ? `OD : ${item.ODValue2} MOsms/L` : "";
            let os = item.OSValue2 ? `OS : ${item.OSValue2} MOsms/L` : "";
            let notes = item.Remarks ? `Notes : ${item.Remarks}` : "";

            return [
                header,
                od,
                os,
                notes
            ].filter(Boolean).join("\n");
        };
        $scope.formatTBUTDesc = function (item) {

            let header = "TBUT";

            let od = item.ODValue1 ? `OD : ${item.ODValue1} Mm` : "";
            let os = item.OSValue1 ? `OS : ${item.OSValue1} Mm` : "";
            let notes = item.Remarks ? `Notes : ${item.Remarks}` : "";

            return [
                header,
                od,
                os,
                notes
            ].filter(Boolean).join("\n");
        };
        $scope.formatHertelsDesc = function (item) {
            if (!item) return "";



            let OD = item.RightEyeRemarks ? `OD : ${item.RightEyeRemarks}` : "";
            let OS = item.LeftEyeRemarks ? `OS : ${item.LeftEyeRemarks}` : "";
            let base = item.BaseValue ? `Base : ${item.BaseValue}` : "";
            let notes = item.HertelsNotes ? `Notes : ${item.HertelsNotes}` : "";

            if (!OD && !OS && !base && !notes) {
                return "";
            }
            let txt = "Hertel’s Examination";
            if (OD) txt += `\n${OD}`;
            if (OS) txt += `\n${OS}`;
            if (base) txt += `\n${base}`;
            if (notes) txt += `\n${notes}`;

            return txt;
        };
        $scope.formatColorVisionDesc = function (item) {

            if (!item) return "";

            let title = "";

            let testName = item.InvestigationDesc || "";

            let od = item.RightEyeRemarks || "";
            let os = item.LeftEyeRemarks || "";
            let notes = item.Notes || item.Remarks || "";
            if (!od && !os && !notes) {
                return "";
            }

            let desc = `${title}\n${testName}\n`;

            if (od) desc += `OD : ${od || ''}\n`;
            if (os) desc += `OS : ${os || ''}\n`;
            if (notes) desc += `Notes : ${notes || ''}`;

            return desc.trim();
        };
        $scope.formatLacrimalPatencySections = function (items) {

            let odParts = [];
            let osParts = [];

            items.forEach(item => {

                let label = "";
                if (item.InvestigationId == 2091) label = "Watering";
                else if (item.InvestigationId == 2092) label = "Regurgitation";
                else if (item.InvestigationId == 2093) label = "Discharge";
                else if (item.InvestigationId == 2094) label = "Syringing";

                if (label) {
                    if (item.Remarks != "") {
                        odParts.push(`${label} : ${item.Remarks || ''}`);
                    }
                    if (item.LeftEyeRemarks != "") {
                        osParts.push(`${label} : ${item.LeftEyeRemarks || ''}`);
                    }
                }
            });

            return {
                od: `OD : ${odParts.join(", ")}`,
                os: `OS : ${osParts.join(", ")}`
            };
        };
        function getMasterName(list, id, keyName = "name", idField = "id") {
            if (!id || !list) return "";
            let obj = list.find(x => x[idField] == id);
            return obj ? obj[keyName] : "";
        }


        //9 Gaze Evalutions
        function formatNineGaze(obj) {

            if (!obj) return "";

            // If array, take first element
            if (Array.isArray(obj)) {
                obj = obj[0];
            }

            if (!obj) return "";

            let rightValues = [
                obj.RsrValue ?? "0",
                obj.RsrIoValue ?? "0",
                obj.RIoValue ?? "0",
                obj.RLrValue ?? "0",
                obj.RPgValue ?? "0",
                obj.RMrValue ?? "0",
                obj.RIrValue ?? "0",
                obj.RIrSoValue ?? "0",
                obj.RSoValue ?? "0"
            ].join(", ");

            let leftValues = [
                obj.LIoValue ?? "0",
                obj.LIoSrValue ?? "0",
                obj.LSrValue ?? "0",
                obj.LMrValue ?? "0",
                obj.LPgValue ?? "0",
                obj.LLrValue ?? "0",
                obj.LSoValue ?? "0",
                obj.LSoIrValue ?? "0",
                obj.LIrValue ?? "0"
            ].join(", ");

            let text = "";

            text += `OD (Right Eye) : ${rightValues}`;

            if (obj.RRemarks && obj.RRemarks.trim() !== "")
                text += `\nRemarks : ${obj.RRemarks}`;

            text += `\n\nOS (Left Eye) : ${leftValues}`;

            if (obj.LRemarks && obj.LRemarks.trim() !== "")
                text += `\nRemarks : ${obj.LRemarks}`;

            if (obj.AlphabetPattern && obj.AlphabetPattern.trim() !== "")
                text += `\nAlphabet Pattern : ${obj.AlphabetPattern}`;

            return text;
        }



        $scope.compareNineGaze = function (newObj, oldObj) {

            if (!newObj && !oldObj) return;

            let fields = [

                "RsrValue", "RsrIoValue", "RIoValue", "RLrValue", "RPgValue", "RMrValue",
                "RIrValue", "RIrSoValue", "RSoValue",

                "LIoValue", "LIoSrValue", "LSrValue", "LMrValue", "LPgValue", "LLrValue",
                "LSoValue", "LSoIrValue", "LIrValue",

                "RRemarks", "LRemarks", "AlphabetPattern"
            ];

            let added = false;
            let deleted = false;
            let edited = false;

            // NEW has data, OLD empty
            if ((!oldObj || oldObj.length === 0) && (newObj && newObj.length > 0)) {

                added = true;

            }

            // OLD has data, NEW empty
            else if ((oldObj && oldObj.length > 0) && (!newObj || newObj.length === 0)) {

                deleted = true;

            }

            // BOTH have data → check edited
            else if ((oldObj && oldObj.length > 0) && (newObj && newObj.length > 0)) {

                let oldData = oldObj[0];
                let newData = newObj[0];

                let fields = [

                    "RsrValue", "RsrIoValue", "RIoValue", "RLrValue", "RPgValue", "RMrValue",
                    "RIrValue", "RIrSoValue", "RSoValue",

                    "LIoValue", "LIoSrValue", "LSrValue", "LMrValue", "LPgValue", "LLrValue",
                    "LSoValue", "LSoIrValue", "LIrValue",

                    "RRemarks", "LRemarks", "AlphabetPattern"
                ];

                edited = fields.some(f => (oldData[f] || "") !== (newData[f] || ""));

            }

            let now = $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss");


            if (added) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Motor Examination (9 Gaze Evaluation)",
                    ActionType: "Added",
                    OldActionDescription: "",
                    NewActionDescription: formatNineGaze(newObj),
                    ActionDateTime: now
                });
            }


            if (edited) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Motor Examination (9 Gaze Evaluation)",
                    ActionType: "Edited",
                    OldActionDescription: formatNineGaze(oldObj),
                    NewActionDescription: formatNineGaze(newObj),
                    ActionDateTime: now
                });
            }


            if (deleted) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Motor Examination (9 Gaze Evaluation)",
                    ActionType: "Deleted",
                    OldActionDescription: formatNineGaze(oldObj),
                    NewActionDescription: "",
                    ActionDateTime: now
                });
            }

            console.log("FINAL LOG ARRAY :", $scope.ExamLogObj.LogArray);
        };



        // Amsler Grid
        // ---------- FORMAT FUNCTION ----------
        function formatAmslerGrid(obj) {

            if (!obj) return "";

            function getChecked(list) {
                return (list || [])
                    .filter(x => x.IsChecked)
                    .map(x => x.Id)
                    .join(", ");
            }

            let rightCells = getChecked(obj.RDrawList);
            let leftCells = getChecked(obj.LDrawList);

            let text = "";

            // ---------- OD (Right Eye) ----------
            let rightName = obj.RightEyeName || "Normal";

            text += `OD (Right Eye) : ${rightName}`;

            if (rightCells)
                text += `\nSelected Grids : ${rightCells}`;

            if (obj.RightEyeRemarks)
                text += `\nRemarks : ${obj.RightEyeRemarks}`;

            // ---------- OS (Left Eye) ----------
            let leftName = obj.LeftEyeName || "Normal";

            text += `\n\nOS (Left Eye) : ${leftName}`;

            if (leftCells)
                text += `\nSelected Grids : ${leftCells}`;

            if (obj.LeftEyeRemarks)
                text += `\nRemarks : ${obj.LeftEyeRemarks}`;

            return text;
        }


        // ---------- GET EYE NAME ----------
        $scope.getEyeNameById = function (id) {

            if (!id) return "";

            let item = $scope.AmslerGridDropdowmList.find(x => x.Id == id);

            return item ? item.Values : "";
        };


        // ---------- GET CHECKED IDS ONLY ----------
        function getCheckedIds(list) {

            return (list || [])
                .filter(x => x.IsChecked)
                .map(x => x.Id)
                .sort()
                .join(",");
        }


        // ---------- COMPARE FUNCTION ----------
        $scope.compareAmslerGrid = function (newObj, oldObj) {

            // Handle array cases
            if (Array.isArray(newObj))
                newObj = newObj[0];

            if (Array.isArray(oldObj))
                oldObj = oldObj[0];

            // No data
            if (!newObj && !oldObj)
                return;

            // Clone objects (avoid reference issues)
            let newData = newObj ? angular.copy(newObj) : null;
            let oldData = oldObj ? angular.copy(oldObj) : null;

            // Set Eye Names
            if (newData) {
                newData.RightEyeName = $scope.getEyeNameById(newData.RightEyeId);
                newData.LeftEyeName = $scope.getEyeNameById(newData.LeftEyeId);
            }

            if (oldData) {
                oldData.RightEyeName = $scope.getEyeNameById(oldData.RightEyeId);
                oldData.LeftEyeName = $scope.getEyeNameById(oldData.LeftEyeId);
            }

            let added = false;
            let deleted = false;
            let edited = false;

            // ---------- CHECK STATES ----------
            if (!oldData && newData) {

                added = true;
            }
            else if (oldData && !newData) {

                deleted = true;
            }
            else if (oldData && newData) {

                // Compare only checked grid ids
                let oldRight = getCheckedIds(oldData.RDrawList);
                let newRight = getCheckedIds(newData.RDrawList);

                let oldLeft = getCheckedIds(oldData.LDrawList);
                let newLeft = getCheckedIds(newData.LDrawList);

                // Compare actual values only
                if (
                    oldRight !== newRight ||
                    oldLeft !== newLeft ||
                    (oldData.RightEyeRemarks || "") !== (newData.RightEyeRemarks || "") ||
                    (oldData.LeftEyeRemarks || "") !== (newData.LeftEyeRemarks || "") ||
                    (oldData.RightEyeId || "") !== (newData.RightEyeId || "") ||
                    (oldData.LeftEyeId || "") !== (newData.LeftEyeId || "")
                ) {

                    edited = true;
                }
            }

            let now = $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss");

            // ---------- ADDED ----------
            if (added) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Exam (Amsler Grid)",
                    ActionType: "Added",
                    OldActionDescription: "",
                    NewActionDescription: formatAmslerGrid(newData),
                    ActionDateTime: now
                });
            }

            // ---------- EDITED ----------
            if (edited) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Exam (Amsler Grid)",
                    ActionType: "Edited",
                    OldActionDescription: formatAmslerGrid(oldData),
                    NewActionDescription: formatAmslerGrid(newData),
                    ActionDateTime: now
                });
            }

            // ---------- DELETED ----------
            if (deleted) {

                $scope.ExamLogObj.LogArray.push({

                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Exam (Amsler Grid)",
                    ActionType: "Deleted",
                    OldActionDescription: formatAmslerGrid(oldData),
                    NewActionDescription: "",
                    ActionDateTime: now
                });
            }
        };



        // confirtational

        function formatConfrontationalFieldTest(obj) {

            if (!obj) return "";

            function getChecked(list) {
                return (list || [])
                    .filter(x => x.IsChecked)
                    .map(x => x.Id)
                    .join(", ");
            }

            let text = "";

            // ---------- 8 FIELD TEST ----------

            let right8 = getChecked(obj.RDrawList);
            let left8 = getChecked(obj.LDrawList);

            text += "8 Field Test\n";

            text += `OD (Right Eye)\n`;

            if (right8)
                text += `Selected Fields : ${right8}\n`;

            if (obj.RightEyeRemarks)
                text += `Remarks : ${obj.RightEyeRemarks}\n`;

            if (obj.ERightEyeNotes)
                text += `Notes : ${obj.ERightEyeNotes}\n`;


            text += `\nOS (Left Eye)\n`;

            if (left8)
                text += `Selected Fields : ${left8}\n`;

            if (obj.LeftEyeRemarks)
                text += `Remarks : ${obj.LeftEyeRemarks}\n`;

            if (obj.ELeftEyeNotes)
                text += `Notes : ${obj.ELeftEyeNotes}\n`;


            // ---------- 4 FIELD TEST ----------

            let right4 = getChecked(obj.FRDrawList);
            let left4 = getChecked(obj.FLDrawList);

            text += `\n4 Field Test\n`;

            text += `OD (Right Eye)\n`;

            if (right4)
                text += `Selected Fields : ${right4}\n`;

            if (obj.FRightEyeRemarks)
                text += `Remarks : ${obj.FRightEyeRemarks}\n`;

            if (obj.FRightEyeNotes)
                text += `Notes : ${obj.FRightEyeNotes}\n`;


            text += `\nOS (Left Eye)\n`;

            if (left4)
                text += `Selected Fields : ${left4}\n`;

            if (obj.FLeftEyeRemarks)
                text += `Remarks : ${obj.FLeftEyeRemarks}\n`;

            if (obj.FLeftEyeNotes)
                text += `Notes : ${obj.FLeftEyeNotes}`;

            return text.trim();
        }

