        function formatExtraOcular(extraArr) {
            if (!extraArr || extraArr.length === 0) return "";
            let obj = extraArr[0];
            let rightValues = `SR: ${clean(obj.RsrValue)}, IO: ${clean(obj.RIoValue)}, LR: ${clean(obj.RLrValue)}, MR: ${clean(obj.RMrValue)}, IR: ${clean(obj.RIrValue)}, SO: ${clean(obj.RSoValue)}`;
            let leftValues = `SR: ${clean(obj.LSrValue)}, IO: ${clean(obj.LIoValue)}, LR: ${clean(obj.LLrValue)}, MR: ${clean(obj.LMrValue)}, IR: ${clean(obj.LIrValue)}, SO: ${clean(obj.LSoValue)}`;
            let text = "";
            text += `OD (Right Eye) : ${rightValues}`;
            if (obj.RRemarks) text += `\nRemarks : ${obj.RRemarks}`;
            text += `\n\nOS (Left Eye) : ${leftValues}`;
            if (obj.LRemarks) text += `\nRemarks : ${obj.LRemarks}`;
            return text;
        }
        function formatDuctions(ductionArr) {
            if (!ductionArr || ductionArr.length === 0) return "";
            let organs = ductionArr[0].InvestigationOrgans || [];
            let odDuction = organs
                .filter(x => x.PositionDesc === "OD" && x.DeleteInd !== "Y")
                .map(x => x.Value).join(", ");
            let osDuction = organs
                .filter(x => x.PositionDesc === "OS" && x.DeleteInd !== "Y")
                .map(x => x.Value).join(", ");
            let text = "";
            if (odDuction) text += `OD - Limitation Of: ${odDuction}`;
            if (osDuction) text += `\nOS - Limitation Of: ${osDuction}`;
            return text;
        }

        $scope.compareExtraOcular = function (extraNew, extraOld) {
            extraNew = extraNew || [];
            extraOld = extraOld || [];
            let newText = formatExtraOcular(extraNew);
            let oldText = formatExtraOcular(extraOld);
            if (newText === oldText) return;
            let actionType = "Edited";
            if (!extraOld.length && extraNew.length) actionType = "Added";
            if (extraOld.length && !extraNew.length) actionType = "Deleted";
            let now = $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss");
            $scope.ExamLogObj.LogArray.push({
                LogId: 0,
                ModuleId: 1,
                ModuleName: "OUTPatient",
                SubModuleId: 52,
                SubModuleName: "Examination",
                ScreenType: "Motor Examination (Extra Ocular Motility)",
                ActionType: actionType,
                OldActionDescription: oldText ? `Extra Ocular Motility:\n${oldText}` : '',
                NewActionDescription: newText ? `Extra Ocular Motility:\n${newText}` : '',
                ActionDateTime: now
            });
        };
        $scope.compareDuctions = function (newDuction, oldDuction) {
            newDuction = newDuction || [];
            oldDuction = oldDuction || [];
            let newText = formatDuctions(newDuction);
            let oldText = formatDuctions(oldDuction);
            if (newText === oldText) return;
            let actionType = "Edited";
            if (!oldDuction.length && newDuction.length) actionType = "Added";
            if (oldDuction.length && !newDuction.length) actionType = "Deleted";
            let now = $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss");
            $scope.ExamLogObj.LogArray.push({
                LogId: 0,
                ModuleId: 1,
                ModuleName: "OUTPatient",
                SubModuleId: 52,
                SubModuleName: "Examination",
                ScreenType: "Motor Examination (Ductions)",
                ActionType: actionType,
                OldActionDescription: oldText ? `Ductions:\n${oldText}` : '',
                NewActionDescription: newText ? `Ductions:\n${newText}` : '',
                ActionDateTime: now
            });
        };


        $scope.compareAssessmentList = function () {

            const newList = $scope.AssessmentplanpopupObj.AssessmentListArray || [];
            const oldList = $scope.ExamLogObj.AssessmentPlan || [];

            let masters = {
                Severity: $scope.GetSeverityList,
                Status: $scope.AssesmentPlanStatusList,
                Episode: $scope.CareEpisodeList,
                Priority: $scope.GetPriorityList
            };

            let oldArr = [];
            let newArr = [];
            let deletedArr = [];
            let deletedCount = 0;

            // ---------------------- MASTER GETTER ----------------------
            function getMaster(list, id, label, key) {
                let f = list.find(x => x[key] == id);
                return f ? f[label] : "";
            }

            // ---------------------- LOCATION ----------------------
            function locName(id) {
                return id == 1 ? "OD" : id == 2 ? "OS" : id == 4 ? "General" : "";
            }

            // ---------------------- HEADER ----------------------
            function header(item) {
                let cs = item.CodeSystem ? item.CodeSystem + " - " : "";
                let icd = item.ICD10CODE ? item.ICD10CODE + " | " : "";
                return `${cs}${icd}${item.DiagnosisName || item.ICD10DIAGDESCRIPTION}`;
            }

            // ---------------------- CHECK FIELD ----------------------
            function check(label, oldV, newV, oldFields, newFields) {
                if ((oldV || "") !== (newV || "")) {
                    if (oldV) oldFields.push(`${label} : ${oldV}`);
                    if (newV) newFields.push(`${label} : ${newV}`);
                }
            }

            // ---------------------- DELETED ITEMS ----------------------
            oldList.forEach(o => {
                let exists = newList.find(n => n.ConsultationDiagnosisId == o.ConsultationDiagnosisId);
                exists = exists || "";
                if (exists != "") {
                    if (exists.DeleteInd == "Y") {
                        deletedArr.push(header(o));
                        deletedCount++;
                    }
                }
            });

            // ---------------------- ADDED + EDITED ----------------------
            newList.forEach(n => {

                if (n.DeleteInd == "Y") return;

                let old = oldList.find(o => o.ConsultationDiagnosisId == n.ConsultationDiagnosisId);

                let h = header(n);

                // ---------------------- ADDED ----------------------
                if (!old) {
                    let add = [];
                    if (n.LocationId1)
                        add.push(`Location : ${locName(n.LocationId1)}`);

                    if (n.SeverityId1)
                        add.push(`Severity : ${getMaster(masters.Severity, n.SeverityId1, "SeverityName", "SeverityId")}`);

                    if (n.DiagnosisStatusId1)
                        add.push(`Status : ${getMaster(masters.Status, n.DiagnosisStatusId1, "AssesmentPlanStatus", "AssesmentPlanStatusID")}`);

                    if (n.LocationId2)
                        add.push(`Location - 2 : ${locName(n.LocationId2)}`);

                    if (n.SeverityId2)
                        add.push(`Severity - 2 : ${getMaster(masters.Severity, n.SeverityId2, "SeverityName", "SeverityId")}`);

                    if (n.DiagnosisStatusId2)
                        add.push(`Status - 2 : ${getMaster(masters.Status, n.DiagnosisStatusId2, "AssesmentPlanStatus", "AssesmentPlanStatusID")}`);

                    if (n.CareEpisodeId)
                        add.push(`Care Episode : ${getMaster(masters.Episode, n.CareEpisodeId, "CareEpisodeName", "CareEpisodeId")}`);

                    if (n.PriorityId)
                        add.push(`Priority : ${getMaster(masters.Priority, n.PriorityId, "AssesmentPlanPriority", "AssesmentPlanPriorityID")}`);

                    let ap = n.AssessmentPlan || {};
                    if (ap.AssessmentsNotes) add.push(`Assessment Notes : ${ap.AssessmentsNotes}`);
                    if (ap.DoctorNotes) add.push(`Doctor Notes : ${ap.DoctorNotes}`);
                    if (ap.PlanofDiscussionsNotes) add.push(`Plan : ${ap.PlanofDiscussionsNotes}`);
                    if (ap.ActionsTaken) add.push(`Actions Taken : ${ap.ActionsTaken}`);
                    if (ap.PatientInstructions) add.push(`Patient Instructions : ${ap.PatientInstructions}`);

                    newArr.push(h + "\n" + add.join("\n"));
                    return;
                }

                // ---------------------- EDITED ----------------------
                let oldF = [];
                let newF = [];

                check("Location", locName(old.LocationId1), locName(n.LocationId1), oldF, newF);
                check("Severity",
                    getMaster(masters.Severity, old.SeverityId1, "SeverityName", "SeverityId"),
                    getMaster(masters.Severity, n.SeverityId1, "SeverityName", "SeverityId"),
                    oldF, newF
                );
                check("Status",
                    getMaster(masters.Status, old.DiagnosisStatusId1, "AssesmentPlanStatus", "AssesmentPlanStatusID"),
                    getMaster(masters.Status, n.DiagnosisStatusId1, "AssesmentPlanStatus", "AssesmentPlanStatusID"),
                    oldF, newF
                );

                check("Location - 2", locName(old.LocationId2), locName(n.LocationId2), oldF, newF);


                check("Severity - 2",
                    getMaster(masters.Severity, old.SeverityId2, "SeverityName", "SeverityId"),
                    getMaster(masters.Severity, n.SeverityId2, "SeverityName", "SeverityId"),
                    oldF, newF
                );



                check("Status - 2",
                    getMaster(masters.Status, old.DiagnosisStatusId2, "AssesmentPlanStatus", "AssesmentPlanStatusID"),
                    getMaster(masters.Status, n.DiagnosisStatusId2, "AssesmentPlanStatus", "AssesmentPlanStatusID"),
                    oldF, newF
                );

                check("Care Episode",
                    getMaster(masters.Episode, old.CareEpisodeId, "CareEpisodeName", "CareEpisodeId"),
                    getMaster(masters.Episode, n.CareEpisodeId, "CareEpisodeName", "CareEpisodeId"),
                    oldF, newF
                );

                check("Priority",
                    getMaster(masters.Priority, old.PriorityId, "AssesmentPlanPriority", "AssesmentPlanPriorityID"),
                    getMaster(masters.Priority, n.PriorityId, "AssesmentPlanPriority", "AssesmentPlanPriorityID"),
                    oldF, newF
                );

                // NOTES
                let op = old.AssessmentPlan || {};
                let np = n.AssessmentPlan || {};

                check("Assessment Notes", op.AssessmentsNotes, np.AssessmentsNotes, oldF, newF);
                check("Doctor Notes", op.DoctorNotes, np.DoctorNotes, oldF, newF);
                check("Plan", op.PlanofDiscussionsNotes, np.PlanofDiscussionsNotes, oldF, newF);
                check("Actions Taken", op.ActionsTaken, np.ActionsTaken, oldF, newF);
                check("Patient Instructions", op.PatientInstructions, np.PatientInstructions, oldF, newF);

                if (oldF.length || newF.length) {
                    oldArr.push(h + "\n" + oldF.join("\n"));
                    newArr.push(h + "\n" + newF.join("\n"));
                }
            });

            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 53,
                    SubModuleName: "Assessment Plan",
                    ScreenType: "Assessment",
                    ActionType: "Deleted",
                    OldActionDescription: deletedArr.join("\n\n"),
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }

            return {
                oldDescription: oldArr.join("\n\n").trim(),
                newDescription: newArr.join("\n\n").trim()
            };
        };



        function pickAssessmentFields(obj) {
            return {
                LocationId1: obj.LocationId1,
                LocationId2: obj.LocationId2,
                SeverityId1: obj.SeverityId1,
                SeverityId2: obj.SeverityId2,
                DiagnosisStatusId1: obj.DiagnosisStatusId1,
                DiagnosisStatusId2: obj.DiagnosisStatusId2,
                CareEpisodeId: obj.CareEpisodeId,
                PriorityId: obj.PriorityId,

                Notes: obj.AssessmentPlan?.AssessmentsNotes || "",
                Doc: obj.AssessmentPlan?.DoctorNotes || "",
                Plan: obj.AssessmentPlan?.PlanofDiscussionsNotes || "",
                ActionTaken: obj.AssessmentPlan?.ActionsTaken || "",
                PatientInstructions: obj.AssessmentPlan?.PatientInstructions || ""
            };
        }
        function formatAssessmentLine(item, masters) {

            item.CodeSystem = item.CodeSystem || "";
            item.ICD10CODE = item.ICD10CODE || "";

            // ------- Line 1 -------
            let line1 = "";
            let CodeSystem = item.CodeSystem ? item.CodeSystem + " - " : "";
            let ICD10CODE = item.ICD10CODE ? item.ICD10CODE + " | " : "";

            line1 = `${CodeSystem}${ICD10CODE}${item.DiagnosisName || item.ICD10DIAGDESCRIPTION}`;

            // ------- Line 2 -------
            let parts2 = [];

            // Location
            let loc1 = item.LocationId1 == 1 ? "OD" : item.LocationId1 == 2 ? "OS" : item.LocationId1 == 4 ? "General" : "";
            let loc2 = item.LocationId2 == 1 ? "OD" : item.LocationId2 == 2 ? "OS" : item.LocationId2 == 4 ? "General" : "";
            if (loc1) parts2.push(`Location : ${loc1}`);
            if (loc1) parts2.push(`Severity : ${getMasterName(masters.SeverityList, item.SeverityId1, "SeverityName", "SeverityId")}`);
            if (loc1) parts2.push(`Status : ${getMasterName(masters.StatusList, item.DiagnosisStatusId1, "AssesmentPlanStatus", "AssesmentPlanStatusID")}`);

            if (loc2) parts2.push(`Location - 2 : ${loc2}`);
            if (loc2) parts2.push(`Severity : ${getMasterName(masters.SeverityList, item.SeverityId2, "SeverityName", "SeverityId")}`);
            if (loc2) parts2.push(`Status : ${getMasterName(masters.StatusList, item.DiagnosisStatusId2, "AssesmentPlanStatus", "AssesmentPlanStatusID")}`);

            // Care Episode
            let ce = getMasterName(masters.CareEpisodeList, item.CareEpisodeId, "CareEpisodeName", "CareEpisodeId");
            if (ce) parts2.push(`Care Episode : ${ce}`);

            // Priority
            let pr = getMasterName(masters.PriorityList, item.PriorityId, "AssesmentPlanPriority", "AssesmentPlanPriorityID");
            if (pr) parts2.push(`Priority : ${pr}`);

            let line2 = parts2.join(", ");

            // ------- Line 3 -------
            let ap = item.AssessmentPlan || {};

            let line3Parts = [];

            if (ap.AssessmentsNotes) line3Parts.push(`\nAssessments Notes : ${ap.AssessmentsNotes}`);
            if (ap.DoctorNotes) line3Parts.push(`\nDoctor Notes : ${ap.DoctorNotes}`);
            if (ap.PlanofDiscussionsNotes) line3Parts.push(`\nPlan : ${ap.PlanofDiscussionsNotes}`);
            if (ap.ActionsTaken) line3Parts.push(`\nActions Taken : ${ap.ActionsTaken}`);
            if (ap.PatientInstructions) line3Parts.push(`\nPatient Instructions : ${ap.PatientInstructions}`);

            let line3 = line3Parts.join(" , ");

            // FINAL 3-LINE FORMAT
            return `${line1}\n${line2}\n${line3}`.trim();
        }

        $scope.compareInvestigations = function () {

            const newList = $scope.cacheStorageItem.InvestigationsDetails || [];
            const oldList = $scope.ExamLogObj.InvestigationsDetails || [];

            let oldArr = [];
            let newArr = [];
            let deleteArr = [];

            let deletedCount = 0;
            let Ordersnames = '';

            // ---- Deleted ----
            oldList.forEach(old => {
                let exists = newList.find(n => n.PatientInvestigationId == old.PatientInvestigationId);
                if (!exists || exists.DeleteInd === "Y") {
                    Ordersnames += `${old.ProcedureCode || ""} - ${old.Description || old.InvestigationName || ""}`;
                    deletedCount++;
                    //  deleteArr.push(formatInvestigation(old));
                    deletedCount++;
                }
            });

            // ---- Added & Edited ----
            newList.forEach(n => {

                if (n.DeleteInd === "Y") return;

                let old = oldList.find(o => o.PatientInvestigationId == n.PatientInvestigationId);

                if (!old) {
                    // Added
                    newArr.push(formatInvestigation(n));
                    return;
                }

                // Edited check
                let oldFields = pickInvestigationCompareFields(old);
                let newFields = pickInvestigationCompareFields(n);

                if (JSON.stringify(oldFields) !== JSON.stringify(newFields)) {
                    oldArr.push(formatInvestigation(old));
                    newArr.push(formatInvestigation(n));
                }
            });
            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Investigations",
                    ActionType: "Deleted",
                    OldActionDescription: Ordersnames,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            return {
                oldDescription: oldArr.join("\n\n").trim(),
                newDescription: newArr.join("\n\n").trim(),
            };
        };
        function getFindingText(arr, typeId, organId) {
            if (!Array.isArray(arr)) return "";

            return arr
                .filter(x =>
                    x.DeleteInd === 'N' &&
                    x.TypeId === typeId &&
                    x.OrganId === organId
                )
                .map(x => x.FindingValue)
                .join(", ");
        }
        function getActiveFilesByEye(files, organId) {
            if (!Array.isArray(files)) return "";

            return files
                .filter(f =>
                    f.DeleteInd === 'N' &&
                    f.OrganId === organId &&
                    f.DocumentName
                )
                .map(f => f.DocumentName)
                .join(", ");
        }


        function formatInvestigation(inv) {
            if (!inv) return "";

            let out = [];

            // ---- Header ----
            let header = `${inv.ProcedureCode || ""} - ${inv.Description || inv.InvestigationName || ""}`;
            out.push(header);

            // ---- Loop OrderDetails (usually 1 row) ----
            (inv.OrderDetails || []).forEach(od => {
                od.Duration = od.Duration || "";
                od.DurationType = od.DurationType || "";
                od.DurationDate = od.DurationDate || "";
                // Eye
                let eye = inv.OrganId == 1 ? "OD" :
                    inv.OrganId == 2 ? "OS" :
                        inv.OrganId == 3 ? "OU" : "";

                // Status
                let status = od.StatusId == 1 ? "Active" : "InActive";

                // Onset
                let onset = "";
                if (od.DurationDate) {
                    onset = $filter("date")(od.DurationDate, "MM-dd-yyyy");
                } else if (od.Duration && od.DurationType) {
                    let unit = "";
                    switch (od.DurationType) {
                        case "D": unit = "Days"; break;
                        case "W": unit = "Weeks"; break;
                        case "M": unit = "Months"; break;
                        case "Y": unit = "Years"; break;
                        case "SB": unit = "Since Birth"; break;
                    }
                    onset = od.DurationType === "SB" ? "Since Birth" : `${od.Duration} ${unit}`;
                }

                out.push(`Eye : ${eye} , Status : ${status} , Modality : ${od.ModalityName || ""} , Onset : ${onset}`);

                // ---- Diagnosis ----
                //if (od.DiagnosisList && od.DiagnosisList.length > 0) {
                //    out.push("\nDiagnosis :");
                //    od.DiagnosisList.forEach(d => {
                //        out.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                //    });
                //}

                if (od.DiagnosisList && od.DiagnosisList.length > 0) {

                    const diagList = od.DiagnosisList.filter(d => d.DeleteInd === 'N');

                    if (diagList.length > 0) {
                        out.push("\nDiagnosis :");
                        diagList.forEach(d => {
                            out.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                        });
                    }
                }


                // ---- Provider & Coordinator notes ----
                if (od.ProviderRemarks)
                    out.push(`\nProvider Remarks : ${od.ProviderRemarks}`);

                if (od.CoordinatorNotes)
                    out.push(`Coordinator Notes : ${od.CoordinatorNotes}`);

            });
            let interpretationText = formatInterpretationResult(inv);
            if (interpretationText) out.push(interpretationText);
            return out.join("\n");
        }
        function formatInterpretationResult(inv) {
            let iod = inv.InvestigationOrderDetail;
            if (!iod) return "";

            let out = [];

            // ---- Interpretation Result ----
            if (iod.ImageQuality) {
                out.push("\nInterpretation Result :-");
                out.push(`Image Quality : ${iod.ImageQuality}`);
            }

            // ---- Findings ----
            let findings = [];

            function pushIf(label, value) {
                if (value) findings.push(`${label} : ${value}`);
            }

            // ---- OD ----
            let od = [];
            pushIf.call({}, {}, null); // no-op safeguard

            function pushOD(label, value) {
                if (value) od.push(`${label} : ${value}`);
            }
            let odMacular = getFindingText(iod.MacularFindingArray, 4, 1);
            let odON = getFindingText(iod.ONFindingArray, 5, 1);
            let odFundus = getFindingText(iod.FundusFindingArray, 1, 1);
            let odFA = getFindingText(iod.FAFindingArray, 2, 1);
            let odICG = getFindingText(iod.ICGFindingArray, 3, 1);

            pushOD("Macular Findings Value", odMacular);
            pushOD("Macular Thickness", iod.ODMacularThickNess);
            pushOD("RHFL Thickness", iod.ODRHFLThickNess);
            pushOD("IOL Lens Value", iod.ODIOLLensValue);
            pushOD("IOL Power", iod.ODIOLPower);
            pushOD("Toric Power", iod.ODToricPower);
            pushOD("IOL Manufacturer", iod.ODIOLManufacturer);
            pushOD("Frequencies Value", iod.ODFrequenciesValue);
            pushOD("Finding Value", iod.ODFindingValue);
            pushOD("K1 Value", iod.ODK1Value);
            pushOD("K2 Value", iod.ODK2Value);
            pushOD("CYL Value", iod.ODCYLValue);
            pushOD("Corneal Thickness", iod.ODCornealThicknessValue);
            pushOD("SL Photo", iod.ODOCTMACFindings);
            pushOD("Lids", iod.ODLidsValue);
            pushOD("Conjunctiva", iod.ODConjunctivaValue);
            pushOD("Sclera", iod.ODScleraValue);
            pushOD("Cornea", iod.ODCorneaValue);
            pushOD("Endothelial Cell Count", iod.ODEndothelialCellCountValue);
            pushOD("Endothelial Corneal Thickness", iod.ODEndoCornealThicknessValue);
            pushOD("Endothelial Cell Density", iod.ODEndothelialCellDensity);
            pushOD("Fixation Loss", iod.ODFixationLoss);
            pushOD("False Positive Errors", iod.ODFalsePositiveErrors);
            pushOD("False Negative Errors", iod.ODFalseNegitiveErrors);
            pushOD("TD Probability Plot", iod.ODTDProbabilityPlot);
            pushOD("PD Probability Plot", iod.ODPDProbabilityPlot);
            pushOD("Mean Deviation", iod.ODMeanDeviation);
            pushOD("Pattern Std Deviation", iod.ODPatternStandardDeviation);
            pushOD("Visual Field Index", iod.ODVisualFieldIndex);
            pushOD("GHT Value", iod.ODGHTValue);
            pushOD("HVF Finding", iod.ODHVFFindingValue);
            pushOD("AS-OCT", iod.ODASOCTfindingValue);


            pushOD("ON Findings", odON);
            pushOD("Fundus Findings", odFundus);
            pushOD("FA", odFA);
            pushOD("ICG", odICG);


            if (od.length > 0) {
                out.push("\nFindings :");
                out.push("OD -");
                od.forEach(x => out.push(x));
            }

            // ---- OS ----
            let os = [];

            function pushOS(label, value) {
                if (value) os.push(`${label} : ${value}`);
            }
            let osMacular = getFindingText(iod.MacularFindingArray, 4, 2);
            let osON = getFindingText(iod.ONFindingArray, 5, 2);
            let osFundus = getFindingText(iod.FundusFindingArray, 1, 2);
            let osFA = getFindingText(iod.FAFindingArray, 2, 2);
            let osICG = getFindingText(iod.ICGFindingArray, 3, 2);

            pushOS("Macular Findings Value", osMacular);
            pushOS("Macular Thickness", iod.OSMacularThickNess);
            pushOS("RHFL Thickness", iod.OSRHFLThickNess);
            pushOS("IOL Lens Value", iod.OSIOLLensValue);
            pushOS("IOL Power", iod.OSIOLPower);
            pushOS("Toric Power", iod.OSToricPower);
            pushOS("IOL Manufacturer", iod.OSIOLManufacturer);
            pushOS("Frequencies Value", iod.OSFrequenciesValue);
            pushOS("Finding Value", iod.OSFindingValue);
            pushOS("K1 Value", iod.OSK1Value);
            pushOS("K2 Value", iod.OSK2Value);
            pushOS("CYL Value", iod.OSCYLValue);
            pushOS("Corneal Thickness", iod.OSCornealThicknessValue);
            pushOS("SL Photo", iod.OSOCTMACFindings);
            pushOS("Lids", iod.OSLidsValue);
            pushOS("Conjunctiva", iod.OSConjunctivaValue);
            pushOS("Sclera", iod.OSScleraValue);
            pushOS("Cornea", iod.OSCorneaValue);
            pushOS("Endothelial Cell Count", iod.OSEndothelialCellCountValue);
            pushOS("Endothelial Corneal Thickness", iod.OSEndoCornealThicknessValue);
            pushOS("Endothelial Cell Density", iod.OSEndothelialCellDensity);
            pushOS("Fixation Loss", iod.OSFixationLoss);
            pushOS("False Positive Errors", iod.OSFalsePositiveErrors);
            pushOS("False Negative Errors", iod.OSFalseNegitiveErrors);
            pushOS("TD Probability Plot", iod.OSTDProbabilityPlot);
            pushOS("PD Probability Plot", iod.OSPDProbabilityPlot);
            pushOS("Mean Deviation", iod.OSMeanDeviation);
            pushOS("Pattern Std Deviation", iod.OSPatternStandardDeviation);
            pushOS("Visual Field Index", iod.OSVisualFieldIndex);
            pushOS("GHT Value", iod.OSGHTValue);
            pushOS("HVF Finding", iod.OSHVFFindingValue);
            pushOS("AS-OCT", iod.OSASOCTfindingValue);


            pushOS("ON Findings", osON);
            pushOS("Fundus Findings", osFundus);
            pushOS("FA", osFA);
            pushOS("ICG", osICG);


            if (os.length > 0) {
                out.push("\nOS -");
                os.forEach(x => out.push(x));
            }

            // ---- Files (OD / OS specific) ----
            let odFiles = getActiveFilesByEye(iod.PatientFiles, 1);
            let osFiles = getActiveFilesByEye(iod.PatientFiles, 2);
            let ouFiles = getActiveFilesByEye(iod.PatientFiles, 3);

            if (odFiles || osFiles || ouFiles) {
                out.push("\nFiles :");

                if (odFiles) {
                    out.push(`OD : ${odFiles}`);
                }

                if (osFiles) {
                    out.push(`OS : ${osFiles}`);
                }
                if (ouFiles) {
                    out.push(`OU : ${ouFiles}`);
                }
            }


            // ---- Technician / Provider ----
            if (iod.TechnicianName)
                out.push(`\nTechnician : ${iod.TechnicianName}`);

            if (iod.TechnicianRemarks)
                out.push(`Technician Notes : ${iod.TechnicianRemarks}`);

            if (iod.DoctorName)
                out.push(`Provider : ${iod.DoctorName}`);

            if (iod.ProviderRemarks)
                out.push(`Provider Notes : ${iod.ProviderRemarks}`);

            return out.join("\n");
        }

        function toNumber(val) {
            return val === null || val === undefined || val === "" ? null : Number(val);
        }

        function normalize(val) {
            if (val === null || val === undefined) return "";
            if (val === 0) return "";
            if (val === " ") return "";
            return val;
        }

        function pickInvestigationCompareFields(inv) {

            return {
                ProcedureCode: inv.ProcedureCode,
                Description: inv.Description,
                OrganId: toNumber(inv.OrganId),
                OrderDetails: (inv.OrderDetails || []).map(od => {

                    let formattedDate = od.DurationDate
                        ? $filter("date")(od.DurationDate, "MM-dd-yyyy")
                        : "";

                    return {
                        OrganId: toNumber(od.OrganId),
                        StatusId: od.StatusId,
                        Duration: od.Duration,
                        DurationType: od.DurationType,
                        DurationDate: formattedDate,
                        ModalityName: od.ModalityName,
                        ProviderRemarks: od.ProviderRemarks,
                        CoordinatorNotes: od.CoordinatorNotes,

                        DiagnosisList: (od.DiagnosisList || [])
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => ({
                                DiagnosisId: d.DiagnosisId,
                                ICD10CODE: d.ICD10CODE || d.ICDCode,
                                DiagnosisName: d.DiagnosisName
                            }))
                    };
                }),

                InvestigationOrderDetail: pickInterpretationCompareFields(inv.InvestigationOrderDetail)

            };
        }


