        $scope.compareProcedures = function () {

            const newList = $scope.cacheStorageItem.ProceduresDetails || [];
            const oldList = $scope.ExamLogObj.ProceduresDetails || [];

            let oldArr = [];
            let newArr = [];
            let deleteArr = [];
            let deletedCount = 0;
            let Ordersnames = '';

            // ---- Deleted ----
            oldList.forEach(old => {
                let exists = newList.find(n => n.PatientProcedureId == old.PatientProcedureId);
                if (!exists || exists.DeleteInd === "Y") {
                    if (deletedCount > 0) Ordersnames += ', ';
                    Ordersnames += `${old.ProcedureCode || ""} - ${old.Description || old.InvestigationName || ""}`;
                    // deleteArr.push(formatProcedure(old));
                    deletedCount++;
                }
            });

            // ---- Added & Edited ----
            newList.forEach(n => {

                if (n.DeleteInd === "Y") return;

                let old = oldList.find(o => o.PatientProcedureId == n.PatientProcedureId);

                if (!old) {
                    newArr.push(formatProcedure(n));   // Added
                    return;
                }

                let oldFields = pickProcedureCompareFields(old);
                let newFields = pickProcedureCompareFields(n);

                if (JSON.stringify(oldFields) !== JSON.stringify(newFields)) {
                    oldArr.push(formatProcedure(old));
                    newArr.push(formatProcedure(n));
                }
            });
            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Procedures",
                    ActionType: "Deleted",
                    OldActionDescription: Ordersnames,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            return {
                oldDescription: oldArr.join("\n\n").trim(),
                newDescription: newArr.join("\n\n").trim(),
            };
        };
        function formatProcedure(proc) {
            if (!proc) return "";

            let out = [];
            let organ =
                proc.OrganId == 1 ? "OD" :
                    proc.OrganId == 2 ? "OS" :
                        proc.OrganId == 3 ? "OU" : "";

            let header = `Procedure Name : ${proc.ProcedureCode || ""} - ${proc.Description || proc.ProcedureName || ""} (${organ})`;
            out.push(header);
            //let eye1 = proc.OrganId == 1 ? "OD" :
            //    proc.OrganId == 2 ? "OS" : "";
            //proc.OrganId == 3 ? "OU" : "";
            //out.push(eye1);
            (proc.OrderDetails || []).forEach(od => {
                if (od.DeleteInd == "Y") return;
                od.Duration = od.Duration || "";
                od.DurationType = od.DurationType || "";
                od.DurationDate = od.DurationDate || "";

                // Eye
                let eye = od.EyeOrder == 1 ? "First Eye" :
                    od.EyeOrder == 2 ? "Second Eye" : "";

                let organ = od.OrganId == 1 ? "OD" :
                    od.OrganId == 2 ? "OS" : "";
                od.OrganId == 3 ? "OU" : "";
                // Status
                let status = od.StatusId == 1 ? "Active" : "InActive";

                let schedule = "";
                if (od.DurationDate) {
                    schedule = $filter("date")(od.DurationDate, "MM-dd-yyyy");
                } else if (od.Duration && od.DurationType) {
                    let unit = "";
                    switch (od.DurationType) {
                        case "D": unit = "Days"; break;
                        case "W": unit = "Weeks"; break;
                        case "M": unit = "Months"; break;
                        case "Y": unit = "Years"; break;
                        case "SB": unit = "Since Birth"; break;
                    }
                    schedule = od.DurationType === "SB" ? "Since Birth" : `${od.Duration} ${unit}`;
                }

                out.push(` ${eye} : ${organ}`);
                out.push(`Scheduled on : ${schedule} , Status : ${status}`);

                // ---- Diagnosis ----
                //if (od.DiagnosisList && od.DiagnosisList.length > 0) {
                //    out.push("\nDiagnosis :");
                //    od.DiagnosisList.forEach(d => {
                //        out.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                //    });
                //}

                if (od.DiagnosisList && od.DiagnosisList.length > 0) {

                    const diagList = od.DiagnosisList.filter(d => d.DeleteInd === 'N');

                    if (diagList.length > 0) {
                        out.push("\nDiagnosis :");
                        diagList.forEach(d => {
                            out.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                        });
                    }
                }


                // if (od.CoordinatorNotes)
                out.push(`Notes To Co-Ordinator: ${od.CoordinatorNotes}`);
            });

            return out.join("\n");
        }

        function pickProcedureCompareFields(proc) {
            return {
                ProcedureCode: proc.ProcedureCode,
                Description: proc.Description,
                OrganId: toNumber(proc.OrganId),

                OrderDetails: (proc.OrderDetails || []).map(od => {
                    od.CoordinatorNotes = od.CoordinatorNotes || "";
                    let formattedDate = od.DurationDate
                        ? $filter("date")(od.DurationDate, "MM-dd-yyyy")
                        : "";

                    return {
                        OrganId: toNumber(od.OrganId),
                        EyeOrder: toNumber(od.EyeOrder),
                        StatusId: od.StatusId,
                        Duration: od.Duration,
                        DurationType: od.DurationType,
                        DurationDate: formattedDate,
                        CoordinatorNotes: od.CoordinatorNotes,

                        DiagnosisList: (od.DiagnosisList || [])
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => ({
                                DiagnosisId: d.DiagnosisId,
                                ICD10CODE: d.ICD10CODE || d.ICDCode,
                                DiagnosisName: d.DiagnosisName
                            }))
                    };
                })

            };
        }
        $scope.DeletedSurgeries = function () {

            const newList = $scope.cacheStorageItem.SurgeriesDetails || [];
            const oldList = $scope.ExamLogObj.SurgeriesDetails || [];

            let delArr = [];
            let deletedCount = 0;
            let Ordersnames = '';
            // Deleted
            oldList.forEach(o => {
                let exists = newList.find(n => n.PatientSurgeryId == o.PatientSurgeryId);
                if (!exists || exists.DeleteInd == "Y") {
                    if (deletedCount > 0) Ordersnames += ', ';
                    Ordersnames += `${o.ProcedureCode || ""} - ${o.Description || o.InvestigationName || ""}`;
                    deletedCount++;

                }
            });

            // Added / Edited
            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Surgeries",
                    ActionType: "Deleted",
                    OldActionDescription: Ordersnames,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
        };

        function PickSurgeryFields(sur) {
            return {

                OrganId: toNumber(sur.OrganId),
                ProcedureCode: sur.ProcedureCode,
                Description: sur.Description,

                OrderDetails: (sur.OrderDetails || []).map(od => ({
                    EyeOrder: toNumber(od.EyeOrder),
                    OrganId: Number(od.OrganId),
                    DeleteInd: od.DeleteInd,
                    // ----- Diagnosis -----
                    DiagnosisList: (od.DiagnosisList || [])
                        .filter(d => d.DeleteInd === "N")
                        .map(d => ({
                            DiagnosisId: d.DiagnosisId,
                            ICD10CODE: d.ICD10CODE || d.ICDCode,
                            DiagnosisName: d.DiagnosisName
                        })),

                    // ----- IOL -----
                    CoordinatorName: od.CoordinatorName,
                    ExternalCoManagerName: od.ExternalCoManagerName,
                    InternalCoManagerName: od.InternalCoManagerName,
                    CoordinatorNotes: od.CoordinatorNotes,

                    ProposedIOL: (od.ProposedIol || [])
                        .filter(x => x.DeleteInd === "N") // Only active IOLs
                        .map(p => p.CordinatorIOLType),

                    // ----- Status & Scheduling -----
                    StatusId: od.StatusId,
                    Duration: od.Duration,
                    DurationType: od.DurationType,
                    DurationDate: od.DurationDate
                        ? $filter("date")(od.DurationDate, "MM-dd-yyyy")
                        : "",
                }))
                // General Notes


            };
        }
        function PickCounsellingFields(sur) {
            return {
                OrganId: toNumber(sur.OrganId),
                ProcedureCode: sur.ProcedureCode,
                Description: sur.Description,

                OrderDetails: (sur.OrderDetails || []).map(od => ({

                    // OrganId: toNumber(od.OrganId),
                    CoordinatorOrganId: toNumber(od.CoordinatorOrganId),
                    DeleteInd: od.DeleteInd,
                    CoordinatorStatusId: normalize(od.CoordinatorStatusId),
                    EyeOrder: toNumber(od.EyeOrder),
                    Manufacturer: toNumber(od.Manufacturer),
                    CordinatorIOLType: toNumber(od.CordinatorIOLType),
                    Power: toNumber(od.Power),

                    FollowupDate: od.FollowupDate
                        ? $filter("date")(od.FollowupDate, "MM-dd-yyyy")
                        : "",

                    SurgeonName: toNumber(od.SurgeonName),
                    CoSurgeonName: toNumber(od.CoSurgeonName),
                    NurseName: toNumber(od.NurseName),
                    AnesthetistName: toNumber(od.AnesthetistName),
                    //Appointment details
                    PreAdmissionDate: od.PreAdmissionDate ? $filter("date")(od.PreAdmissionDate, "MM-dd-yyyy") : "",
                    AscAppointmentDate: od.AscAppointmentDate ? $filter("date")(od.AscAppointmentDate, "MM-dd-yyyy") : "",
                    FirstFollowupDate: od.FirstFollowupDate ? $filter("date")(od.FirstFollowupDate, "MM-dd-yyyy") : "",
                    SecondFollowupDate: od.SecondFollowupDate ? $filter("date")(od.SecondFollowupDate, "MM-dd-yyyy") : "",
                    ThirdFollowupDate: od.ThirdFollowupDate ? $filter("date")(od.ThirdFollowupDate, "MM-dd-yyyy") : "",
                    PreAdmissionStartTime: od.PreAdmissionStartTime ? $filter("date")(od.PreAdmissionStartTime, "hh:mm a") : "",
                    AscAppointmentStartTime: od.AscAppointmentStartTime ? $filter("date")(od.AscAppointmentStartTime, "hh:mm a") : "",
                    FirstFollowupStartTime: od.FirstFollowupStartTime ? $filter("date")(od.FirstFollowupStartTime, "hh:mm a") : "",
                    SecondFollowupStartTime: od.SecondFollowupStartTime ? $filter("date")(od.SecondFollowupStartTime, "hh:mm a") : "",
                    ThirdFollowupStartTime: od.ThirdFollowupStartTime ? $filter("date")(od.ThirdFollowupStartTime, "hh:mm a") : "",
                    GeneralNotes: od.GeneralNotes,
                }))
            };
        }

        function formatSurgeryDetails(sur) {
            if (!sur) return "";

            let out = [];
            let block = [];             // <-- NEW: temporary buffer
            let headerAdded = false;    // <-- NEW: flag

            const fmt = d => d ? $filter("date")(d, "MM-dd-yyyy") : "";

            function getDoctorName(list, id) {
                if (!id || !list || !list.length) return "";
                let f = list.find(x => x.DoctorID == id);
                return f ? f.FullName : "";
            }


            let organ =
                sur.OrganId == 1 ? "OD" :
                    sur.OrganId == 2 ? "OS" :
                        sur.OrganId == 3 ? "OU" : "";

            let headerLine = `Surgeory Name : ${sur.ProcedureCode || ""} - ${sur.Description || ""} (${organ})`;

            (sur.OrderDetails || []).forEach(od => {
                if (od.DeleteInd == "Y") return;

                od.DurationDate = od.DurationDate || "";
                od.Duration = od.Duration || "";
                od.DurationType = od.DurationType || "";
                od.ExternalCoManagerId = od.ExternalCoManagerId || 0;
                od.InternalCoManagerId = od.InternalCoManagerId || 0;
                od.CoordinatorNotes = od.CoordinatorNotes || "";
                od.CoordinatorName = od.CoordinatorName || "";

                let eyeOrder =
                    od.EyeOrder == 1 ? "First Eye" :
                        od.EyeOrder == 2 ? "Second Eye" : "";

                let eye =
                    od.OrganId == 1 ? "OD" :
                        od.OrganId == 2 ? "OS" :
                            od.OrganId == 3 ? "OU" : "";

                let part = [];

                part.push(`${eyeOrder} : ${eye}`);

                // Diagnosis
                //if (od.DiagnosisList && od.DiagnosisList.length > 0) {
                //    part.push("Diagnosis :");
                //    od.DiagnosisList.forEach(d => {
                //        part.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                //    });
                //}

                if (od.DiagnosisList && od.DiagnosisList.length > 0) {

                    let activeList = od.DiagnosisList.filter(d => d.DeleteInd === 'N');

                    if (activeList.length > 0) {
                        part.push("Diagnosis :");

                        activeList.forEach(d => {
                            part.push(`${d.ICD10CODE || d.ICDCode} | ${d.DiagnosisName}`);
                        });
                    }

                }


                let hasIol =
                    od.StatusId || od.DurationDate || od.Duration ||
                    od.DurationType || od.ExternalCoManagerId ||
                    od.InternalCoManagerId || od.CoordinatorNotes ||
                    (od.ProposedIol && od.ProposedIol.some(x => x.DeleteInd !== "Y"));

                if (hasIol) {
                    part.push("IOL details");

                    let status =
                        od.StatusId == 1 ? "Active" :
                            od.StatusId == 2 ? "InActive" : "";

                    part.push(`Co-Ordinator : ${od.CoordinatorName}`);
                    part.push(`Status : ${status}`);

                    let schedule = "";
                    if (od.DurationDate) {
                        schedule = fmt(od.DurationDate);
                    } else if (od.Duration && od.DurationType) {
                        let map = { D: "Days", W: "Weeks", M: "Months", Y: "Years", SB: "Since Birth" };
                        schedule = od.DurationType == "SB"
                            ? "Since Birth"
                            : `${od.Duration} ${map[od.DurationType]}`;
                    }

                    part.push(`Scheduled for : ${schedule}`);
                    let externalName = getDoctorName($scope.AllExternalCoordinatorList, od.ExternalCoManagerId);
                    let internalName = getDoctorName($scope.AllInternalCoordinatorList, od.InternalCoManagerId);

                    if (externalName)
                        part.push(`External Co-Manager : ${externalName}`);

                    if (internalName)
                        part.push(`Internal Co-Manager : ${internalName}`);

                    //part.push(`External Co-Manager : ${od.ExternalCoManagerName}`);
                    //part.push(`Internal Co-Manager : ${od.InternalCoManagerName}`);
                    let proposed = "";
                    if (od.ProposedIol && od.ProposedIol.some(x => x.DeleteInd !== "Y")) {
                        proposed = od.ProposedIol
                            .filter(x => x.DeleteInd !== "Y")
                            .map(x => x.CordinatorIOLType)
                            .join(", ");

                        //  part.push(`Proposed IOL : ${proposed}`);
                    }
                    part.push(`Proposed IOL : ${proposed}`);

                    part.push(`Notes to Co-ordinator : ${od.CoordinatorNotes}`);
                }

                if (part.length > 0) {

                    if (!headerAdded) {
                        out.push(headerLine);
                        headerAdded = true;
                    }

                    out.push(part.join("\n"));
                    out.push("");
                }
            });

            return out.join("\n");
        }



        function formatCounsellingDetails(sur) {

            if (!sur) return "";

            let out = [];
            let headerAdded = false;   // <-- added flag

            const fmt = d => d ? $filter("date")(d, "MM-dd-yyyy") : "";

            let organ =
                sur.OrganId == 1 ? "OD" :
                    sur.OrganId == 2 ? "OS" :
                        sur.OrganId == 3 ? "OU" : "";

            let line = `Surgeory Name : ${sur.ProcedureCode || ""} - ${sur.Description || ""} (${organ})`;

            (sur.OrderDetails || []).forEach(od => {

                od.CoordinatorStatusId = od.CoordinatorStatusId || 0;
                od.Manufacturer = od.Manufacturer || "";
                od.CordinatorIOLType = od.CordinatorIOLType || "";
                od.CoordinatorOrganId = od.CoordinatorOrganId || 0;
                od.Power = od.Power || "";
                od.SurgeonName = od.SurgeonName || "";
                od.CoSurgeonName = od.CoSurgeonName || "";
                od.NurseName = od.NurseName || "";
                od.AnesthetistName = od.AnesthetistName || "";
                od.PreAdmissionDate = od.PreAdmissionDate || null;
                od.PreAdmissionStartTime = od.PreAdmissionStartTime || null;
                od.AscAppointmentDate = od.AscAppointmentDate || null;
                od.AscAppointmentStartTime = od.AscAppointmentStartTime || null;
                od.FirstFollowupDate = od.FirstFollowupDate || null;
                od.FirstFollowupStartTime = od.FirstFollowupStartTime || null;
                od.SecondFollowupDate = od.SecondFollowupDate || null;
                od.SecondFollowupStartTime = od.SecondFollowupStartTime || null;
                od.ThirdFollowupStartTime = od.ThirdFollowupStartTime || null;
                od.ThirdFollowupDate = od.ThirdFollowupDate || null;
                od.FollowupDate = od.FollowupDate || null;
                od.GeneralNotes = od.GeneralNotes || "";

                // if (od.CoordinatorStatusId != 0) {
                if (od.DeleteInd == "Y") return;

                // Collect block lines temporarily
                let block = [];

                let eyeOrder =
                    od.EyeOrder == 1 ? "First Eye" :
                        od.EyeOrder == 2 ? "Second Eye" : "";

                let eye =
                    od.CoordinatorOrganId == 1 ? "OD" :
                        od.CoordinatorOrganId == 2 ? "OS" :
                            od.CoordinatorOrganId == 3 ? "OU" : "";

                block.push(`${eyeOrder} : ${eye}`);
                let counselStatus =
                    od.CoordinatorStatusId == 1 ? "Not Accepted" :
                        od.CoordinatorStatusId == 2 ? "Follow-Up" :
                            od.CoordinatorStatusId == 3 ? "Accepted" : "";
                //let counselStatus = { 1: "Not Accepted", 2: "Follow-Up", 3: "Accepted" }[od.CoordinatorStatusId];
                block.push(`Order Status : ${counselStatus}`);

                block.push(`Manufacturer : ${od.Manufacturer}`);
                block.push(`IOL Type : ${od.CordinatorIOLType}`);
                block.push(`IOL SEQ : ${od.Power}`);


                if (od.CoordinatorStatusId == 3) {
                    if (od.SurgeonName != " " || od.CoSurgeonName != " " || od.NurseName != " " || od.AnesthetistName != " ") {
                        block.push("Surgery Staff :");
                        block.push(`Doctor : ${od.SurgeonName}`);
                        block.push(`Additional Doctor : ${od.CoSurgeonName}`);
                        block.push(`Nurse : ${od.NurseName}`);
                        block.push(`Anesthetist : ${od.AnesthetistName}`);
                    }
                }

                let hasAppt =
                    od.PreAdmissionDate || od.AscAppointmentDate ||
                    od.FirstFollowupDate || od.SecondFollowupDate || od.ThirdFollowupDate;


                let preadmission = "";
                let surgery = "";
                let postop1 = "";
                let postop2 = "";
                let postop3 = "";
                if (od.PreAdmissionDate || od.PreAdmissionStartTime) {
                    preadmission = fmt(od.PreAdmissionDate) + " " + od.PreAdmissionStartTime;
                }
                if (od.AscAppointmentDate || od.AscAppointmentStartTime) {
                    surgery = fmt(od.AscAppointmentDate) + " " + od.AscAppointmentStartTime;
                }
                if (od.FirstFollowupDate || od.FirstFollowupStartTime) {
                    postop1 = fmt(od.FirstFollowupDate) + " " + od.FirstFollowupStartTime;
                }
                if (od.SecondFollowupDate || od.SecondFollowupStartTime) {
                    postop2 = fmt(od.SecondFollowupDate) + " " + od.SecondFollowupStartTime;
                }
                if (od.ThirdFollowupDate || od.ThirdFollowupStartTime) {
                    postop3 = fmt(od.ThirdFollowupDate) + " " + od.ThirdFollowupStartTime;
                }

                if (od.CoordinatorStatusId == 3) {
                    //if (hasAppt) {
                    block.push("Appointment Details :");

                    // if (od.PreAdmissionDate || od.PreAdmissionStartTime)
                    block.push(`Pre-Admission : ${preadmission}`);

                    //if (od.AscAppointmentDate || od.AscAppointmentStartTime)
                    block.push(`Surgery : ${surgery}`);

                    // if (od.FirstFollowupDate || od.FirstFollowupStartTime)
                    block.push(`Post-OP 1 : ${postop1}`);

                    // if (od.SecondFollowupDate || od.SecondFollowupStartTime)
                    block.push(`Post-OP 2 : ${postop2}`);

                    //  if (od.ThirdFollowupDate || od.ThirdFollowupStartTime)
                    block.push(`Post-OP 3 : ${postop3}`);
                    //   }
                }
                //if (hasAppt) {
                //    block.push("Appointment Details :");

                //    if (od.PreAdmissionDate || od.PreAdmissionStartTime)
                //        block.push(`Pre-Admission : ${fmt(od.PreAdmissionDate)} ${od.PreAdmissionStartTime}`);

                //    if (od.AscAppointmentDate || od.AscAppointmentStartTime)
                //        block.push(`Surgery : ${fmt(od.AscAppointmentDate)} ${od.AscAppointmentStartTime}`);

                //    if (od.FirstFollowupDate || od.FirstFollowupStartTime)
                //        block.push(`Post-OP 1 : ${fmt(od.FirstFollowupDate)} ${od.FirstFollowupStartTime}`);

                //    if (od.SecondFollowupDate || od.SecondFollowupStartTime)
                //        block.push(`Post-OP 2 : ${fmt(od.SecondFollowupDate)} ${od.SecondFollowupStartTime}`);

                //    if (od.ThirdFollowupDate || od.ThirdFollowupStartTime)
                //       block.push(`Post-OP 3 : ${fmt(od.ThirdFollowupDate)} ${od.ThirdFollowupStartTime}`);
                //}

                block.push(`GeneralNotes : ${od.GeneralNotes}`);
                if (od.CoordinatorStatusId == 2) {
                    // if (od.FollowupDate)
                    block.push(`Followup Date : ${fmt(od.FollowupDate)}`);
                }

                if (block.length > 0) {

                    if (!headerAdded) {
                        out.push(line);
                        headerAdded = true;
                    }

                    out.push(block.join("\n"));
                    out.push("");
                }
                //}
            });

            return out.join("\n");
        }

        $scope.CompareSurgeryDetails = function () {

            let oldList = $scope.ExamLogObj.SurgeriesDetails || [];
            let newList = $scope.cacheStorageItem.SurgeriesDetails || [];

            let oldDesc = "";
            let newDesc = "";

            newList.forEach(n => {
                if (n.DeleteInd == "Y") return;
                let o = oldList.find(x => x.PatientOrderId == n.PatientOrderId);

                if (!o) {
                    newDesc += (newDesc ? "\n\n" : "") + formatSurgeryDetails(n);
                } else {
                    // pick only comparable fields
                    let oldFields = PickSurgeryFields(o);
                    let newFields = PickSurgeryFields(n);

                    if (JSON.stringify(oldFields) !== JSON.stringify(newFields)) {
                        // Only here we include surgery block
                        oldDesc += (oldDesc ? "\n\n" : "") + formatSurgeryDetails(o);
                        newDesc += (newDesc ? "\n\n" : "") + formatSurgeryDetails(n);
                    }
                }
            });

            return { oldDescription: oldDesc, newDescription: newDesc };
        };

        $scope.CompareCounsellingDetails = function () {

            let oldList = $scope.ExamLogObj.SurgeriesDetails || [];
            let newList = $scope.cacheStorageItem.SurgeriesDetails || [];

            let oldDesc = "";
            let newDesc = "";

            newList.forEach(n => {
                if (n.DeleteInd == "Y") return;
                let o = oldList.find(x => x.PatientOrderId == n.PatientOrderId);

                if (!o) {
                    newDesc += (newDesc ? "\n\n" : "") + formatCounsellingDetails(n);
                } else {
                    let oldFields = PickCounsellingFields(o);
                    let newFields = PickCounsellingFields(n);

                    if (JSON.stringify(oldFields) !== JSON.stringify(newFields)) {
                        // Only here we include counselling block
                        oldDesc += (oldDesc ? "\n\n" : "") + formatCounsellingDetails(o);
                        newDesc += (newDesc ? "\n\n" : "") + formatCounsellingDetails(n);
                    }
                }
            });

            return { oldDescription: oldDesc, newDescription: newDesc };
        };


        $scope.compareReturnToOfficeDetails = function () {

            const newList = $scope.cacheStorageItem.ReturnToOfficeFollowupDetails || [];
            const oldList = $scope.ExamLogObj.ReturnToOfficeFollowupDetails || [];

            let oldDescArr = [];
            let newDescArr = [];
            let deleteArr = [];
            let deletedCount = 0;


            // DELETED
            oldList.forEach(o => {
                let exists = newList.find(n => n.FollowUpId == o.FollowUpId && n.DeleteInd !== "Y");
                if (!exists) {
                    deleteArr.push(formatRTO(o));
                    deletedCount++;
                }
            });

            // ADDED / UPDATED
            newList.forEach(n => {
                if (n.DeleteInd === "Y") return;

                const old = oldList.find(o => o.FollowUpId == n.FollowUpId);

                if (!old) {
                    // Added
                    newDescArr.push(formatRTO(n));
                } else {
                    old.FollowUpDuration = old.FollowUpDuration || null;
                    old.FollowUpDate = old.FollowUpDate || "";
                    n.FollowUpDuration = n.FollowUpDuration || null;
                    n.FollowUpDate = n.FollowUpDate || "";
                    const fOld = JSON.stringify({
                        d: old.FollowUpDate,
                        du: old.FollowUpDuration,
                        dut: old.FollowUpDurationType,
                        r: old.FollowUpVisitReasonName,
                        n: old.FollowUpNotes
                    });

                    const fNew = JSON.stringify({
                        d: n.FollowUpDate,
                        du: n.FollowUpDuration,
                        dut: n.FollowUpDurationType,
                        r: n.FollowUpVisitReasonName,
                        n: n.FollowUpNotes
                    });

                    if (fOld !== fNew) {
                        oldDescArr.push(formatRTO(old));
                        newDescArr.push(formatRTO(n));
                    }
                }
            });

            if (oldDescArr.length || newDescArr.length) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Return To Office",
                    ActionType: "Edited",
                    OldActionDescription: oldDescArr.join("\n\n"),
                    NewActionDescription: newDescArr.join("\n\n"),
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }

            // DELETED LOG
            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Return To Office",
                    ActionType: "Deleted",
                    OldActionDescription: deleteArr.join("\n\n"),
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
        };

        function formatRTO(item) {
            if (!item) return "";
            item.FollowUpDate = $filter('date')(item.FollowUpDate, "MM-dd-yyyy") || null;
            let out = "Return To Office :";

            // Onset
            let schedule = "";
            if (item.FollowUpDate) {
                schedule = item.FollowUpDate; // already in MM-dd-yyyy
            } else if (item.FollowUpDuration && item.FollowUpDurationType) {
                const map = { D: "Days", W: "Weeks", M: "Months", Y: "Years", SB: "Since Birth" };
                schedule = item.FollowUpDurationType === "SB"
                    ? "Since Birth"
                    : `${item.FollowUpDuration} ${map[item.FollowUpDurationType]}`;
            }
            if (schedule) out += ` Onset : ${schedule}`;

            // FollowUp Reason
            if (item.FollowUpVisitReasonName)
                out += ` , Followup Visit Reason : ${item.FollowUpVisitReasonName}`;

            // Notes
            if (item.FollowUpNotes)
                out += ` , Notes : ${item.FollowUpNotes}`;

            return out;
        }
        $scope.compareReferralDetails = function () {
            let oldList = $scope.ExamLogObj.ReferralDetails || [];
            let newList = $scope.cacheStorageItem.ReferralDetails || [];

            let oldDesc = "";
            let newDesc = "";
            let deletedCount = 0;
            let Ordersnames = "";
            oldList.forEach(old => {
                let exists = newList.find(n => n.PatientReferralDetailId == old.PatientReferralDetailId);
                if (!exists || exists.DeleteInd === "Y") {
                    Ordersnames += `${old.Referral}`;
                    deletedCount++;

                }
            });
            // Convert to simple comparable objects
            let oldMapped = oldList.map(r => pickReferralFields(r, $filter));
            let newMapped = newList.map(r => pickReferralFields(r, $filter));

            newList.forEach((refItem, i) => {
                if (refItem.DeleteInd == "Y") return;
                let oldMatch = oldMapped[i];
                let newMatch = newMapped[i];

                if (!oldMatch) {
                    // Added
                    let desc = formatReferral(refItem, $filter);
                    newDesc += (newDesc ? "\n\n" : "") + desc;
                    return;
                }

                // Edited?
                if (JSON.stringify(oldMatch) !== JSON.stringify(newMatch)) {
                    let oldRefObj = oldList[i];
                    let newRefObj = newList[i];

                    let oldFormatted = formatReferral(oldRefObj, $filter);
                    let newFormatted = formatReferral(newRefObj, $filter);

                    oldDesc += (oldDesc ? "\n\n" : "") + oldFormatted;
                    newDesc += (newDesc ? "\n\n" : "") + newFormatted;
                }
            });


            if (deletedCount > 0) {
                $scope.ExamLogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 54,
                    SubModuleName: "Orders",
                    ScreenType: "Refferal",
                    ActionType: "Deleted",
                    OldActionDescription: Ordersnames,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            return {
                oldDescription: oldDesc,
                newDescription: newDesc,
            };
        };
        function formatReferral(ref, $filter) {
            if (!ref) return "";

            let out = [];

            out.push("Referral :");
            out.push(`${ref.Referral || ref.Description || ""}`);

            // Internal / External
            let typeCode = ref.Type === "External" ? "EXT" : "INT";
            if (ref.ReferralDoctorName) {
                out.push(`Internal Doctor : ${typeCode} Dr. ${ref.ReferralDoctorName}`);
            }

            // Scheduled Date
            if (ref.DurationDate) {
                out.push(`Scheduled On : ${$filter("date")(ref.DurationDate, "MM-dd-yyyy")}`);
            } else if (ref.Duration && ref.DurationType) {
                let map = { D: "Days", W: "Weeks", M: "Months", Y: "Years" };
                let unit = map[ref.DurationType] || "";
                out.push(`Scheduled On : ${ref.Duration} ${unit}`);
            }

            if (ref.IsUrgency) out.push("Urgent Referral : Yes");
            if (ref.IsFollowUpAfterReferral) out.push("Follow Up After Referral : Yes");

            // Diagnosis
            let od = (ref.OrderDetails && ref.OrderDetails[0]) || {};
            if (od.DiagnosisList && od.DiagnosisList.length > 0) {
                out.push("Diagnosis :");
                od.DiagnosisList
                    .filter(d => d.DeleteInd === "N")
                    .forEach(d => {
                        out.push(`${d.ICD10CODE || d.ICDCode} - ${d.DiagnosisName}`);
                    });
            }

            // Reason For Referral
            if (ref.ReferralReason) {
                out.push("");
                out.push(`Reason for Referral :${ref.ReferralReason}`);
            }

            return out.join("\n");
        }
        function pickReferralFields(r, $filter) {
            let od = (r.OrderDetails && r.OrderDetails[0]) || {};
            r.Duration = r.Duration || "";
            return {
                Referral: r.Referral,
                ReferralDoctorName: r.ReferralDoctorName,
                Type: r.Type,
                IsUrgency: r.IsUrgency,
                IsFollowUpAfterReferral: r.IsFollowUpAfterReferral,
                Duration: r.Duration,
                DurationType: r.DurationType,
                DurationDate: r.DurationDate ? $filter("date")(r.DurationDate, "MM-dd-yyyy") : "",
                ReferralReason: r.ReferralReason,

                DiagnosisList: (od.DiagnosisList || [])
                    .filter(x => x.DeleteInd === "N")
                    .map(d => ({
                        DiagnosisId: d.DiagnosisId,
                        ICD10CODE: d.ICD10CODE || d.ICDCode,
                        DiagnosisName: d.DiagnosisName
                    }))
            };
        }
