        console.log(isTouchDevice);
        function initializeDeviceCheck() {
            var resizeTimer;

            function isTouchDevice() {
                return (
                    (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) ||
                    navigator.maxTouchPoints > 1 ||
                    'ontouchstart' in window
                );
            }

            // screen.width is zoom-independent (browser zoom changes innerWidth, NOT screen.width)
            function getPhysicalWidth() {
                return window.screen.width || window.innerWidth;
            }

            $scope.checkDevice = function () {
                var physicalWidth = getPhysicalWidth();
                var touch = isTouchDevice();

                // Real tablet ONLY if it's a touch device AND in the 768-1366 physical width range
                $scope.isTablet = true;

                if ($scope.isTablet) {
                    if (
                        !$scope.selectedAnteriorItem &&
                        $scope.AnteriorSegmentArrayNew &&
                        $scope.AnteriorSegmentArrayNew.length > 0
                    ) {
                        var filtered = $scope.AnteriorSegmentArrayNew.filter(function (x) {
                            return x.ActiveInd === 'Y';
                        });
                        $scope.selectedAnteriorItem = filtered[0];
                        $scope.activeAnteriorIndex = 0;
                        $scope.activeAnteriorId = filtered[0].InvestigationId;
                        $scope.ExamTab = 1;
                        $scope.anteriorSearch.query = '';
                    }

                    if (
                        !$scope.selectedPosteriorItem &&
                        $scope.PoteriorSegmentArrayNew &&
                        $scope.PoteriorSegmentArrayNew.length > 0
                    ) {
                        var filteredP = $scope.PoteriorSegmentArrayNew.filter(function (x) {
                            return x.ActiveInd === 'Y';
                        });
                        $scope.selectedPosteriorItem = filteredP[0];
                        $scope.activePosteriorIndex = 0;
                        $scope.activePosteriorId = filteredP[0].InvestigationId;
                        $scope.posteriorSearch.query = '';
                    }

                    $scope.summaryState.isOn = false;
                }
            };

            $scope.checkDevice();

            // Debounced resize - performance safe, every pixel మీద fire అవ్వదు
            function debouncedResize() {
                clearTimeout(resizeTimer);
                resizeTimer = setTimeout(function () {
                    $scope.$apply(function () {
                        $scope.checkDevice();
                    });
                }, 150);
            }

            angular.element($window).bind('resize orientationchange', debouncedResize);

            // Memory leak avoid చేయడానికి cleanup - controller destroy అయినప్పుడు listener తీసేయాలి
            $scope.$on('$destroy', function () {
                angular.element($window).unbind('resize orientationchange', debouncedResize);
                clearTimeout(resizeTimer);
            });
        }
        initializeDeviceCheck();

