        /* Add as Template: the section's points as rows of the new template - only the points still shown (not removed,
       not the empty input row), and without the visit's row ids (those belong to the visit's notes, not to the template) */
        function templateRowsFrom(rows, idKey, textKey) {
            var templateRows = [];
            angular.forEach(rows || [], function (row) {
                if (row && row.DeleteInd !== 'Y' && String(row[textKey] || '').trim()) {
                    var templateRow = angular.copy(row);
                    templateRow[idKey] = 0;
                    templateRow.DeleteInd = 'N';
                    templateRows.push(templateRow);
                }
            });
            return templateRows;
        }


        $scope.SaveDiscussionsTemplate = function (val) {
            var TempPodList = $filter("filter")($scope.AssessmentplanpopupObj.AssessmentListArray, { "IsEditData": true }, true);
            val = TempPodList[0].AssessmentPlan.PlanofDiscussionsNotes || '';
            if ($scope.assonj.EnterPlanOfDiscussionsTemplateName == '') {
                alertify.error('Enter Template Name');
                return;
            }
            if (val == '') {
                alertify.error('Enter Plan Of Discussions ');
                return;
            }
            var object = {
                "UserId": $scope.UserId,
                "OrganizationId": $scope.HospitalId,
                "TemplateId": 0,
                "TemplateName": $scope.assonj.EnterPlanOfDiscussionsTemplateName || "",
                "PlanofDiscussionsNotes": val || "",
                "DeleteInd": "N",
                "PlanArray": templateRowsFrom(TempPodList[0].AssessmentPlan.PlanArray, "AssessmentPlanNotesId", "AssessmentPlanNotes"),

            }
            eHnoteSettingsDataService.AddUpdatePlanofDiscussionTemplates(object).success(function (resp) {
                if (resp.Status === 'Success') {
                    alertify.success("Successfully Added");
                    let LogItem = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 53,
                        "SubModuleName": "Assessment Plan",
                        "ScreenType": "Plan Template",
                        "ActionType": "Added",
                        "OldActionDescription": "",
                        "NewActionDescription": `Tempalte Name :${$scope.assonj.EnterPlanOfDiscussionsTemplateName} \n Notes :${val}`,
                    }
                    $scope.AddAuditLogNew(LogItem);
                    $scope.templatesaveclick();
                    $scope.GetUserConsultationTemplateDetails();
                    $scope.assonj.EnterPlanOfDiscussionsTemplateName = "";
                    $scope.assonj.IsPlanOfDiscussionTemplateSavePopOver = false;
                } else {
                    alertify.error(resp.Message);
                }
            })
                .error(function (error) {
                    alertify.error("Error Occured");
                });
        }
