        $scope.Mapdiagnosis = function (item, orditem) {


            //var TempDiagnosisArray = $filter("filter")($scope.AdvisedOrderDetailsArray, { "IsEditData": true }, true);
            orditem.DiagnosisList = orditem.DiagnosisList || [];
            if (orditem.DiagnosisList.length > 0) {


                if (item.IsCheckedDiagnosis) {
                    var obj = {
                        "DiagnosisDetailId": 0,
                        "DiagnosisId": item.DiagnosisId,
                        "PatientOrderId": orditem.PatientOrderId,
                        "AssessmentPlanId": item.AssessmentPlan.AssessmentPlanId,
                        "ConsultationDiagnosisId": item.ConsultationDiagnosisId,
                        "DiagnosisName": item.DiagnosisName || '',
                        "ICDCode": item.ICD10CODE || '',
                        "ActiveInd": "Y",
                        "IsChecked": true,
                        "DeleteInd": item.DeleteInd || 'N',
                        "ICD10CODE": item.ICD10CODE || "",
                        "Diagnosis": true,
                    }
                    if (obj.DiagnosisName == '') {
                        obj.DiagnosisName = item.ICD10DIAGDESCRIPTION || '';
                    }

                    item.DiagnosisId = item.DiagnosisId || 0;
                    item.SnomedCodeId = item.SnomedCodeId || 0;
                    if (item.DiagnosisId !== 0) {
                        var TempDiagnosisDiagnosisArray = $filter("filter")(orditem.DiagnosisList, { "DiagnosisId": item.DiagnosisId, "DeleteInd": 'N' }, true);
                        if (TempDiagnosisDiagnosisArray.length == 0) {
                            orditem.DiagnosisList.push(obj);
                        }
                    }
                    if (item.SnomedCodeId !== 0) {
                        var TempSnomedDiagnosisArray = $filter("filter")(orditem.DiagnosisList, { "DiagnosisId": item.SnomedCodeId, "DeleteInd": 'N' }, true);
                        if (TempSnomedDiagnosisArray.length == 0) {
                            orditem.DiagnosisList.push(obj);
                        }
                    }

                } else {
                    // var TempDiagnosisDiagnosisArray = $filter("filter")(TempDiagnosisArray[0].DiagnosisList, { "DiagnosisId": item.DiagnosisId }, true);
                    if (orditem.DiagnosisList.length != 0) {
                        angular.forEach(orditem.DiagnosisList, function (Aitem, index) {
                            item.DiagnosisId = item.DiagnosisId || 0;
                            item.SnomedCodeId = item.SnomedCodeId || 0;
                            if (item.DiagnosisId !== 0) {
                                if (Aitem.DiagnosisId == item.DiagnosisId) {
                                    if (Aitem.DiagnosisDetailId == 0) {
                                        orditem.DiagnosisList.splice(index, 1);
                                    } else {
                                        Aitem.DeleteInd = 'Y';
                                        Aitem.ActiveInd = 'N';
                                    }

                                }
                            }

                            if (item.SnomedCodeId !== 0) {
                                if (Aitem.DiagnosisDetailId == 0) {
                                    orditem.DiagnosisList.splice(index, 1);
                                } else {
                                    Aitem.DeleteInd = 'Y';
                                    Aitem.ActiveInd = 'N';
                                }
                            }

                        });

                    }

                }
            } else {
                //item.IsCheckedDiagnosis = false;
                //alertify.error("Select Edit Order To Map Diagnosis");
                var obj = {
                    "DiagnosisDetailId": 0,
                    "DiagnosisId": item.DiagnosisId,
                    "PatientOrderId": orditem.PatientOrderId,
                    "AssessmentPlanId": item.AssessmentPlan.AssessmentPlanId,
                    "ConsultationDiagnosisId": item.ConsultationDiagnosisId,
                    "DiagnosisName": item.DiagnosisName || '',
                    "ICDCode": item.ICD10CODE || '',
                    "ActiveInd": "Y",
                    "IsChecked": true,
                    "DeleteInd": item.DeleteInd || 'N',
                    "ICD10CODE": item.ICD10CODE || "",
                    "Diagnosis": true,
                }
                if (obj.DiagnosisName == '') {
                    obj.DiagnosisName = item.ICD10DIAGDESCRIPTION || '';
                }

                item.DiagnosisId = item.DiagnosisId || 0;
                item.SnomedCodeId = item.SnomedCodeId || 0;
                if (item.DiagnosisId !== 0) {

                    orditem.DiagnosisList.push(obj);
                }
                if (item.SnomedCodeId !== 0) {

                    orditem.DiagnosisList.push(obj);

                }

            }

        }


