                "DiagnosisNotes": '',
                "ActiveInd": mainobject.ActiveInd || "Y",
                "IsChecked": true,
                "DeleteInd": mainobject.DeleteInd || 'N',
                "ICD10CODE": newAssessmentObj.ICD10CODE || "",
                "DiagnosisCode": newAssessmentObj.ICD10CODE || "",
