        $scope.ChangeNewSearchValue = function (catid, Mitem, type) {
            Mitem.ShowAddNewBtnAntOD = false;
            Mitem.ShowAddNewBtnAntOS = false;
            Mitem.ShowAddNewBtnPostOD = false;
            Mitem.ShowAddNewBtnPostOS = false;

            if (catid == 5) {
                if (type == 'OD') {

                    var exactMatch = $scope.NewAnteriorFindingsMasterArray.some(function (item) {
                        return item.FindingValue && item.FindingValue.toLowerCase() === Mitem.ODSearchObj.toLowerCase();
                    });

                    Mitem.ShowAddNewBtnAntOD = !exactMatch;
                } else {

                    var exactMatch = $scope.NewAnteriorFindingsMasterArray.some(function (item) {
                        return item.FindingValue && item.FindingValue.toLowerCase() === Mitem.OSSearchObj.toLowerCase();
                    });

                    Mitem.ShowAddNewBtnAntOS = !exactMatch;
                }
            }
            else if (catid == 6) {
                if (type == 'OD') {
                    var exactMatch = $scope.NewPosteriorFindingsMasterArray.some(function (item) {
                        return item.FindingValue && item.FindingValue.toLowerCase() === Mitem.ODSearchObj.toLowerCase();
                    });

                    Mitem.ShowAddNewBtnPostOD = !exactMatch;
                } else {
                    var exactMatch = $scope.NewPosteriorFindingsMasterArray.some(function (item) {
                        return item.FindingValue && item.FindingValue.toLowerCase() === Mitem.OSSearchObj.toLowerCase();
                    });

                    Mitem.ShowAddNewBtnPostOS = !exactMatch;
                }
            }

        }


        $scope.ChangeCheckboxFindingASValue = function (item, catid, type) {
            catid = catid || '';
            type = type || '';
            var count = [];
            var i = 0;
            if (type == 'OD') {
                var Organid = 1;
            }
            else {
                var Organid = 2;
            }
            if (item.IsChecked) {
                angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                    if (Mitem.RemarksArray.length > 0 && Mitem.InvestigationId !== 6 && Mitem.InvestigationId !== 7 && Mitem.InvestigationId !== 9 && Mitem.InvestigationId !== 10 && Mitem.InvestigationId !== 31) {
                        count = $filter("filter")(Mitem.RemarksArray, function (fitem, index) { return fitem.InvFindingId === item.InvFindingId && fitem.OrganId === Organid && fitem.ActiveInd == 'Y' });
                        if (count.length !== 0) {
                            i++;
                        }
                    }
                    else if (Mitem.RemarksArray.length == 0 && Mitem.InvestigationId == 6 && Mitem.InvestigationId == 7 && Mitem.InvestigationId == 9 && Mitem.InvestigationId == 10 && Mitem.InvestigationId == 31) {

                    }
                });
            }
            if (i !== 0) {
                item.IsChecked = false;
                alertify.error("This Item is Already Added");
                return false;
            }

            if (type == 'OD') {
                $scope.newAnteriorObj.AnteriorSearchObj = item;
                $scope.ChangeFindingASValue1($scope.newAnteriorObj, $scope.newAnteriorObj.AnteriorSearchObj, catid, type);
            } else {
                $scope.newAnteriorObj.OSAnteriorSearchObj = item;
                $scope.ChangeFindingASValue1($scope.newAnteriorObj, $scope.newAnteriorObj.OSAnteriorSearchObj, catid, type);
            }

        }
        $scope.ChangeCheckboxFindingPSValue = function (item, catid, type) {
            catid = catid || '';
            type = type || '';
            var count = [];
            var i = 0;

            if (type == 'OD') {
                var Organid = 1;
            }
            else {
                var Organid = 2;
            }
            if (item.IsChecked) {
                angular.forEach($scope.PoteriorSegmentArrayNew, function (Mitem) {
                    if (Mitem.RemarksArray.length > 0) {
                        count = $filter("filter")(Mitem.RemarksArray, function (fitem, index) { return fitem.InvFindingId === item.InvFindingId && fitem.OrganId === Organid && fitem.ActiveInd == 'Y' });
                        if (count.length !== 0) {
                            i++;
                        }
                    }
                });
            }
            if (i !== 0) {
                item.IsChecked = false;
                //$scope.newAnteriorObj.AnteriorSearchObj = '';
                //$scope.newAnteriorObj.OSAnteriorSearchObj = '';
                alertify.error("This Item is Already Added");
                return false;
            }
            if (item.IsChecked) {
                if (type == 'OD') {
                    $scope.newPosteriorObj.PosteriorSearchObj = item;
                    $scope.ChangeFindingPSValue($scope.newPosteriorObj, $scope.newPosteriorObj.PosteriorSearchObj, catid, type);
                } else {
                    $scope.newPosteriorObj.OSPosteriorSearchObj = item;
                    $scope.ChangeFindingPSValue($scope.newPosteriorObj, $scope.newPosteriorObj.OSPosteriorSearchObj, catid, type);
                }
            }
            else {
                angular.forEach($scope.PoteriorSegmentArrayNew, function (mitem, index) {
                    var PoteriorArray = [], Index = ''
                    PoteriorArray = $filter("filter")(mitem.RemarksArray, { "InvFindingId": item.InvFindingId, "OrganId": Organid }, true) || [];
                    /*if (AnteriorArray.length > 0) {*/
                    Index = index

                    //}
                    if (PoteriorArray.length > 0) {
                        if (catid == 6) {
                            if (type == 'OD') {
                                if (item.FindingId !== 32) {
                                    $scope.removeRightAnteriorNew(PoteriorArray[0], $scope.PoteriorSegmentArrayNew[Index]);
                                }
                                //else {
                                //    $scope.deleteRightPosterior($scope.AnteriorSegmentArrayNew[Index]);
                                //}
                            }
                            else if (type == 'OS') {
                                if (item.FindingId !== 32) {
                                    $scope.removeLeftAnteriorNew(PoteriorArray[0], $scope.PoteriorSegmentArrayNew[Index]);
                                }
                                //else {
                                //    $scope.deleteLeftPosterior($scope.AnteriorSegmentArrayNew[Index]);
                                //}
                            }
                        }
                    }

                });
            }
        }

