        $scope.GetAnteriorOrgFindingValues = function () {


            //$scope.SearchText = val || "";
            //$scope.CategoryId = Catid || 0;
            //$scope.FindingId = FindingId || 0;
            //$scope.type = type || "";
            var params = {
                "CategoryId": 5,
                "FindingId": 0,
                "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "PageSize": 4000,
                "PageNumber": 1,
                "SearchText": "",
            }
            return eHnotePatientDataService.GetOrgFindingValues(params).then(function (resp) {
                if (resp.data.status === "Success") {
                    if (resp.data.rows !== undefined) {
                        $scope.AnteriorINVDropdownListMain = resp.data.rows || [];
                        $scope.AnteriorRightEyeArray = angular.copy(resp.data.rows) || [];
                        $scope.AnteriorLeftEyeArray = angular.copy(resp.data.rows) || [];
                        $scope.MRDvaluesFilteredArray = (resp.data.rows || []).filter(function (item) {
                            return item.FindingId === 6 || item.FindingId === 7 || item.FindingId === 9 || item.FindingId === 10 || item.FindingId === 31;
                        });

                        let allAnteriorData = resp.data.rows || [];
                        let TempAnteriorfavariotes = allAnteriorData.filter(item => item.IsFavoriteInd);
                        //let nonFavorites = allAnteriorData.filter(item => !item.IsFavoriteInd);

                        let nonFavorites = allAnteriorData.filter(item => !item.IsFavoriteInd).reverse();

                        $scope.NewAnteriorFindingsMasterArray = TempAnteriorfavariotes.concat(nonFavorites);

                        $scope.Anteriorfavariotes = angular.copy(TempAnteriorfavariotes) || [];
                        $scope.AnteriorLeftfavariotes = angular.copy(TempAnteriorfavariotes) || [];
                        angular.forEach($scope.Anteriorfavariotes, function (item) {
                            item.IsChecked = false;
                        });
                        angular.forEach($scope.AnteriorLeftfavariotes, function (item) {
                            item.IsChecked = false;
                        });
                        $scope.ExamLogObj.Anteriorfavariotes = $scope.ExamLogObj.Anteriorfavariotes || [];
                        $scope.ExamLogObj.Anteriorfavariotes = angular.copy(TempAnteriorfavariotes) || [];

                        angular.forEach($scope.AnteriorSegmentArrayNew, function (mainitem) {
                            mainitem.ODSearchObj = '';
                            mainitem.OSSearchObj = '';
                            angular.forEach(mainitem.RemarksArray, function (Aitem) {

                                if (Aitem.OrganId == 1 && Aitem.ActiveInd == "Y") {
                                    angular.forEach($scope.Anteriorfavariotes, function (item, index) {
                                        if (Aitem.InvFindingId == item.InvFindingId) {
                                            item.IsChecked = true;
                                        }
                                    });
                                }
                                else if (Aitem.OrganId == 2 && Aitem.ActiveInd == "Y") {
                                    angular.forEach($scope.AnteriorLeftfavariotes, function (item, index) {
                                        if (Aitem.InvFindingId == item.InvFindingId) {
                                            item.IsChecked = true;
                                        }
                                    });
                                }

                            });
                        });

                        angular.forEach($scope.AnteriorRightEyeArray, function (item) {
                            item.IsChecked = false;
                        });
                        angular.forEach($scope.AnteriorLeftEyeArray, function (item) {
                            item.IsChecked = false;
                        });
                        //$scope.AnteriorSegmentArrayNew = $scope.AnteriorSegmentArrayNew || [];
                        //if ($scope.AnteriorSegmentArrayNew.length > 0) {
                        //    angular.forEach($scope.AnteriorRightEyeArray, function (ritem) {
                        //        angular.forEach($scope.AnteriorSegmentArrayNew, function (item) {
                        //            if (item.RemarksArray.length > 0) {
                        //                angular.forEach(item.RemarksArray, function (mitem) {
                        //                    if (mitem.InvFindingId == ritem.InvFindingId && mitem.OrganId == 1 && mitem.RemarksId == 0) {
                        //                        ritem.IsChecked = true;
                        //                    }
                        //                });
                        //            }

                        //        });
                        //    });

                        //    angular.forEach($scope.AnteriorLeftEyeArray, function (ritem) {
                        //        angular.forEach($scope.AnteriorSegmentArrayNew, function (item) {
                        //            if (item.RemarksArray.length > 0) {
                        //                angular.forEach(item.RemarksArray, function (mitem) {
                        //                    if (mitem.InvFindingId == ritem.InvFindingId && mitem.OrganId == 2 && mitem.RemarksId == 0) {
                        //                        ritem.IsChecked = true;
                        //                    }
                        //                });
                        //            }

                        //        });
                        //    });
                        //}

                        $scope.AnteriorINVDropdownList = angular.copy($scope.AnteriorINVDropdownListMain);

                        angular.forEach($scope.AnteriorSegmentArrayNew, function (mitem) {
                            if (mitem.RemarksArray.length > 0) {
                                angular.forEach(mitem.RemarksArray, function (subitem) {
                                    subitem.IsFavoriteInd = false;
                                });
                            }
                        });

                        angular.forEach($scope.AnteriorSegmentArrayNew, function (mitem) {
                            if (mitem.RemarksArray.length > 0) {
                                angular.forEach(mitem.RemarksArray, function (subitem) {
                                    if (subitem.OrganId == 1 && subitem.ActiveInd == "Y") {
                                        let match = $scope.Anteriorfavariotes.filter(function (localItem) {
                                            return localItem.InvFindingId == subitem.InvFindingId;
                                        }) || [];
                                        if (match.length > 0) {
                                            subitem.IsFavoriteInd = true;
                                        }
                                    } else if (subitem.OrganId == 2 && subitem.ActiveInd == "Y") {
                                        let match = $scope.AnteriorLeftfavariotes.filter(function (localItem) {
                                            return localItem.InvFindingId == subitem.InvFindingId;
                                        }) || [];
                                        if (match.length > 0) {
                                            subitem.IsFavoriteInd = true;
                                        }
                                    }

                                });
                            }

                        });
                    }
                    $scope.newAnteriorObj.ShowAddNewBtnAntOD = false;
                    $scope.newAnteriorObj.ShowAddNewBtnAntOS = false;

                }

            });
        }
