                        "InvestigationDesc": "CDR",
                        "RHorizontal": '',
                        "LHorizontal": '',
                        "RVertical": '',
                        "LVertical": '',
                        "RDPS": '',
                        "LDPS": '',
                        "RemarksArray": [],
