        $scope.isFreelyMoving = function (gazeObj) {

            if (!gazeObj) return false;

            var isFree = true;

            angular.forEach(gazeObj, function (position, key) {

                if (key.indexOf("Id") !== -1 || key === "DeleteInd") {
                    return;
                }

                if (position.H) {
                    if (position.H.Amount !== 0 || position.H.Direction !== "None") {
                        isFree = false;
                    }
                }

                if (position.V) {
                    if (position.V.Amount !== 0 || position.V.Direction !== "None") {
                        isFree = false;
                    }
                }

            });

            return isFree;
        };

