        function buildPairedRemarks(item) {
            var odList = (item.RemarksArray || []).filter(function (r) {
                return r.OrganId === 1 && r.ActiveInd === 'Y' && !r.IsFavoriteInd;
            });
            var osList = (item.RemarksArray || []).filter(function (r) {
                return r.OrganId === 2 && r.ActiveInd === 'Y' && !r.IsFavoriteInd;
            });

            var maxLen = Math.max(odList.length, osList.length);
            var paired = [];
            for (var i = 0; i < maxLen; i++) {
                paired.push({ od: odList[i] || null, os: osList[i] || null });
            }
            item.PairedRemarks = paired;
        }

        function rebuildAllPairedRemarks(segmentArray) {
            angular.forEach(segmentArray || [], function (item) {
                buildPairedRemarks(item);
            });
        }
        function chunkArray(arr, chunkSize) {
            let chunkedArray = [];
            for (let i = 0; i < arr.length; i += chunkSize) {
                chunkedArray.push(arr.slice(i, i + chunkSize));
            }
            return chunkedArray;
        }
