        $scope.changePossibleDiagnosisright1 = function (item, bool) {
            var checkedArray = _.where($scope.RightPossibleDiagnosisArray, { IsRightSelected: true });
            $scope.Status.AllStatusCheck = checkedArray.length > 0 && $scope.RightPossibleDiagnosisArray.length === checkedArray.length ? true : false;
            if ($scope.Status.AllStatusCheck) {
                $scope.Status.RightSelectStatusString = 'All';
            }

            if (!$scope.Status.AllStatusCheck && checkedArray.length > 0) {
                $scope.Status.RightSelectStatusString = 'Selected';
            }

            if ($scope.RightPossibleDiagnosisArray.length > 0) {
                angular.forEach($scope.RightPossibleDiagnosisArray, function (mitem) {
                    var existingItem = item.RightEye.RightEyePossibleDiagnosisArray.find(function (obj) {
                        return obj.PossibleDiagnosisName === mitem.DiagnosisName;
                    });

                    if (mitem.IsRightSelected === true) {
                        if (!existingItem) { // If no existing object, add the new one
                            var obj = {
                                "GonioscopyPossibleDiagnosisId": 0,
                                "PossibleDiagnosisName": mitem.DiagnosisName,
                                "PossibleDiagnosisId": mitem.DiagnosisId,
                                // "IsRightSelected": mitem.IsRightSelected,
                                "ICD10CODE": mitem.ICD10CODE,
                                "DeleteInd": 'N'
                            };
                            item.RightEye.RightEyePossibleDiagnosisArray.push(obj);
                        } else {
                            // Optionally, update the existing object if necessary
                            //existingItem.IsRightSelected = true;
                            existingItem.DeleteInd = 'N';
                        }
                    } else if (mitem.IsRightSelected === false && (mitem.GonioscopyPossibleDiagnosisId != 0 && mitem.GonioscopyPossibleDiagnosisId != undefined)) {
                        if (!existingItem) { // If no existing object, add it with DeleteInd 'Y'
                            var obj = {
                                "GonioscopyPossibleDiagnosisId": mitem.GonioscopyPossibleDiagnosisId,
                                "PossibleDiagnosisName": mitem.DiagnosisName,
                                "PossibleDiagnosisId": mitem.DiagnosisId,
                                //"IsRightSelected": mitem.IsRightSelected,
                                "ICD10CODE": mitem.ICD10CODE,
                                "DeleteInd": 'Y'
                            };
                            item.RightEye.RightEyePossibleDiagnosisArray.push(obj);
                        } else {
                            // Update the existing object to mark it for deletion
                            //existingItem.IsRightSelected = false;
                            existingItem.DeleteInd = 'Y';
                        }
                    }
                    else {
                        if (item.RightEye.RightEyePossibleDiagnosisArray.length > 0) {
                            angular.forEach(item.RightEye.RightEyePossibleDiagnosisArray, function (ritem) {
                                if (ritem.GonioscopyPossibleDiagnosisId == 0 && mitem.DiagnosisId == ritem.PossibleDiagnosisId) {
                                    var index = item.RightEye.RightEyePossibleDiagnosisArray.indexOf(ritem);
                                    if (index > -1) {
                                        item.RightEye.RightEyePossibleDiagnosisArray.splice(index);
                                    }
                                }

                            });
                        }
                    }
                });
            }
        }

        $scope.removePossibleDiagnosisright = function (inv, selectedItem) {

            selectedItem.IsRightSelected = false;
            var existingItem = inv.RightEye.RightEyePossibleDiagnosisArray.find(function (obj) {
                return obj.PossibleDiagnosisId == selectedItem.DiagnosisId;
            });
            if (existingItem) {

                if (existingItem.GonioscopyPossibleDiagnosisId &&
                    existingItem.GonioscopyPossibleDiagnosisId != 0) {
                    existingItem.DeleteInd = 'Y';
                }
                else {
                    var index = inv.RightEye.RightEyePossibleDiagnosisArray.indexOf(existingItem);
                    if (index > -1) {
                        inv.RightEye.RightEyePossibleDiagnosisArray.splice(index, 1);
                    }
                }
            }
            var checkedArray = _.where($scope.RightPossibleDiagnosisArray, { IsRightSelected: true });
            if (checkedArray.length == $scope.RightPossibleDiagnosisArray.length && checkedArray.length > 0) {
                $scope.Status.AllStatusCheck = true;
                $scope.Status.RightSelectStatusString = "All";
            }
            else if (checkedArray.length > 0) {
                $scope.Status.AllStatusCheck = false;
                $scope.Status.RightSelectStatusString = "Selected";
            }
            else {
                $scope.Status.AllStatusCheck = false;
                $scope.Status.RightSelectStatusString = "Select";
            }
        };

