        $scope.ChangeBVPossibleDiagnosis = function (item) {
            var checkedArray = _.where($scope.BinocularPossibleDiagnosis, { IsSelected: true });
            $scope.Status.AllStatusCheck = checkedArray.length > 0 && $scope.BinocularPossibleDiagnosis.length === checkedArray.length ? true : false;
            if ($scope.Status.AllStatusCheck) {
                $scope.Status.BVSelectStatusString = 'All';
            }

            if (!$scope.Status.AllStatusCheck && checkedArray.length > 0) {
                $scope.Status.BVSelectStatusString = 'Selected';
            }
            if ($scope.BinocularPossibleDiagnosis.length > 0) {
                angular.forEach($scope.BinocularPossibleDiagnosis, function (mitem) {
                    // Check if the object already exists in RightEyePossibleDiagnosisArray based on DiagnosisId
                    var existingItem = item.BVPossibleDiagnosisArray.find(function (obj) {
                        return obj.BVPossibleDiagnosis === mitem.DiagnosisName;
                    });

                    if (mitem.IsSelected === true) {
                        if (!existingItem) { // If no existing object, add the new one
                            var obj = {
                                "ExamBVPossibleDiagnosisId": 0,
                                "BVPossibleDiagnosis": mitem.DiagnosisName,
                                "BVPossibleDiagnosisId": mitem.DiagnosisId,
                                "ICD10CODE": mitem.ICD10CODE,
                                //"IsSelected": mitem.IsSelected,
                                "DeleteInd": 'N'
                            };
                            item.BVPossibleDiagnosisArray.push(obj);
                        } else {
                            // Optionally, update the existing object if necessary
                            // existingItem.IsSelected = true;
                            existingItem.DeleteInd = 'N';
                        }
                    } else if (mitem.IsSelected === false && mitem.ExamBVPossibleDiagnosisId != 0) {
                        if (!existingItem) { // If no existing object, add it with DeleteInd 'Y'
                            var obj = {
                                "ExamBVPossibleDiagnosisId": mitem.ExamBVPossibleDiagnosisId || 0,
                                "BVPossibleDiagnosis": mitem.DiagnosisName,
                                "ICD10CODE": mitem.ICD10CODE,
                                "BVPossibleDiagnosisId": mitem.DiagnosisId,
                                //"IsSelected": mitem.IsSelected,
                                "DeleteInd": 'Y'
                            };
                            item.BVPossibleDiagnosisArray.push(obj);
                        } else {
                            // Update the existing object to mark it for deletion
                            //existingItem.IsSelected = false;
                            existingItem.DeleteInd = 'Y';
                        }
                    }
                });
            }
        }

