        function hasCounselorOrders(template) {
            if (!template) return false;

            const pre = template?.PreOp?.OrderDetails;
            const intra = template?.IntraOp?.OrderDetails;
            const post = template?.PostOp?.OrderDetails;

            const investigations = template.InvestigationsList;
            const coordinatorChecklist = template.CoordinatorChecklistArray;

            return (pre && pre.length > 0) ||
                (intra && intra.length > 0) ||
                (post && post.length > 0) ||
                (investigations && investigations.length > 0) ||
                (coordinatorChecklist && coordinatorChecklist.length > 0);
        }
