        $scope.SaveBillTemplates = function () {
            if ($scope.Coordinatorobj.EnterBillTemplateName == '') {
                alertify.error('Please Enter Template Name!');
                return false;
            }
            if ($scope.Mainobj.BillItemList.length == 0) {
                alertify.error('Please Add At Least One Bill Item!');
                return false;
            }
            var params = {
                "UserId": $scope.UserId,
                "OrganizationId": $scope.HospitalId,
                "DeleteInd": "N",
                "TemplateId": 0,
                "TemplateName": $scope.Coordinatorobj.EnterBillTemplateName || '',
                "BillItems": $scope.Mainobj.BillItemList || [],
            }

            eHnotePatientDataService.AddUpdateUserBillItemTemplateDetails(params).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Save successfully");
                    $scope.Coordinatorobj.EnterBillTemplateName = '';
                    $scope.Coordinatorobj.TemplateSavePopOver = false;
                    $scope.GetUserBillItemDetails();

                } else {
                    alertify.error(resp.data.Message);
                }
            }, function (err) {

            });
        }
        $scope.changePrice = function () {
            $scope.Mainobj.BillItemList = $scope.Mainobj.BillItemList || [];
            $scope.Mainobj.TotalAmount = null;
            $scope.Mainobj.TotalChargeAmount = null;
            if ($scope.Mainobj.BillItemList.length > 0) {
                angular.forEach($scope.Mainobj.BillItemList, function (item) {
                    if (item.DeleteInd == 'N') {
                        var Quantity = 0;
                        var Price = 0; Quantity = item.Units;
                        Price = item.PatientCoPay;
                        if (Quantity > 0 && Price > 0) {
                            /*$scope.hghgh = Quantity * Price;*/
                            item.Total = Quantity * Price;
                        } else {
                            item.Total = 0;
                        }
                        /*item.PatientCoPay = parseInt(item.PatientCoPay);*/
                        item.PatientCoPay = item.PatientCoPay || null;
                        item.PatientCoPayRaw = item.PatientCoPay;
                        item.PatientCoPayRaw = parseFloat(item.PatientCoPayRaw) || null;

                        if (item.PatientCoPayRaw != null) {
                            $scope.Mainobj.TotalAmount += item.Total;
                            $scope.Mainobj.TotalChargeAmount += item.Total;
                        }
                        //if (item.PatientCoPayRaw == null || item.Units == null) {
                        //    $scope.Mainobj.TotalChargeAmount = '';
                        //}
                    }
                });
            }
            $scope.Mainobj.TotalChargeAmount = parseFloat($scope.Mainobj.TotalChargeAmount.toFixed(2));
        }
        $scope.changeUploadedItemBillPrice = function () {
            $scope.Mainobj.FileUploadTotalAmount = 0;
            if ($scope.Mainobj.FileUploadArray.length > 0) {
                angular.forEach($scope.Mainobj.FileUploadArray, function (item) {
                    if (item.DeleteInd == 'N') {
                        item.BillItemPriceRaw = item.BillItemPrice;
                        item.BillItemPriceRaw = parseFloat(item.BillItemPriceRaw) || null;

                        $scope.Mainobj.FileUploadTotalAmount += item.BillItemPriceRaw;
                        $scope.Mainobj.FileUploadTotalAmount = parseFloat($scope.Mainobj.FileUploadTotalAmount.toFixed(2));
                    }
                });
            }
        }
