        $scope.GetOrganizationProcedureVideoList = function (text, Type) {
            var newlist = "";
            if ($scope.AdvisedOrderDetailsArray.length > 0) {
                angular.forEach($scope.AdvisedOrderDetailsArray, function (Aitem) {
                    if (Aitem.OrderDetails.length > 0) {
                        var filtredobj = $filter("filter")(Aitem.OrderDetails, function (bitem, index) { return bitem.CoordinatorStatusId == 3 && bitem.OrderTypeId != 4 }) || [];
                        if (filtredobj.length > 0) {
                            angular.forEach(filtredobj, function (item) {
                                newlist += "," + item.OrgDescriptionId;
                            });
                            if (newlist.charAt(0) === ",") {
                                newlist = newlist.slice(1);
                            }
                        }
                    }
                });
            }

            $scope.Coordinatorobj.searchText = '';

            var FileType = '';
            if (Type == 'Video') {
                FileType = Type;
            } else {
                FileType = 'Images';
            }

            var params = {
                "Type": FileType,
                "HospitalId": $scope.HospitalId,
                "PageSize": 10,
                "PageNumber": 1,
                "SearchText": text || "",
            };

            return eHnoteSurgeryService.GetOrganizationPatientEducationMaterials(params).then(function (resp) {
                if (resp.data.rows !== undefined) {
                    $scope.Coordinatorobj.ProcedureVideosArray = [];
                    $scope.Coordinatorobj.ProcedureImagesArray = [];
                    $scope.Coordinatorobj.ProcedureFilesArray = [];
                    if (resp.data.rows.length > 0) {
                        if (Type == 'Video') {
                            angular.forEach(resp.data.rows, function (Vitem) {
                                var videoId = '';
                                var url = Vitem.VideoURL;
                                videoId = url.split("=")[1] || '';
                                Vitem.videoId = videoId;
                                Vitem.IsChecked = false;
                                Vitem.NoteFileTypeId = 42;
                                Vitem.PatientDocumentMaterialId = 0;
                                Vitem.DocumentExt = 'video';
                                Vitem.DeleteInd = 'N';

                                $scope.Coordinatorobj.ProcedureVideosArray.push(Vitem);
                            });
                        } else if (Type == 'Images') {
                            angular.forEach(resp.data.rows, function (item) {
                                if (item.DocumentExt === 'image/jpeg' || item.DocumentExt === "image/png") {
                                    item.file = item.S3URL;
                                    item.IsChecked = false;
                                    item.NoteFileTypeId = 42;
                                    item.PatientDocumentMaterialId = 0;
                                    item.DeleteInd = 'N';

                                    $scope.Coordinatorobj.ProcedureImagesArray.push(item);
                                }
                            });
                        } else {
                            angular.forEach(resp.data.rows, function (item) {
                                if (item.DocumentExt === "application/pdf") {
                                    item.file = item.S3URL;
                                    item.IsChecked = false;
                                    item.NoteFileTypeId = 42;
                                    item.PatientDocumentMaterialId = 0;
                                    item.DeleteInd = 'N';

                                    $scope.Coordinatorobj.ProcedureFilesArray.push(item);
                                }
                            });
                        }
                    }
                    if (Type == 'Video') {
                        return $scope.Coordinatorobj.ProcedureVideosArray.map(function (item) {
                            return item;
                        });
                    } else if (Type == 'Images') {
                        return $scope.Coordinatorobj.ProcedureImagesArray.map(function (item) {
                            return item;
                        });
                    } else {
                        return $scope.Coordinatorobj.ProcedureFilesArray.map(function (item) {
                            return item;
                        });
                    }
                }
            });
        };

