        $scope.ClearAllPosterior = function (organ) {
            if (organ == 1) {
                var confirmationMessage = "Are you sure you want to permanently delete OD values?";
            }
            else {
                var confirmationMessage = "Are you sure you want to permanently delete OS values?";

            }
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>" + confirmationMessage + "</h4>", function () {
                angular.forEach($scope.PoteriorSegmentArrayNew, function (inv, index) {
                    if (inv.InvestigationId !== 32) {
                        if (inv.RemarksArray.length > 0) {
                            var indexesToRemove = [];
                            angular.forEach(inv.RemarksArray, function (hitem, index) {
                                if (hitem.OrganId == organ) {
                                    if (hitem.RemarksId === 0) {
                                        /*inv.RemarksArray.splice(index, 1);*/
                                        indexesToRemove.push(index);
                                    }
                                    else {
                                        hitem.ActiveInd = 'N';
                                    }

                                    if (inv.CategoryId === 6) {
                                        if (organ == 1) {
                                            $scope.cacheStorageItem.PosteriorODIsNormal = false;
                                        }
                                        if (organ == 2) {
                                            $scope.cacheStorageItem.PosteriorOSIsNormal = false;
                                        }
                                    }
                                }
                            });
                            indexesToRemove.reverse().forEach(function (index) {
                                inv.RemarksArray.splice(index, 1);
                            });
                        }
                    } else if (inv.InvestigationId == 32 && organ == 1) {
                        inv.RHorizontal = "";
                        inv.RVertical = "";
                        inv.RDPS = "";
                        $scope.CDRHorizantalList = GetPosteriorCDR();
                        $scope.CDRVerticalList = GetPosteriorCDR();
                        $scope.CDR_DPSList = GetPosteriorCDR();
                    } else if (inv.InvestigationId == 32 && organ == 2) {
                        inv.LHorizontal = "";
                        inv.LVertical = "";
                        inv.LDPS = "";
                        $scope.CDRHorizantalList = GetPosteriorCDR();
                        $scope.CDRVerticalList = GetPosteriorCDR();
                        $scope.CDR_DPSList = GetPosteriorCDR();
                    }
                });

                angular.forEach($scope.Posteriorfavariotes, function (item) {
                    item.IsChecked = false;
                });
                angular.forEach($scope.PosteriorLeftfavariotes, function (item) {
                    item.IsChecked = false;
                });
                angular.forEach($scope.PoteriorSegmentArrayNew, function (mainitem) {
                    angular.forEach(mainitem.RemarksArray, function (Aitem) {
                        if (Aitem.OrganId == 1 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.Posteriorfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        } else if (Aitem.OrganId == 2 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.PosteriorLeftfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        }

                    });
                });
                $scope.$digest();
                $scope.IsPosteriorTemplateAlreadyAdded = false;

            }, function () {
                r = "You pressed Cancel!";
            });
        }
