                    $scope.AnteriorPosteriorObj = {
                        "ShowAddNewBtn": false,
                        "type": '',
                        "InvestigationDesc": '',
                        "FindingValue": '',
                        "FindingValuesArray": [],
                        "InvestigationId": 0,
                        "InvestigationDesc": '',
                        "CategoryId": ''
                    };
