        //MRD info 
        $scope.ChangeAnteriorMRDValue = function (item, MainArray, ExamAnteriorPosteriorObject) {
            if (MainArray.length > 0) {
                let ValueArray = $filter('filter')(MainArray, { 'FindingId': item.FindingId }, true) || [];
                angular.forEach(ValueArray, function (valueitem) {
                    valueitem.IsChecked = false;
                    if (valueitem.FindingId == item.FindingId) {
                        item.IsChecked = true;
                    }
                });

                if ($scope.AnteriorSegmentArrayNew.length > 0) {
                    angular.forEach($scope.AnteriorSegmentArrayNew, function (pitem) {
                        if (pitem.InvestigationId == 6 && pitem.InvestigationId == item.FindingId) {
                            pitem.InvestigationDesc = item.FindingName || '';
                        }

                        if (ExamAnteriorPosteriorObject.IsAnteriorMrdODInd) {

                            if (item.FindingId == 6) {
                                pitem.RMRD1 = item.FindingValue || "";
                            }
                            if (item.FindingId == 7) { pitem.RMRDcNS = item.FindingValue || ""; }
                            if (item.FindingId == 9) { pitem.RMRD2 = item.FindingValue || ""; }
                            if (item.FindingId == 10) { pitem.RLF = item.FindingValue || ""; }
                            if (item.FindingId == 31) { pitem.RPFH = item.FindingValue || ""; }
                        }
                        if (ExamAnteriorPosteriorObject.IsAnteriorMrdOSInd) {
                            if (item.FindingId == 6) { pitem.LMRD1 = item.FindingValue || ""; }
                            if (item.FindingId == 7) { pitem.LMRDcNS = item.FindingValue || ""; }
                            if (item.FindingId == 9) { pitem.LMRD2 = item.FindingValue || ""; }
                            if (item.FindingId == 10) { pitem.LLF = item.FindingValue || ""; }
                            if (item.FindingId == 31) { pitem.LPFH = item.FindingValue || ""; }
                        }
                    });
                }
            }
        }
        $scope.AddODmrdvalue = function (eyetype) {
            if (eyetype == 'OD') {
                $scope.ExamAnteriorPosteriorObject.IsAnteriorMrdODInd = true;
                $scope.ExamAnteriorPosteriorObject.IsAnteriorMrdOSInd = false;
            }
            if (eyetype == 'OS') {
                $scope.ExamAnteriorPosteriorObject.IsAnteriorMrdODInd = false
                $scope.ExamAnteriorPosteriorObject.IsAnteriorMrdOSInd = true;
            }
            var MRD1 = "";
            var MRDcNS = "";
            var MRD2 = "";
            var PFH = "";
            var LF = "";
            if ($scope.AnteriorSegmentArrayNew.length > 0) {
                angular.forEach($scope.AnteriorSegmentArrayNew, function (pitem) {
                    if (pitem.InvestigationId == 6) {
                        if (eyetype == "OD") {
                            MRD1 = pitem.RMRD1;
                            MRDcNS = pitem.RMRDcNS;
                            MRD2 = pitem.RMRD2;
                            LF = pitem.RLF;
                            PFH = pitem.RPFH;
                        } else if (eyetype == "OS") {
                            MRD1 = pitem.LMRD1;
                            MRDcNS = pitem.LMRDcNS;
                            MRD2 = pitem.LMRD2;
                            LF = pitem.LLF;
                            PFH = pitem.LPFH;
                        }
                    }
                });
            }
            angular.forEach($scope.chunkedAnteriorINVDropdownList, function (item) {
                item.IsChecked = false;
            });
            let filterLMRD1 = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRD1, 'FindingId': 6 }, true);
            if (filterLMRD1.length > 0) {
                filterLMRD1[0].IsChecked = true;
            }
            let filterLMRDcNS = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRDcNS, 'FindingId': 7 }, true);
            if (filterLMRDcNS.length > 0) {
                filterLMRDcNS[0].IsChecked = true;
            }
            let filterLMRD2 = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRD2, 'FindingId': 9 }, true);
            if (filterLMRD2.length > 0) {
                filterLMRD2[0].IsChecked = true;
            }
            let filterLLF = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": LF, 'FindingId': 10 }, true);
            if (filterLLF.length > 0) {
                filterLLF[0].IsChecked = true;
            }
            let filterLPFH = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": PFH, 'FindingId': 31 }, true);
            if (filterLPFH.length > 0) {
                filterLPFH[0].IsChecked = true;
            }
        }
