                    $scope.changeAnteriorDPSSelectedEye = function (eye) {

                        $scope.AnteriorINVDropdownList = $filter("filter")($scope.AnteriorINVDropdownListMain, function (iterator, ind) { return (iterator.FindingId == 6 || iterator.FindingId == 7 || iterator.FindingId == 9 || iterator.FindingId == 10 || iterator.FindingId == 31) }) || [];
                        $scope.chunkedAnteriorINVDropdownList = angular.copy($scope.AnteriorINVDropdownList);

                        var MRD1 = "";
                        var MRDcNS = "";
                        var MRD2 = "";
                        var LF = "";
                        var PFH = "";

                        if ($scope.AnteriorSegmentArrayForGrid.length > 0) {
                            angular.forEach($scope.AnteriorSegmentArrayForGrid, function (pitem) {
                                if (pitem.InvestigationId == 6) {

                                    if (eye == "OD") {
                                        MRD1 = pitem.RMRD1;
                                        MRDcNS = pitem.RMRDcNS;
                                        MRD2 = pitem.RMRD2;
                                        LF = pitem.RLF;
                                        PFH = pitem.RPFH;
                                    } else if (eye == "OS") {
                                        MRD1 = pitem.LMRD1;
                                        MRDcNS = pitem.LMRDcNS;
                                        MRD2 = pitem.LMRD2;
                                        LF = pitem.LLF;
                                        PFH = pitem.LPFH;
                                    }
                                }

                                if (MRD1 != undefined && MRD1 != "") {
                                    var filter = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRD1, 'FindingId': 6 }, true);
                                    if (filter.length > 0) {
                                        filter[0].IsChecked = true;
                                    }
                                }
                                if (MRDcNS != undefined && MRDcNS != "") {
                                    var filter = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRDcNS, 'FindingId': 7 }, true);
                                    if (filter.length > 0) {
                                        filter[0].IsChecked = true;
                                    }
                                }
                                if (MRD2 != undefined && MRD2 != "") {
                                    var filter = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": MRD2, 'FindingId': 9 }, true);
                                    if (filter.length > 0) {
                                        filter[0].IsChecked = true;
                                    }
                                }
                                if (LF != undefined && LF != "") {
                                    var filter = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": LF, 'FindingId': 10 }, true);
                                    if (filter.length > 0) {
                                        filter[0].IsChecked = true;
                                    }
                                }
                                if (PFH != undefined && PFH != "") {
                                    var filter = $filter("filter")($scope.chunkedAnteriorINVDropdownList, { "FindingValue": PFH, 'FindingId': 31 }, true);
                                    if (filter.length > 0) {
                                        filter[0].IsChecked = true;
                                    }
                                }

                            });
                        }

                    };
                    $scope.ChangeAnteriorMRDValue = function (item, MainArray, ExamAnteriorPosteriorObject) {
                        if (MainArray.length > 0) {
                            let ValueArray = $filter('filter')(MainArray, { 'FindingId': item.FindingId }, true) || [];
                            angular.forEach(ValueArray, function (valueitem) {

                                if (valueitem.FindingId == item.FindingId && item.InvFindingId !== valueitem.InvFindingId) {
                                    valueitem.IsChecked = false;

                                }
                            });
                            if (item.IsChecked == false || item.IsChecked == undefined) {
                                item.IsChecked = true;
                            }
                            else {
                                item.IsChecked = false;
                            }
                            if (item.IsChecked == false) {
                                if ($scope.AnteriorSegmentArrayForGrid.length > 0) {
                                    angular.forEach($scope.AnteriorSegmentArrayForGrid, function (pitem) {
                                        if (ExamAnteriorPosteriorObject.IsAnteriorMrdODInd) {

                                            if (item.FindingId == 6) {
                                                pitem.RMRD1 = "";
                                            }
                                            if (item.FindingId == 7) { pitem.RMRDcNS = ""; }
                                            if (item.FindingId == 9) { pitem.RMRD2 = ""; }
                                            if (item.FindingId == 10) { pitem.RLF = ""; }
                                            if (item.FindingId == 31) { pitem.RPFH = ""; }
                                        }
                                        if (ExamAnteriorPosteriorObject.IsAnteriorMrdOSInd) {
                                            if (item.FindingId == 6) { pitem.LMRD1 = ""; }
                                            if (item.FindingId == 7) { pitem.LMRDcNS = ""; }
                                            if (item.FindingId == 9) { pitem.LMRD2 = ""; }
                                            if (item.FindingId == 10) { pitem.LLF = ""; }
                                            if (item.FindingId == 31) { pitem.LPFH = ""; }
                                        }
                                    });
                                }
                                return false;
                            }

                            if ($scope.AnteriorSegmentArrayForGrid.length > 0) {
                                angular.forEach($scope.AnteriorSegmentArrayForGrid, function (pitem) {
                                    if (pitem.InvestigationId == 6 && pitem.InvestigationId == item.FindingId) {
                                        pitem.InvestigationDesc = item.FindingName || '';
                                    }

                                    if (ExamAnteriorPosteriorObject.IsAnteriorMrdODInd) {

                                        if (item.FindingId == 6) {
                                            pitem.RMRD1 = item.FindingValue || "";
                                        }
                                        if (item.FindingId == 7) { pitem.RMRDcNS = item.FindingValue || ""; }
                                        if (item.FindingId == 9) { pitem.RMRD2 = item.FindingValue || ""; }
                                        if (item.FindingId == 10) { pitem.RLF = item.FindingValue || ""; }
                                        if (item.FindingId == 31) { pitem.RPFH = item.FindingValue || ""; }
                                    }
                                    if (ExamAnteriorPosteriorObject.IsAnteriorMrdOSInd) {
                                        if (item.FindingId == 6) { pitem.LMRD1 = item.FindingValue || ""; }
                                        if (item.FindingId == 7) { pitem.LMRDcNS = item.FindingValue || ""; }
                                        if (item.FindingId == 9) { pitem.LMRD2 = item.FindingValue || ""; }
                                        if (item.FindingId == 10) { pitem.LLF = item.FindingValue || ""; }
                                        if (item.FindingId == 31) { pitem.LPFH = item.FindingValue || ""; }
                                    }
                                });
                            }
                        }
                    }

                    $scope.ChangeAnteriorMRDValueNew = function (item, MainArray, eye) {
                        if (!MainArray || MainArray.length === 0) return;

                        // Determine which flag to use based on eye
                        const flagKey = (eye === 'OD') ? 'IsCheckedOD' : 'IsCheckedOS';

                        const ValueArray = $filter('filter')(MainArray, { 'FindingId': item.FindingId }, true) || [];

                        angular.forEach(ValueArray, function (valueitem) {
                            if (valueitem.InvFindingId !== item.InvFindingId) {
                                valueitem[flagKey] = false;
                            }
                        });

                        // Toggle current item for specific eye
                        item[flagKey] = !item[flagKey];

                        // If unchecked, clear the values
                        if (!item[flagKey] && $scope.AnteriorSegmentArrayForGrid && $scope.AnteriorSegmentArrayForGrid.length > 0) {
                            angular.forEach($scope.AnteriorSegmentArrayForGrid, function (pitem) {
                                if (pitem.InvestigationId === 6) {
                                    if (eye === 'OD') {
                                        if (item.FindingId === 6) pitem.RMRD1 = "";
                                        else if (item.FindingId === 7) pitem.RMRDcNS = "";
                                        else if (item.FindingId === 9) pitem.RMRD2 = "";
                                        else if (item.FindingId === 10) pitem.RLF = "";
                                        else if (item.FindingId === 31) pitem.RPFH = "";
                                    }
                                    if (eye === 'OS') {
                                        if (item.FindingId === 6) pitem.LMRD1 = "";
                                        else if (item.FindingId === 7) pitem.LMRDcNS = "";
                                        else if (item.FindingId === 9) pitem.LMRD2 = "";
                                        else if (item.FindingId === 10) pitem.LLF = "";
                                        else if (item.FindingId === 31) pitem.LPFH = "";
                                    }
                                }
                            });
                            return;
                        }

                        // If checked, update the corresponding values
                        if (item[flagKey] && $scope.AnteriorSegmentArrayForGrid && $scope.AnteriorSegmentArrayForGrid.length > 0) {
                            angular.forEach($scope.AnteriorSegmentArrayForGrid, function (pitem) {
                                if (pitem.InvestigationId === 6) {
                                    if (item.FindingId === 6) {
                                        pitem.InvestigationDesc = item.FindingName || '';
                                    }

                                    if (eye === 'OD') {
                                        if (item.FindingId === 6) pitem.RMRD1 = item.FindingValue || "";
                                        else if (item.FindingId === 7) pitem.RMRDcNS = item.FindingValue || "";
                                        else if (item.FindingId === 9) pitem.RMRD2 = item.FindingValue || "";
                                        else if (item.FindingId === 10) pitem.RLF = item.FindingValue || "";
                                        else if (item.FindingId === 31) pitem.RPFH = item.FindingValue || "";
                                    }

                                    if (eye === 'OS') {
                                        if (item.FindingId === 6) pitem.LMRD1 = item.FindingValue || "";
                                        else if (item.FindingId === 7) pitem.LMRDcNS = item.FindingValue || "";
                                        else if (item.FindingId === 9) pitem.LMRD2 = item.FindingValue || "";
                                        else if (item.FindingId === 10) pitem.LLF = item.FindingValue || "";
                                        else if (item.FindingId === 31) pitem.LPFH = item.FindingValue || "";
                                    }
                                }
                            });
                        }
                    };


