                    $scope.AddPosteriorFavoriteFindingValues = function (item, CategoryId, CategoryName, FindingName) {
                        $scope.ExamLogObj.LogArray = [];
                        item.IsFavoriteInd = !item.IsFavoriteInd || false;
                        FindingName = FindingName || "";
                        var params = {
                            "UserId": doctorinfo.doctorid,
                            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                            "OrganizationFindingValueId": item.InvFindingId || 0,
                            //"MasterFindingValueId": 0,
                            "DeleteInd": "N",
                            "CategoryId": CategoryId || 6,
                            "CategoryName": CategoryName || 'Posterior Segment',
                            "FindingId": item.FindingId || 0,
                            "FindingName": item.FindingName || '',
                            //"OrganizationFindingId": 0,
                            "FindingValue": item.FindingValue || "",
                            "IsFavoriteInd": item.IsFavoriteInd,
                            "Logs": {}

                        }
                        let newvalue = '';
                        let Oldvalue = '';

                        if ($scope.ExamLogObj.Posteriorfavariotes.length > 0) {
                            angular.forEach($scope.ExamLogObj.Posteriorfavariotes, function (kitem) {
                                if (kitem.InvFindingId === item.InvFindingId) {
                                    Oldvalue = `${FindingName} : ${item.FindingValue} -  is favourite.`;
                                }
                            });
                        }
                        if (Oldvalue == '') {
                            if (params.IsFavoriteInd == true) {
                                newvalue = `${FindingName} : ${item.FindingValue} -  is favourite.`;
                            }
                        } else {
                            if (params.IsFavoriteInd == false) {
                                newvalue = `${FindingName} : ${item.FindingValue} -  is  unfavourite.`;
                            }
                        }
                        if (Oldvalue == '') {
                            let logObj = {
                                "LogId": 0,
                                "ModuleId": 2,
                                "ModuleName": "OUT PATIENT",
                                "SubModuleId": 52,
                                "SubModuleName": "Examination",
                                "ScreenType": "Posterior Segment",
                                "ActionType": "Added",
                                "OldActionDescription": Oldvalue,
                                "NewActionDescription": newvalue,
                                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                            };
                            $scope.ExamLogObj.LogArray.push(logObj);
                        }
                        else if (Oldvalue !== '' && newvalue !== '') {
                            let logObj = {
                                "LogId": 0,
                                "ModuleId": 2,
                                "ModuleName": "OUT PATIENT",
                                "SubModuleId": 52,
                                "SubModuleName": "Examination",
                                "ScreenType": "Posterior Segment",
                                "ActionType": "Edited",
                                "OldActionDescription": Oldvalue,
                                "NewActionDescription": newvalue,
                                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                            };
                            $scope.ExamLogObj.LogArray.push(logObj);
                        }
                        if ($scope.ExamLogObj.LogArray.length > 0) {
                            params.Logs = $scope.ExamLogObj || {};
                        }
                        eHnotePatientDataService.AddUpdateOrgFindingValues(params).then(function (resp) {
                            if (resp.data.Status === 'Success') {

                                if (item.IsFavoriteInd) {
                                    alertify.success('Add Favorite Successfully');
                                } else {
                                    alertify.success('Remove Favorite Successfully');
                                }

                            }
                            else {
                                alertify.error(resp.data.Message);

                            }
                        });
                    }

