        $scope.CopyOrderDetailDiagnosis = function (orditem, mainitem) {

            if (mainitem.OrganId == 3) {

                let orderdetailuncheck = $filter("filter")(mainitem.OrderDetails, function (item) {
                    return !item.ISSelectedOrderDetailItem;
                }) || [];
                let uncheckdiag = []
                if (orderdetailuncheck.length > 0) {
                    uncheckdiag = angular.copy(orderdetailuncheck[0].DiagnosisList) || [];
                }
                if (uncheckdiag.length > 0) {
                    angular.forEach($scope.AddDiagnosisAssesmentPlanArray, function (Aitem) {
                        angular.forEach(uncheckdiag, function (Bitem) {
                            if (Aitem.DiagnosisId == Bitem.DiagnosisId) {
                                Aitem.IsCheckedDiagnosis = true;
                            }

                            //continue from push to current item
                            //else {
                            //    Aitem.IsCheckedDiagnosis = false;
                            //}

                        });
                    });

                    angular.forEach(uncheckdiag, function (Bitem) {
                        Bitem.DiagnosisId = Bitem.DiagnosisId || 0;
                        Bitem.SnomedCodeId = Bitem.SnomedCodeId || 0;
                        if (Bitem.DiagnosisId !== 0) {
                            var TempDiagnosisDiagnosisArray = $filter("filter")(orditem.DiagnosisList, { "DiagnosisId": Bitem.DiagnosisId, "DeleteInd": 'N' }, true);
                            if (TempDiagnosisDiagnosisArray.length == 0) {
                                Bitem.DiagnosisDetailId = 0;
                                orditem.DiagnosisList.push(Bitem);
                            }
                        }
                        if (Bitem.SnomedCodeId !== 0) {
                            var TempSnomedDiagnosisArray = $filter("filter")(orditem.DiagnosisList, { "DiagnosisId": Bitem.SnomedCodeId, "DeleteInd": 'N' }, true);
                            if (TempSnomedDiagnosisArray.length == 0) {
                                Bitem.DiagnosisDetailId = 0;
                                orditem.DiagnosisList.push(Bitem);
                            }
                        }
                    });
                }
                //if (orderdetailcheck.length == 0) {
                //    object.OrderDetails.push(orderdetail);
                //}
            }


        };

        $scope.OnsurgeryItemSelect = function (suritem, orditem, mainitem) {
            //var filterProcedure = $filter("filter")(mainitem.OrderDetails, function (Aitem, index) { return Aitem.OrgDescriptionId == suritem.OrganizationProcedureId && Aitem.ISSelectedOrderDetailItem },) || [];

            var filterProcedure = ($filter("filter")(mainitem.OrderDetails, function (Aitem) {
                return Aitem.OrgDescriptionId == suritem.OrganizationProcedureId
                    && Aitem.ISSelectedOrderDetailItem === true;
            }) || []);

            if (filterProcedure.length > 0) {
                $scope.adviseObj.surgeyobj = "";
                alertify.error("Surgery Already Added");
                return false;
            }


            if (!orditem.OrganId) {
                alertify.error("Please select Organ");
                $scope.adviseObj.surgeyobj = "";
                return false;
            }

            if (suritem.OrganId) {

                var selectedSide = Number(orditem.OrganId);
                var procedureSide = Number(suritem.OrganId);

                if (selectedSide !== procedureSide) {
                    alertify.error("Procedure does not match selected organ.");
                    $scope.adviseObj.surgeyobj = '';
                    return;
                }
            }



            orditem.DescriptionId = suritem.ProcedureId || "";
            orditem.ProcedureName = suritem.ProcedureName || "";
            orditem.Description = suritem.ProcedureName || ""
            orditem.ProcedureCode = suritem.ProcedureCode || 0;
            orditem.OrgDescriptionId = suritem.OrganizationProcedureId || 0;
            orditem.CPTCode = suritem.CPTCode || '',


                orditem.CoordinatorId = suritem.CoordinatorId || 0;

            orditem.DurationType = suritem.DurationType || "D";

            orditem.ExternalCoManagerId = suritem.ExternalCoManagerId || 0;
            orditem.InternalCoManagerId = suritem.InternalCoManagerId || 0;

            let DoctorID = orditem.SurgeonId || 0;

            $scope.loadCoordinatorOrderTemplates('', DoctorID)


            //if (filterProcedure.length==0){
            //    mainitem.OrderDetails.push(orderdetail);
            //}
            $scope.adviseObj.surgeyobj = "";
        }

