        $scope.EditAppointment = function (sitem, orditem, type, AppointmentId) {
            let EyeOrderId = orditem.EyeOrder || 0;
            eHnoteMainAppointmentService.getAdditionalApptDetailsById(AppointmentId).then(function (resp) {
                console.log(resp);
                resp.data = resp.data || [];
                if (resp.data.length > 0) {
                    let item = resp.data[0] || [];
                    var Sarray = item.AppointmentDetails[0].StartTime.split(":");
                    var stime = Sarray[0] + ":" + Sarray[1];
                    var date = moment(item.AppointmentDetails[0].AppointmentDate).format();
                    var earray = item.AppointmentDetails[0].EndTime.split(":");
                    var etime = earray[0] + ":" + earray[1];
                    var apptime = item.AppointmentDetails[0].AppointmentId;
                    var VisitTypeId = item.AppointmentDetails[0].AppointmentTypeId || "";
                    VisitTypeId = VisitTypeId != '' ? VisitTypeId : 0;
                    var VisitRemarks = item.AppointmentDetails[0].VisitRemarks || "";

                    $scope.AppDate = [stime, etime, apptime, item.VisitReason ? item.VisitReason : "", item.ReferralSourceId ? item.ReferralSourceId : "", VisitTypeId, VisitRemarks];

                    $scope.calenderDate = moment(date).format("DD-MMM-YYYY" + " " + stime);

                    $scope.PageName = "reschedule";

                    let surgeryList = [];
                    if (item.AppointmentDetails[0].AppointmentTypeId == 7) {
                        surgeryList = angular.copy(item.AppointmentDetails[0].PreAdmSurgeryList);

                    } else if (item.AppointmentDetails[0].AppointmentTypeId == 4 || item.AppointmentDetails[0].AppointmentTypeId == 14) {
                        surgeryList = angular.copy(item.AppointmentDetails[0].SurgeryList);
                    }

                    var Obj = {
                        "PageName": "reschedule",
                        "AppDate": $scope.AppDate,
                        "ispatientExistsval": true,
                        "calenderDate": $scope.calenderDate,
                        "AppointmentDate": item.AppointmentDetails[0].AppointmentDate,
                        "AppointmentId": item.AppointmentDetails[0].AppointmentId || null,
                        "PatientId": item.Patient.PatientID || null,
                        'IsComingFrom': 'Coordinator',
                        "DoctorId": item.AppointmentDetails[0].DoctorID,
                        "BranchId": item.AppointmentDetails[0].BranchId,
                        "StartTime": stime || "",
                        "EndTime": etime,
                        'type': 'op',
                        "SurgeryList": surgeryList || [],
                        'IsApptType': 'PreAdmission',
                        "SelectedAppointmentType": type || 0,

                    };
                    datapersistanceFactory.set('AppointmentDetailsCache', Obj);
                    //$scope.OpenAppointmentPopupForCounsellor  (obj, EyeOrderId, type,) 


                    var openBookAppt = "";
                    let bookapptSetupPopUp = $uibModal.open({
                        /*"templateUrl": "templates/appointment/BookAppointmentPopup.html",*/
                        "templateUrl": "templates/appointment/BookAppointmentPopupv3.html",
                        "keyboard": false,
                        "backdrop": "static",
                        "windowClass": "modal__popup--1 bottom-to-top-modal",
                        /*"controller": "UsNewBookAppointmentPopupCtrl",*/
                        "controller": "UsBookAppointmentPopupv2",
                        "resolve": {
                            "allUserList": function () { return angular.copy($scope.allUserList); },
                            "openBookAppt": function () { return openBookAppt; },
                            "BranchList": function () { return $scope.BranchList || []; }
                        }
                    });

                    bookapptSetupPopUp.result.then(function (resp) {
                        resp = resp || '';
                        if (resp != '') {
                            resp.response = resp.response || '';
                            let AppointmentID = 0,
                                AppointmentTypeId = 0,
                                ConsultationDate = null,
                                StartTime = null;
                            if (resp.response != '') {
                                AppointmentID = resp.response.AppointmentID || 0;
                                AppointmentTypeId = resp.response.AppointmentTypeId || 0;
                                ConsultationDate = resp.response.ConsultationDate || null;
                                StartTime = resp.response.StartTime || null;
                            }

                            if ($scope.AdvisedOrderDetailsArray.length > 0) {
                                var count = 0;
                                angular.forEach($scope.AdvisedOrderDetailsArray, function (item) {
                                    //item.IsEditData = false;
                                    if (item.OrderType == "Surgery") {

                                        item.OrderDetails = item.OrderDetails || [];
                                        if (item.OrderDetails.length > 0) {

                                            obj.OrgDescriptionId = obj.OrgDescriptionId || 0;
                                            if (sitem.OrgDescriptionId == item.OrgDescriptionId) {
                                                item.IsEditData = true;
                                                var filterEye = $filter("filter")(item.OrderDetails, function (Aitem, index) { return Aitem.EyeOrder == EyeOrderId },) || [];
                                                if (filterEye.length > 0) {
                                                    filterEye[0].ISSelectedOrderDetailItem = true;

                                                    if (AppointmentTypeId == 7) {
                                                        filterEye[0].PreAdmissionDate = ConsultationDate || null;
                                                        filterEye[0].PreAdmissionStartTime = StartTime || null;
                                                        filterEye[0].PreAdmissionAppointmentID = AppointmentID || 0;

                                                    } else if (AppointmentTypeId == 4 || AppointmentTypeId == 14) {
                                                        if (type == 4) {
                                                            filterEye[0].AscAppointmentDate = ConsultationDate || null;
                                                            filterEye[0].AscAppointmentStartTime = StartTime || null;
                                                            filterEye[0].AscAppointmentID = AppointmentID || 0;
                                                        }

                                                    }
                                                    else if (AppointmentTypeId == 3) {
                                                        if (type == 1) {
                                                            filterEye[0].FirstFollowupDate = ConsultationDate || null;
                                                            filterEye[0].FirstFollowupStartTime = StartTime || null;
                                                            filterEye[0].FirstFollowupAppointmentID = AppointmentID || 0;
                                                        }

                                                        else if (type == 2) {
                                                            filterEye[0].SecondFollowupDate = ConsultationDate || null;
                                                            filterEye[0].SecondFollowupStartTime = StartTime || null;
                                                            filterEye[0].SecondFollowupAppointmentID = AppointmentID || 0;
                                                        } else if (type == 3) {
                                                            filterEye[0].ThirdFollowupDate = ConsultationDate || null;
                                                            filterEye[0].ThirdFollowupAppointmentID = AppointmentID || null;
                                                            filterEye[0].ThirdFollowupStartTime = StartTime || 0;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        //    count++;
                                    }
                                });
                            }
                        }

                    }, function (data) {

                    });
                }
            }, function (err) {
                alertify.error("Getting data failed");
            });
        }
