        //function formatToAMPM(dateTime) {
        //    if (!dateTime) return null;
        //    return new Date(dateTime).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
        //}
        function formatToAMPM(timeString) {
            if (!timeString) return null;

            // If the value is already a Date object, use it directly
            let dateObj;
            if (typeof timeString === "string") {
                // Convert string "12:00:00" into a proper Date object
                if (timeString.includes("AM") || timeString.includes("PM")) {
                    // Case 1: If time is already in AM/PM format, directly parse it
                    dateObj = new Date("1970-01-01 " + timeString);
                } else {
                    // Case 2: If time is in "HH:mm:ss" format, parse it properly
                    let [hours, minutes, seconds] = timeString.split(":").map(Number);
                    dateObj = new Date();
                    dateObj.setHours(hours, minutes || 0, seconds || 0);
                }
                //let [hours, minutes, seconds] = timeString.split(":").map(Number);
                //dateObj = new Date();
                //dateObj.setHours(hours, minutes, seconds);
            } else {
                dateObj = new Date(timeString);
            }

            // Return formatted time in AM/PM format
            return $filter('date')(dateObj, 'hh:mm a');
        }


