                    $scope.addToPosteriorTemplate = function (mitem) {
                        $scope.ExamLogObj.LogArray = [];
                        let TempPosteriorArray = mitem.PosteriorSegmentArrayNew || [];

                        var temparray = $filter("filter")($scope.FindingCheckValuesList, { "CategoryId": 6 }, true);
                        let addArr = [];
                        var FilteredPosteriorData = $scope.PosteriorSegmentArrayNew.filter(function (item) {
                            var hasRemarks = (item.RemarksArray && item.RemarksArray.length > 0);
                            var isMRD = item.InvestigationId === 32;
                            var hasMRDValues = !!(item.LDPS || item.LVertical || item.LHorizontal || item.RDPS || item.RVertical ||
                                item.RHorizontal);
                            return hasRemarks || (isMRD && hasMRDValues);
                        });


                        if (FilteredPosteriorData.length > 0) {
                            angular.forEach(FilteredPosteriorData, function (Aitem) {
                                // Find if an item with the same InvestigationId already exists in PoteriorSegmentArrayNew

                                let matchingItem = TempPosteriorArray.find(function (Mitem) {
                                    return Mitem.InvestigationId === Aitem.InvestigationId;
                                });

                                if (!matchingItem) {
                                    // No match found, create new object and add it to PoteriorSegmentArrayNew
                                    if (Aitem.InvestigationId !== 32) {
                                        var object = {
                                            "PatinetFindingPosteriorTemplateId": 0,
                                            "IsNormal": false,
                                            "CategoryId": Aitem.CategoryId || 6,
                                            "CategoryDesc": Aitem.CategoryName || "Posterior Segment",
                                            "InvestigationId": Aitem.InvestigationId || 0,
                                            "InvestigationDesc": Aitem.InvestigationDesc || "",
                                            "ActiveInd": "Y",
                                            "SelectedGlobalSearch": "",
                                            "SelectedRightEye": 1,
                                            "SelectedLeftEye": 0,
                                            "RemarksArray": [],
                                        };
                                        // Add remarks to the new item
                                        angular.forEach(Aitem.RemarksArray, function (Mitem) {
                                            Mitem.SubFindingList = Mitem.SubFindingList || [];
                                            if (Mitem.SubFindingList.length > 0) {
                                                angular.forEach(Mitem.SubFindingList, function (aitem) {
                                                    aitem.PosteriorSegmentRemarksLevelId = 0;
                                                })
                                            }
                                            var obj = {
                                                "PosteriorRemarksTemplateId": 0,
                                                "InvFindingId": Mitem.InvFindingId || 0,
                                                "FindingValue": Mitem.FindingValue || '',
                                                "OrganId": Mitem.OrganId || 1,
                                                "FindingId": 0,
                                                "FindingName": '',
                                                "DiagnosisRiskLevel": "",
                                                "ActiveInd": "Y",
                                                "Notes": "",
                                                "IsShowNotesTextBox": false,
                                                "SubFindingList": Mitem.SubFindingList || [],
                                                "StampsArray": Mitem.StampsArray || []
                                            }
                                            object.RemarksArray.push(obj);
                                            addArr.push(buildPosteriorSingleRemarkLog(Aitem.InvestigationId, Aitem, Mitem).trim());
                                        });
                                        TempPosteriorArray.push(object);
                                    } else if (Aitem.InvestigationId == 32) {
                                        var obj1 = {
                                            "PatinetFindingPosteriorTemplateId": 0,
                                            "IsNormal": false,
                                            "CategoryId": Aitem.CategoryId || 6,
                                            "CategoryName": Aitem.CategoryName || "Posterior Segment",
                                            "InvestigationId": Aitem.InvestigationId,
                                            "InvestigationDesc": Aitem.InvestigationDesc,
                                            "ActiveInd": "Y",
                                            "RemarksArray": [],
                                            "RHorizontal": Aitem.RHorizontal || "",
                                            "RVertical": Aitem.RVertical || "",
                                            "RDPS": Aitem.RDPS || "",
                                            "LHorizontal": Aitem.LHorizontal || "",
                                            "LVertical": Aitem.LVertical || "",
                                            "LDPS": Aitem.LDPS || "",
                                        }
                                        TempPosteriorArray.push(obj1);
                                        addArr.push(buildPosteriorSingleRemarkLog(Aitem.InvestigationId, Aitem).trim());
                                    }
                                } else if (matchingItem || Aitem.RemarksArray.length > 0) {
                                    // Matching item found, check for new remarks
                                    angular.forEach(Aitem.RemarksArray, function (newRemark) {

                                        angular.forEach(temparray, function (Mitem) {
                                            let existingdata = matchingItem.RemarksArray.find(function (item) {
                                                return Mitem.InvFindingId === item.InvFindingId
                                            })

                                            if (existingdata) {
                                                for (let i = matchingItem.RemarksArray.length - 1; i >= 0; i--) {
                                                    let remark = matchingItem.RemarksArray[i];
                                                    if (remark.InvFindingId === Mitem.InvFindingId && remark.OrganId === newRemark.OrganId && remark.RemarksId === 0) {
                                                        matchingItem.RemarksArray.splice(i, 1);
                                                    } else if (remark.InvFindingId === Mitem.InvFindingId && remark.OrganId === newRemark.OrganId && remark.RemarksId != 0) {
                                                        remark.ActiveInd = 'N';
                                                    }
                                                }
                                            }

                                        })

                                        let existingRemark = matchingItem.RemarksArray.find(function (remark) {
                                            return remark.InvFindingId === newRemark.InvFindingId
                                                && remark.OrganId === newRemark.OrganId
                                                && remark.ActiveInd === "Y";
                                        });

                                        if (!existingRemark) {
                                            newRemark.SubFindingList = newRemark.SubFindingList || [];
                                            if (newRemark.SubFindingList.length > 0) {
                                                angular.forEach(newRemark.SubFindingList, function (aitem) {
                                                    aitem.PosteriorSegmentRemarksLevelId = 0;
                                                })
                                            }
                                            var obj = {
                                                "PosteriorRemarksTemplateId": 0,
                                                "InvFindingId": newRemark.InvFindingId || 0,
                                                "FindingValue": newRemark.FindingValue || '',
                                                "OrganId": newRemark.OrganId || 1,
                                                "FindingId": 0,
                                                "FindingName": '',
                                                "DiagnosisRiskLevel": "",
                                                "ActiveInd": "Y",
                                                "Notes": "",
                                                "IsShowNotesTextBox": false,
                                                "SubFindingList": newRemark.SubFindingList || [],
                                                "StampsArray": newRemark.StampsArray || []
                                            }
                                            matchingItem.RemarksArray.push(obj);
                                            addArr.push(buildPosteriorSingleRemarkLog(Aitem.InvestigationId, Aitem, newRemark).trim());

                                        }
                                    });
                                    if (Aitem.InvestigationId === 32) {
                                        matchingItem.RHorizontal = Aitem.RHorizontal || matchingItem.RHorizontal || "";
                                        matchingItem.RVertical = Aitem.RVertical || matchingItem.RVertical || "";
                                        matchingItem.RDPS = Aitem.RDPS || matchingItem.RDPS || "";
                                        matchingItem.LHorizontal = Aitem.LHorizontal || matchingItem.LHorizontal || "";
                                        matchingItem.LVertical = Aitem.LVertical || matchingItem.LVertical || "";
                                        matchingItem.LDPS = Aitem.LDPS || matchingItem.LDPS || "";
                                        matchingItem.RemarksArray = [];
                                        addArr.push(buildPosteriorSingleRemarkLog(Aitem.InvestigationId, Aitem).trim());

                                    }
                                }
                            })
                        } else {
                            alertify.error("Please Enter Posterior Data")
                            return;
                        }
                        let finalDesc = addArr.join("\n\n").trim();
                        if (finalDesc !== "") {
                            $scope.ExamLogObj.LogArray.push({
                                LogId: 0,
                                ModuleId: 1,
                                ModuleName: "OUTPatient",
                                SubModuleId: 52,
                                SubModuleName: "Examination",
                                ScreenType: "Posterior Template",
                                ActionType: "Add to Template",
                                OldActionDescription: "",
                                NewActionDescription: `Template Name : ${mitem.TemplateName}\n\nAdded in Template :\n${finalDesc}`,
                                ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                            });

                        }
                        var params = {
                            "UserId": doctorinfo.doctorid,
                            "OrganizationId": hospitalId,
                            "ExaminationTemplateId": mitem.ExaminationTemplateId,
                            "TemplateName": mitem.TemplateName,
                            "PosteriorSegmentArrayNew": TempPosteriorArray || [],
                            "DeleteInd": "N",
                            "IsTemplateFavorites": mitem.IsTemplateFavorites || false,
                            "Logs": {}
                        }
                        if ($scope.ExamLogObj.LogArray.length > 0) {
                            params.Logs = $scope.ExamLogObj || {};
                        }
                        eHnotePatientDataService.AddUpdatePosteriorTemplateDetails(params).then(function (resp) {
                            if (resp.data != undefined && resp.data != "") {
                                alertify.success("Update successfully");
                                GetPosteriorTemplateDetails();
                            };

                        }, function (err) {

                        });
                    }

