        $scope.GetAnteriorTemplateDetails = function () {
            var params = {
                "UserId": doctorinfo.doctorid,
                "SearchText": "",
                "PageSize": 50,
                "PageNumber": $scope.AssescurrentPage || 1,
                "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "IsFavoriteInd": 0
            }
            eHnotePatientDataService.GetUserAnteriorTemplateDetails(params).then(function (resp) {
                if (resp.data.Status == "Success") {
                    let allTemplates = resp.data.rows || [];
                    let TempAnteriorfavariotes = allTemplates.filter(item => item.IsTemplateFavorites);
                    let nonFavorites = allTemplates.filter(item => !item.IsTemplateFavorites);
                    $scope.ExamAnteriorTemplateData = TempAnteriorfavariotes.concat(nonFavorites);
                    $scope.ExamLogObj.ExamAnteriorTemplateData = $scope.ExamAnteriorTemplateData || [];
                } else {
                    $scope.ExamAnteriorTemplateData = [];
                }


            }, function (err) {

            });
        }

        $scope.TemplateDropdownOpen = function (Type) {
            if (Type == 'Anterior') {
                $scope.GetAnteriorTemplateDetails();
            } else if (Type == 'Posterior') {
                $scope.GetPosteriorTemplateDetails();
            }

        }

        $scope.IsAnteriorTemplateAlreadyAdded = false;
        $scope.IsPosteriorTemplateAlreadyAdded = false;
        $scope.AnteriorTemplateId = 0;
        /* ----------------------------------------------------------------------------
           Rebuilds one stored template remark as a fresh, unsaved remark
           ----------------------------------------------------------------------------
           This used to be twelve hand-written object literals - one per template code
           path - each listing the same twelve fields. Anything the literals did not
           list was dropped on the way from the template into the examination model,
           and because Save serialises that very model (see FilteredAnteriorSegmentList
           / FilteredPosteriorSegmentList), whatever the binding dropped could never be
           saved. Notes and FindingName were pinned to "", IsFavoriteInd and
           DiagnosisList were not carried at all - so a finding entered by hand and the
           same finding restored from a template were NOT the same object, and only the
           hand-entered one saved completely.

           Carrying the stored remark through instead of re-listing its fields keeps
           every value the template holds, including any field added to the model later,
           and leaves exactly one place where a template remark is built. Only the
           identity and per-session fields are reset, which is what makes it a NEW
           remark rather than an edit of the saved one.
           ---------------------------------------------------------------------------- */
        /* ----------------------------------------------------------------------------
           Restores the display flags on a remark that came back from storage
           ----------------------------------------------------------------------------
           IsCheckFindingValue is a DISPLAY flag, not a stored one. The examination
           load callbacks have always stamped it back on by hand after fetching a saved
           examination - that inline pass is what this function was extracted from, and
           it is the reason sub-findings only appeared once you went Save -> Summary ->
           Edit/Add: that route reloads the examination and runs the stamp, while
           selecting a template does not go through it at all. The values were in the
           model the whole time (which is why Save and the Summary showed them); they
           simply failed the UI's filter, which is strict:

               getSubFindingsBracketText() -> filter(SubFindingList, {IsCheckFindingValue:true}, true)
               the Dx row                  -> filter(DiagnosisList,  {DeleteInd:'N'})

           So the fix is not to relax the filters or to add markup - it is to run the
           same preparation step on template data that loaded data already gets.
           ---------------------------------------------------------------------------- */
        function normalizeRestoredRemarkSelections(remark) {
            if (!remark) { return; }

            // a stored sub-finding is by definition one that was selected
            remark.SubFindingList = remark.SubFindingList || [];
            angular.forEach(remark.SubFindingList, function (subitem) {
                subitem.IsCheckFindingValue = true;
            });

            // only normalise a diagnosis list that is actually there, so this never
            // introduces the property on remarks that never had one
            if (angular.isArray(remark.DiagnosisList)) {
                angular.forEach(remark.DiagnosisList, function (dx) {
                    if (!dx.DeleteInd) { dx.DeleteInd = 'N'; }
                    if (dx.IsSelected === undefined || dx.IsSelected === null) {
                        dx.IsSelected = dx.DeleteInd !== 'Y';
                    }
                });
            }
        }

        function newExamTemplateRemark(source, investigationId, levelIdKey) {
            var remark = angular.copy(source) || {};

            // the sub-findings come back as a fresh set too
            remark.SubFindingList = remark.SubFindingList || [];
            angular.forEach(remark.SubFindingList, function (sub) {
                sub[levelIdKey] = 0;
            });

            // identity: unsaved, and attached to the investigation being restored
            remark.RemarksId = 0;
            remark.FindingId = investigationId || 0;
            remark.ActiveInd = 'Y';

            // per-session UI state never travels with a template
            remark.IsShowNotesTextBox = false;

            // defaults for anything the stored remark happens not to carry, so the
            // shape still matches what manual entry produces
            remark.InvFindingId = remark.InvFindingId || 0;
            remark.FindingValue = remark.FindingValue || '';
            remark.OrganId = remark.OrganId || 1;
            remark.FindingName = remark.FindingName || '';
            remark.DiagnosisRiskLevel = remark.DiagnosisRiskLevel || '';
            remark.Notes = remark.Notes || '';
            remark.IsFavoriteInd = remark.IsFavoriteInd || false;
            remark.StampsArray = remark.StampsArray || [];
            remark.DiagnosisList = remark.DiagnosisList || [];

            // the same preparation a loaded examination gets, so a restored
            // finding reaches the UI in the state manual entry leaves it in
            normalizeRestoredRemarkSelections(remark);

            return remark;
        }

        $scope.ExamAnteriorConfirmPopup = function (TemplateData) {
            $scope.AnteriorSegmentArrayNew = $scope.AnteriorSegmentArrayNew || [];

            var TempAnteriorArray = TemplateData.AnteriorSegmentArrayNew || [];

            if ($scope.AnteriorSegmentArrayNew.length > 0 && $scope.IsAnteriorTemplateAlreadyAdded && $scope.AnteriorTemplateId !== TemplateData.ExaminationTemplateId) {
                let Obj = {
                    "TemplateData": TemplateData
                }
                let mInstanceAdd = $uibModal.open({
                    "templateUrl": "AnteriorConfirmPopupTemplate.html",
                    "size": "md",
                    "backdrop": "static",
                    "keyboard": false,
                    //"scope": $scope,
                    "resolve": {
                        "MainObj": function () { return Obj }
                    },

                    "controller": function ($scope, $uibModal, $uibModalInstance, MainObj) {

                        var ExaminationTemplateData = MainObj.TemplateData || [];

                        $scope.AddOrReplaceAnteriorData = function (action) {
                            $uibModalInstance.close({
                                TemplateData: ExaminationTemplateData,
                                Action: action
                            });

                        }

                        $scope.uibclose = function () {
                            $uibModalInstance.dismiss("cancel");
                        };

                    }
                });
                mInstanceAdd.result.then(function (resp) {
                    $scope.AddReplaceAnteriorTemplateData(resp.TemplateData, resp.Action);
                }, function () { });
            }
            else if ($scope.AnteriorSegmentArrayNew.length == 0 || !$scope.IsAnteriorTemplateAlreadyAdded) {

                var temparray = $filter("filter")($scope.FindingCheckValuesList, { "CategoryId": 5 }, true);
                if (TempAnteriorArray.length > 0) {
                    angular.forEach(TempAnteriorArray, function (Aitem) {
                        let matchingItem = $scope.AnteriorSegmentArrayNew.find(function (Mitem) {
                            return Mitem.InvestigationId === Aitem.InvestigationId;
                        });

                        if (!matchingItem) {
                            // No match found, create new object and add it to AnteriorSegmentArrayNew
                            if (Aitem.InvestigationId !== 6) {
                                var object = {
                                    "PatientFindingAnteriorId": 0,
                                    "IsNormal": false,
                                    "CategoryId": Aitem.CategoryId || 5,
                                    "CategoryDesc": Aitem.CategoryName || "Anterior Segment",
                                    "ActiveInd": "Y",
                                    "InvestigationId": Aitem.InvestigationId || 0,
                                    "InvestigationDesc": Aitem.InvestigationDesc || "",
                                    "SelectedGlobalSearch": "",
                                    "SelectedRightEye": 1,
                                    "SelectedLeftEye": 0,
                                    "OrderBY": Aitem.OrderBY,
                                    "ODSearchObj": "",
                                    "OSSearchObj": "",
                                    "IsOdGridViewShow": false,
                                    "IsOsGridViewShow": false,
                                    "RemarksArray": [],
                                };
                                angular.forEach(Aitem.RemarksArray, function (Mitem) {
                                    Mitem.SubFindingList = Mitem.SubFindingList || [];
                                    if (Mitem.SubFindingList.length > 0) {
                                        angular.forEach(Mitem.SubFindingList, function (aitem) {
                                            aitem.AnteriorSegmentRemarksLevelId = 0;
                                        });
                                    }
                                    var obj = newExamTemplateRemark(Mitem, Aitem.InvestigationId, "AnteriorSegmentRemarksLevelId");
                                    object.RemarksArray.push(obj);
                                });
                                $scope.AnteriorSegmentArrayNew.push(object);
                            }
                            else if (Aitem.InvestigationId == 6) {
                                var obj1 = {
                                    "PatientFindingAnteriorId": 0,
                                    "ActiveInd": "Y",
                                    "IsNormal": false,
                                    "CategoryId": Aitem.CategoryId || 5,
                                    "CategoryDesc": Aitem.CategoryName || "Anterior Segment",
                                    "InvestigationId": Aitem.InvestigationId || 0,
                                    "InvestigationDesc": Aitem.InvestigationDesc || "",
                                    "OrderBY": Aitem.OrderBY,
                                    "RemarksArray": [],
                                    "RMRD1": Aitem.RMRD1 || "",
                                    "RMRDcNS": Aitem.RMRDcNS || "",
                                    "RMRD2": Aitem.RMRD2 || "",
                                    "RLF": Aitem.RLF || "",
                                    "RPFH": Aitem.RPFH || "",
                                    "LMRD1": Aitem.LMRD1 || "",
                                    "LMRDcNS": Aitem.LMRDcNS || "",
                                    "LMRD2": Aitem.LMRD2 || "",
                                    "LLF": Aitem.LLF || "",
                                    "LPFH": Aitem.LPFH || "",
                                }
                                $scope.AnteriorSegmentArrayNew.push(obj1);
                            }
                        } else if (matchingItem || Aitem.RemarksArray.length > 0) {
                            // Matching item found, check for new remarks
                            angular.forEach(Aitem.RemarksArray, function (newRemark) {

                                angular.forEach(temparray, function (Mitem) {
                                    let existingdata = matchingItem.RemarksArray.find(function (item) {
                                        return Mitem.InvFindingId === item.InvFindingId
                                    })

                                    if (existingdata) {
                                        for (let i = matchingItem.RemarksArray.length - 1; i >= 0; i--) {
                                            let remark = matchingItem.RemarksArray[i];
                                            if (remark.InvFindingId === Mitem.InvFindingId && remark.OrganId === newRemark.OrganId && remark.RemarksId === 0) {
                                                matchingItem.RemarksArray.splice(i, 1);
                                            } else if (remark.InvFindingId === Mitem.InvFindingId && remark.OrganId === newRemark.OrganId && remark.RemarksId != 0) {
                                                remark.ActiveInd = 'N';
                                            }
                                        }
                                    }

                                });



                                let existingRemark = matchingItem.RemarksArray.find(function (remark) {
                                    return remark.InvFindingId === newRemark.InvFindingId
                                        && remark.OrganId === newRemark.OrganId
                                        && remark.ActiveInd === "Y";
                                });

                                if (!existingRemark) {
                                    newRemark.SubFindingList = newRemark.SubFindingList || [];
                                    if (newRemark.SubFindingList.length > 0) {
                                        angular.forEach(newRemark.SubFindingList, function (aitem) {
                                            aitem.AnteriorSegmentRemarksLevelId = 0;
                                        });
                                    }
                                    var obj = newExamTemplateRemark(newRemark, Aitem.InvestigationId, "AnteriorSegmentRemarksLevelId");
                                    matchingItem.RemarksArray.push(obj);
                                }
                            });
                            if (Aitem.InvestigationId === 6) {
                                matchingItem.RMRD1 = Aitem.RMRD1 || matchingItem.RMRD1 || '';
                                matchingItem.RMRDcNS = Aitem.RMRDcNS || matchingItem.RMRDcNS || '';
                                matchingItem.RMRD2 = Aitem.RMRD2 || matchingItem.RMRD2 || '';
                                matchingItem.RLF = Aitem.RLF || matchingItem.RLF || '';
                                matchingItem.RPFH = Aitem.RPFH || matchingItem.RPFH || '';
                                matchingItem.LMRD1 = Aitem.LMRD1 || matchingItem.LMRD1 || '';
                                matchingItem.LMRDcNS = Aitem.LMRDcNS || matchingItem.LMRDcNS || '';
                                matchingItem.LMRD2 = Aitem.LMRD2 || matchingItem.LMRD2 || '';
                                matchingItem.LLF = Aitem.LLF || matchingItem.LLF || '';
                                matchingItem.LPFH = Aitem.LPFH || matchingItem.LPFH || '';
                                matchingItem.RemarksArray = [];
                            }
                        }
                    })
                }



                $scope.IsAnteriorTemplateAlreadyAdded = true;
            }


            //for fevchecking

            angular.forEach($scope.Anteriorfavariotes, function (item, index) {
                item.IsChecked = false;

            });
            angular.forEach($scope.AnteriorLeftfavariotes, function (item, index) {
                item.IsChecked = false;

            });

            angular.forEach($scope.AnteriorSegmentArrayNew, function (mainitem) {
                angular.forEach(mainitem.RemarksArray, function (Aitem) {

                    if (Aitem.OrganId == 1 && Aitem.ActiveInd == "Y") {
                        angular.forEach($scope.Anteriorfavariotes, function (item, index) {
                            if (Aitem.InvFindingId == item.InvFindingId) {
                                item.IsChecked = true;
                            }
                        });
                    }
                    else if (Aitem.OrganId == 2 && Aitem.ActiveInd == "Y") {
                        angular.forEach($scope.AnteriorLeftfavariotes, function (item, index) {
                            if (Aitem.InvFindingId == item.InvFindingId) {
                                item.IsChecked = true;
                            }
                        });
                    }

                });
            });


            angular.forEach($scope.AnteriorSegmentArrayNew, function (mitem) {
                if (mitem.RemarksArray.length > 0) {
                    angular.forEach(mitem.RemarksArray, function (subitem) {
                        subitem.IsFavoriteInd = false;
                    });
                }
            });

            angular.forEach($scope.AnteriorSegmentArrayNew, function (mitem) {
                if (mitem.RemarksArray.length > 0) {
                    angular.forEach(mitem.RemarksArray, function (subitem) {
                        if (subitem.OrganId == 1 && subitem.ActiveInd == "Y") {
                            let match = $scope.Anteriorfavariotes.filter(function (localItem) {
                                return localItem.InvFindingId == subitem.InvFindingId;
                            }) || [];
                            if (match.length > 0) {
                                subitem.IsFavoriteInd = true;
                            }
                        } else if (subitem.OrganId == 2 && subitem.ActiveInd == "Y") {
                            let match = $scope.AnteriorLeftfavariotes.filter(function (localItem) {
                                return localItem.InvFindingId == subitem.InvFindingId;
                            }) || [];
                            if (match.length > 0) {
                                subitem.IsFavoriteInd = true;
                            }
                        }

                    });
                }

            });

            if ($scope.AnteriorTemplateId == TemplateData.ExaminationTemplateId) {
                $scope.AddReplaceAnteriorTemplateData(TemplateData, 'Add')
            }
            $scope.AnteriorTemplateId = TemplateData.ExaminationTemplateId || 0;

            $scope.SyncIsNormalOnTemplateCopy(5);
        }

