        $scope.GetPosteriorTemplateDetails = function () {
            var params = {
                "UserId": doctorinfo.doctorid,
                "SearchText": "",
                "PageSize": 50,
                "PageNumber": $scope.AssescurrentPage || 1,
                "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "IsFavoriteInd": 0
            }
            eHnotePatientDataService.GetUserPosteriorTemplateDetails(params).then(function (resp) {
                if (resp.data.Status == "Success") {
                    let allTemplates = resp.data.rows || [];
                    let TempPosteriorfavariotes = allTemplates.filter(item => item.IsTemplateFavorites);
                    let nonFavorites = allTemplates.filter(item => !item.IsTemplateFavorites);
                    $scope.ExamPosteriorTemplateData = TempPosteriorfavariotes.concat(nonFavorites);
                    $scope.ExamLogObj.ExamPosteriorTemplateData = $scope.ExamPosteriorTemplateData || [];
                } else {
                    $scope.ExamPosteriorTemplateData = [];
                    $scope.ExamLogObj.ExamPosteriorTemplateData = [];
                }

            }, function (err) {

            });
        }

        $scope.PosteriorTemplateId = 0;

