        $scope.RemoveSuperBillDiagnosisById = function (item, Mainitem) {
            if (item.SuperbillItemDiagnosisId == 0) {
                Mainitem.DiagnosisArray = Mainitem.DiagnosisArray || [];
                let index = Mainitem.DiagnosisArray.findIndex(sitem => sitem.DiagnosisId == item.DiagnosisId);
                if (index > -1) {
                    Mainitem.DiagnosisArray.splice(index, 1);
                }
            }
            else {
                item.DeleteInd = 'Y';
            }
            if (Mainitem.AddDiagnosisAssesmentPlanArray.length > 0) {
                Mainitem.AddDiagnosisAssesmentPlanArray.forEach(nitem => {
                    if (item.DiagnosisId == nitem.DiagnosisId) {
                        nitem.IsCheckedDiagnosis = false;
                    }
                });
            }
        }

        $scope.SaveFavoriteFindingValues = function (event, item, CategoryId, CategoryName) {
            event.stopPropagation();
            item.IsFavoriteInd = !item.IsFavoriteInd || false;

            var params = {
                "UserId": doctorinfo.doctorid,
                "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "OrganizationFindingValueId": item.InvFindingId || 0,
                //"MasterFindingValueId": 0,
                "DeleteInd": "N",
                "CategoryId": CategoryId || 0,
                "CategoryName": CategoryName || '',
                "FindingId": item.FindingId || 0,
                "FindingName": item.FindingName || '',
                //"OrganizationFindingId": 0,
                "FindingValue": item.FindingValue || "",
                "IsFavoriteInd": item.IsFavoriteInd

            }
            eHnotePatientDataService.AddUpdateOrgFindingValues(params).then(function (resp) {
                if (resp.data.Status === 'Success') {

                    if (item.IsFavoriteInd) {
                        alertify.success('Add Favorite Successfully');
                    } else {
                        alertify.success('Remove Favorite Successfully');
                    }

                    if (CategoryId == 5) {
                        $scope.GetAnteriorOrgFindingValues();
                    } else {
                        $scope.GetPosteriorOrgFindingValues();
                    }
                }
                else {
                    alertify.error(resp.data.Message);

                }
            });
        }
        $scope.anteriornotes1 = {
            templateUrl: 'anteriornotes1.html',
        }

        if ($scope.AnteriorSegmentArrayNew.length > 0) {
            let hasAnteriorData = $scope.AnteriorSegmentArrayNew.some(function (item) {
                var hasRemarks = item.RemarksArray && item.RemarksArray.length > 0;
                var isMRD = item.InvestigationId === 6 && (
                    item.RMRD1 || item.RMRDcNS || item.RMRD2 || item.RLF || item.RPFH ||
                    item.LMRD1 || item.LMRDcNS || item.LMRD2 || item.LLF || item.LPFH
                );
                return hasRemarks || isMRD;
            });
            $scope.IsAnyAnteriorRemarksIsActive = hasAnteriorData;
        }

        if ($scope.PoteriorSegmentArrayNew.length > 0) {
            let hasPosteriorData = $scope.PoteriorSegmentArrayNew.some(function (item) {
                var hasRemarks = item.RemarksArray && item.RemarksArray.length > 0;
                var isCDR = item.InvestigationId === 32 && (
                    item.LVertical || item.LHorizontal || item.LDPS || item.RVertical || item.RHorizontal ||
                    item.RDPS
                );
                return hasRemarks || isCDR;
            });
            $scope.IsAnyPosteriorRemarksIsActive = hasPosteriorData;
        };



