                    $scope.GetAnteriorTemplateDetails = function (Type, item, Tab) {
                        item = item || '';
                        var params = {
                            "UserId": $scope.UserId,
                            "SearchText": "",
                            "PageSize": 50,
                            "PageNumber": 1,
                            "OrganizationId": $scope.HospitalId,
                            "IsFavoriteInd": 0
                        }

                        eHnotePatientDataService.GetUserAnteriorTemplateDetails(params).then(function (resp) {
                            if (resp.data.Status == "Success") {
                                $scope.ExamAnteriorTemplateData = resp.data.rows || [];
                                $scope.ExamLogObj.ExamAnteriorTemplateData = $scope.ExamAnteriorTemplateData || [];
                                if (Type == 'Delete') {
                                    $scope.ChangeTemplate($scope.ExamAnteriorTemplateData[0], Tab);
                                } else if (Type == 'Favorite' || Type == 'Update') {
                                    var TempODArray = $filter('filter')($scope.ExamAnteriorTemplateData, { 'ExaminationTemplateId': item.ExaminationTemplateId }, true) || [];
                                    $scope.ChangeTemplate(TempODArray[0], Tab);
                                }
                            } else {
                                $scope.ExamAnteriorTemplateData = [];
                            }

                        }, function (err) {

                        });
                    };
