        function setAccessRules() {
            if ($scope.cacheStorageItem.OPChartStatus === 'E') {

                $scope.UserAccess.isSummaryMode = true;
                if ($scope.RoleId == 1 || $scope.RoleId == 43 || $scope.RoleId == 10) {
                    $scope.UserAccess.canEditDoctorData = false;
                } else if ($scope.RoleId == 18) {
                    $scope.UserAccess.canEditCoordinatorData = true;
                }
            } else {

                if ($scope.RoleId == 1 || $scope.RoleId == 43 || $scope.RoleId == 10 || $scope.RoleId == 16) {
                    $scope.UserAccess.canEditDoctorData = true;
                    $scope.UserAccess.isSummaryMode = false;
                } else if ($scope.RoleId == 18) {
                    $scope.UserAccess.canEditDoctorData = true;
                    $scope.UserAccess.canEditCoordinatorData = true;
                    $scope.UserAccess.isSummaryMode = false;
                }
            }
        }
        setAccessRules();


