        // Suggested Diagnosis Save data 
        $scope.addDiagnosisForFindingValue = function (inv, item) {
            var GOrganId = parseFloat(inv.OrganId) || 1;
            var obj1 = {
                "InvFindingId": inv.InvFindingId || 0,
                "FindingId": item.InvestigationId,
                "OrganizationId": $scope.HospitalId,
                "OrganId": GOrganId
            }

            eHnotePatientDataService.GetOrgDiagnosisByFindingId(obj1).then(function (resp) {
                if (resp.data.status == "Success") {
                    if (resp.data.DiagnosisList.length > 0) {
                        $scope.SuggestionsObj.ShowSuggestedCodes = true;
                        $scope.SuggestionsObj.SuggestedCodesOrgan = GOrganId == 1 ? 'OD' : 'OS';
                        $scope.SearchDiagnosisList = resp.data.DiagnosisList || [];
                        if ($scope.SearchDiagnosisList.length > 0) {
                            angular.forEach($scope.SearchDiagnosisList, function (item) {
                                item.IsChecked = false;
                                item.InvestigationId = inv.InvestigationId;
                                item.InvestigationDesc = inv.InvestigationDesc;
                                item.InvFindingId = inv.InvFindingId;
                                item.OrganId = item.OrganId || null;
                                item.Organ = inv.OrganId || null;
                            });
                        }

                        if ($scope.AnteriorSegmentArrayNew && $scope.AnteriorSegmentArrayNew.length > 0) {

                            angular.forEach($scope.AnteriorSegmentArrayNew, function (finding) {

                                // Match Investigation first
                                if (finding.InvestigationId != inv.FindingId)
                                    return;

                                angular.forEach(finding.RemarksArray, function (remark) {


                                    remark.DiagnosisList = remark.DiagnosisList || [];


                                    remark.DiagnosisList = remark.DiagnosisList.filter(function (item) {
                                        return item.DeleteInd === 'N';
                                    });
                                    if (remark.DiagnosisList.length > 0) {
                                        angular.forEach(remark.DiagnosisList, function (savedDiag) {

                                            // Match Organ also
                                            if (savedDiag.OrganId != GOrganId)
                                                return;

                                            // Now mark checkbox checked
                                            angular.forEach($scope.SearchDiagnosisList, function (suggestedDiag) {

                                                if (savedDiag.DiagnosisId == suggestedDiag.DiagnosisId) {
                                                    suggestedDiag.IsChecked = true;
                                                }

                                            });

                                        });
                                    }

                                });

                            });

                        }



                        if ($scope.PoteriorSegmentArrayNew && $scope.PoteriorSegmentArrayNew.length > 0) {

                            angular.forEach($scope.PoteriorSegmentArrayNew, function (finding) {

                                // Match Investigation first
                                if (finding.InvestigationId != inv.FindingId)
                                    return;

                                angular.forEach(finding.RemarksArray, function (remark) {
                                    remark.DiagnosisList = remark.DiagnosisList || [];

                                    remark.DiagnosisList = remark.DiagnosisList.filter(function (item) {
                                        return item.DeleteInd === 'N';
                                    });

                                    if (remark.DiagnosisList.length > 0) {
                                        angular.forEach(remark.DiagnosisList, function (savedDiag) {

                                            // Match Organ also
                                            if (savedDiag.OrganId != GOrganId)
                                                return;

                                            // Now mark checkbox checked
                                            angular.forEach($scope.SearchDiagnosisList, function (suggestedDiag) {

                                                if (savedDiag.DiagnosisId == suggestedDiag.DiagnosisId) {
                                                    suggestedDiag.IsChecked = true;
                                                }

                                            });

                                        });
                                    }

                                });

                            });

                        }
                    } else {
                        // Suppressed: the Edit popup calls addDiagnosisForFindingValue() on every open, so a finding with no suggested codes raised this on each open.
                        // alertify.error("No Adviced Diagnosis");
                        return false;
                    }

                }

            }, function (err) {
                console.log(err);
            });

            $scope.AddToCache();
        };



