        // ── Labs & Studies Patient / Guardian signature ──
        // One signature for Labs & Studies, by the Patient or the Guardian, captured with the ASC Admit signature popup
        // (mouse / touch drawing, or the Topaz sign pad) and kept as the base64 PNG data URL like the Admit signature.
        // Saved with the Labs & Studies request.
        $scope.LabsStudiesSignerTypes = ["Patient", "Guardian"];

        // Patient -> patient's name; Guardian -> the Guardian on the patient profile (editable in the signature popup)
        function getLabsStudiesDefaultSignerName(SignerType) {
            let Patient = (($scope.selectedPatientData || {}).Patient || [])[0] || {};
            if (SignerType === "Patient") {
                return Patient.FullName || '';
            }
            if (SignerType === "Guardian") {
                return Patient.Guardian || '';
            }
            return '';
        }

        // a different signer must sign again, so a signature captured for the previous signer is removed
        $scope.OnLabsStudiesSignerTypeChange = function (temp) {
            temp.PatientGuardianSignerName = getLabsStudiesDefaultSignerName(temp.PatientGuardianSignerType) || null;
            temp.PatientGuardianEncryptedSig = null;
            temp.PatientGuardianSignedDateTime = null;
            temp.PatientGuardianSignCaptureUserId = null;
            syncCoordinatorSummaryToRequest(temp);
        };

        // Add Signature / Change Signature: the ASC Admit "Accompanied By" signature popup (AscAdmissionCtrl AddAccompaniedSigature,
        // template AccompaniedBySignacturepopover.html) - mouse / touch drawing on a canvas, plus "Using Sign Pad" (Topaz) when the
        // organization's Digital Signature Type is Topaz. Both give the same data:image/png;base64 string.
        $scope.AddLabsStudiesSignature = function (temp) {
            if (!temp.PatientGuardianSignerType) {
                alertify.error("Please Select Patient / Guardian");
                return false;
            }
            // same organization setting the Admit screen reads (OrgDigitalSignType)
            let OrganizationSettingsData = datapersistanceFactory.getItem("OrganizationSettingsData") || {};
            let obj = {
                "SignerType": temp.PatientGuardianSignerType,
                "SignerName": temp.PatientGuardianSignerName || getLabsStudiesDefaultSignerName(temp.PatientGuardianSignerType),
                "OrgDigitalSignType": (OrganizationSettingsData.AppointmentSettings || {}).DigitalSigatureType || 'Drawing',
                "SignString": temp.PatientGuardianEncryptedSig || ''
            };
            let mInstanceAdd = $uibModal.open({
                "templateUrl": "LabsStudiesSignaturepopover.html",
                "backdrop": "static",
                "size": "md",
                "resolve": {
                    "mainObject": function () { return obj; }
                },
                "windowClass": "zindexpopupConsentSign",
                "keyboard": false,
                "controller": ["$scope", "$uibModalInstance", "mainObject", LabsStudiesSignatureCtrl]
            });
            mInstanceAdd.result.then(function (result) {
                if (!result || !result.SignString) {
                    return;
                }
                temp.PatientGuardianSignerName = result.SignerName || '';
                temp.PatientGuardianEncryptedSig = result.SignString;
                temp.PatientGuardianSignedDateTime = $filter('date')(new Date(), "yyyy-MM-dd HH:mm:ss");
                temp.PatientGuardianSignCaptureUserId = $scope.UserId;
                syncCoordinatorSummaryToRequest(temp);
            }, function () {
            });
        };

        $scope.RemoveLabsStudiesSignature = function (temp) {
            alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to Delete?</h4>", function () {
                temp.PatientGuardianEncryptedSig = null;
                temp.PatientGuardianSignedDateTime = null;
                temp.PatientGuardianSignCaptureUserId = null;
                syncCoordinatorSummaryToRequest(temp);
                $scope.$digest();
            }, function () {
            });
        };

        // Controller of LabsStudiesSignaturepopover.html: the Admit AddAccompaniedSigature popup controller.
        // SigWeb (js/SignWebMain.js) is only called once the sign pad is in use: its calls are synchronous requests to the
        // local SigWeb service and throw when it is not running, so drawing with the mouse never depends on it.
        function LabsStudiesSignatureCtrl($scope, $uibModalInstance, mainObject) {
            var tmr;
            var resetIsSupported = false;
            var savedSignCleared = false;   // Clear pressed while editing a saved signature

            $scope.mainObject = mainObject || {};
            $scope.OrgDigitalSignType = $scope.mainObject.OrgDigitalSignType || 'Drawing';

            $scope.signPlusObj = {
                "SignBy": "Drawing",
                "SignString": "",
                "SignerType": $scope.mainObject.SignerType || '',
                "SignerName": $scope.mainObject.SignerName || ''
            };

            function isTopazSign() {
                return $scope.signPlusObj.SignBy == "Topaz";
            }

            function stopTopazSign() {
                if (isTopazSign()) {
                    try {
                        SetTabletState(0, tmr);
                    } catch (e) {
                        console.log(e);
                    }
                    tmr = null;
                }
            }

            // "Using Sign Pad"
            $scope.OnSignPatientSignature = function () {
                if (IsSigWebInstalled()) {
                    $scope.signPlusObj.SignBy = "Topaz";
                    var ctx = document.getElementById('LabsStudiesSign').getContext('2d');
                    SetDisplayPenWidth(5);
                    SetDisplayXSize(1200);
                    SetDisplayYSize(700);
                    SetTabletState(0, tmr);
                    SetJustifyMode(5);
                    ClearTablet();
                    SetEncryptionMode(3);
                    AutoKeyAddData("0000000000000000");
                    SetKeyString("0000000000000000");
                    if (tmr == null) {
                        tmr = SetTabletState(1, ctx, 50);
                    }
                    else {
                        SetTabletState(0, tmr);
                        tmr = null;
                        tmr = SetTabletState(1, ctx, 50);
                    }
                } else {
                    alert("Unable to communicate with SigWeb. Please confirm that SigWeb is installed and running on this PC.");
                }
            };

            $scope.closeuib = function () {
                stopTopazSign();
                $uibModalInstance.dismiss("cancel");
            };

            function GetResetSupported() {
                var minSigWebVersionResetSupport = "1.6.4.0";
                if (isOlderSigWebVersionInstalled(minSigWebVersionResetSupport)) {
                    console.log("Old SigWeb version installed.");
                    return false;
                }
                return true;
            }

            function isOlderSigWebVersionInstalled(cmprVer) {
                var sigWebVer = GetSigWebVersion();
                if (sigWebVer != "") {
                    return isOlderVersion(cmprVer, sigWebVer);
                } else {
                    return false;
                }
            }

            function isOlderVersion(oldVer, newVer) {
                const oldParts = oldVer.split('.')
                const newParts = newVer.split('.')
                for (var i = 0; i < newParts.length; i++) {
                    const a = parseInt(newParts[i]) || 0
                    const b = parseInt(oldParts[i]) || 0
                    if (a < b) return true
                    if (a > b) return false
                }
                return false;
            }

            // SigWeb check on open only for Topaz organizations (the only ones shown "Using Sign Pad")
            $scope.onLoadSIg = function () {
                if (IsSigWebInstalled()) {
                    resetIsSupported = GetResetSupported();
                    if (!resetIsSupported) {
                        var note = document.getElementById("sigWebVrsnNote");
                        if (note) {
                            var sigweb_link = document.createElement("a");
                            sigweb_link.href = "https://www.topazsystems.com/software/sigweb.exe";
                            sigweb_link.innerHTML = "https://www.topazsystems.com/software/sigweb.exe";
                            note.innerHTML = "There is a newer version of SigWeb available here: ";
                            note.appendChild(sigweb_link);
                        }
                    }
                }
                else {
                    alert("Unable to communicate with SigWeb. Please confirm that SigWeb is installed and running on this PC.");
                }
            }
            if ($scope.OrgDigitalSignType == 'Topaz') {
                $scope.onLoadSIg();
            }

            $scope.SaveLabsStudiesDrawSign = function () {
                if (!($scope.signPlusObj.SignerName || '').trim()) {
                    alertify.error("Please Enter " + $scope.signPlusObj.SignerType + " Name");
                    return false;
                }
                if (isTopazSign()) {
                    if (NumberOfTabletPoints() == 0) {
                        alertify.error("Please add Signature");
                        return false;
                    }
                    SetTabletState(0, tmr);
                    var CryptoData = "";
                    CryptoData = "This represents sample data the signer reads and is agreeing to when signing.";
                    CryptoData = CryptoData + "Concatenate all this data into a single variable.";
                    AutoKeyAddANSIData(CryptoData);
                    SetEncryptionMode(2);
                    SetSigCompressionMode(2);
                    SetImageXSize(1200);
                    SetImageYSize(800);
                    SetImagePenWidth(10);
                    GetSigImageB64(function (str) {
                        $scope.signPlusObj.SignString = "data:image/png;base64," + str;
                        alertify.success("Signature added Successfully ");
                        $uibModalInstance.close($scope.signPlusObj);
                    });
                } else {
                    // mouse / touch drawing: an untouched canvas gives the same image as a new blank canvas of its size
                    var canvas = document.getElementById('LabsStudiesSign');
                    var blank = document.createElement('canvas');
                    blank.width = canvas.width;
                    blank.height = canvas.height;
                    var sign = canvas.toDataURL();
                    if (sign == blank.toDataURL()) {
                        alertify.error("Please sign to continue");
                        return false;
                    }
                    $scope.signPlusObj.SignString = sign;
                    alertify.success("Signature added Successfully ");
                    $uibModalInstance.close($scope.signPlusObj);
                }
            };

            $scope.OnClearLabsStudiesSignature = function () {
                if (isTopazSign()) {
                    try {
                        ClearTablet();
                    } catch (e) {
                        console.log(e);
                    }
                    stopTopazSign();
                }
                var canvas = document.getElementById('LabsStudiesSign');
                var context = canvas.getContext('2d');
                // The "drawing" directive (app.js) strokes one path that only restarts on mousedown, and stops drawing only
                // on a mouseup over the canvas. A stroke released outside the canvas leaves it drawing, and the next
                // mousemove re-strokes the whole old path. End that stroke and drop the old path, not just the pixels.
                canvas.dispatchEvent(new MouseEvent('mouseup'));
                context.clearRect(0, 0, canvas.width, canvas.height);
                context.beginPath();
                savedSignCleared = true;
                $scope.signPlusObj.SignBy = 'Drawing';
                $scope.signPlusObj.SignString = '';
            };

            // Change Signature: show the current signature on the canvas, as Admit does
            $uibModalInstance.rendered.then(function () {
                if ($scope.mainObject.SignString) {
                    var canvas = document.getElementById("LabsStudiesSign");
                    var ctx = canvas.getContext("2d");
                    ctx.clearRect(0, 0, canvas.width, canvas.height);
                    var image = new Image();
                    image.onload = function () {
                        // cleared before the saved signature finished loading: do not bring it back
                        if (!savedSignCleared) {
                            ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
                        }
                    };
                    image.src = $scope.mainObject.SignString;
                }
            });
        }

        // fields read by the Pre-Op print header helpers (getPatientBranchDetailsTableForASC, getPatientDetailsTableForASC,
        // getPatientSurgeryDetailsTableForASC), taken from the patient and the surgery order the coordinator orders belong to
        function getLabsStudiesPrintHeaderObj(temp) {
            var selectedPatientData = eHnoteMasterDataService.getpatientData();
            var Patient = (selectedPatientData && selectedPatientData.Patient && selectedPatientData.Patient[0]) || {};

            // selected surgery order (same selection the Coordinator Orders tab uses: IsEditData + ISSelectedOrderDetailItem)
            let Surgery = {}, SurgeryDetail = {};
            angular.forEach($scope.AdvisedOrderDetailsArray || [], function (oitem) {
                if (!oitem.IsEditData) return;
                angular.forEach(oitem.OrderDetails || [], function (ditem) {
                    if (ditem.ISSelectedOrderDetailItem) {
                        Surgery = oitem;
                        SurgeryDetail = ditem;
                    }
                });
            });
            let TempSurgery = (temp.SurgeryArray || [])[0] || {};
            let Diagnosis = ($filter("filter")(SurgeryDetail.DiagnosisList || [], function (dg) {
                return (dg.DeleteInd || 'N') === 'N';
            }) || []).map(function (dg) {
                return (dg.ICD10CODE || '') + ' - ' + (dg.DiagnosisName || '');
            }).join(', ');

            return {
                "EhnoteLogoURL": $scope.HeaderLogo || '',
                "Name": Patient.FullName || '',
                "PatientDisplayId": Patient.PatientDisplayId || '',
                "PatientDOB": Patient.DOB || '',
                "Age": $scope.PatientAge || '',
                "Gender": Patient.Gender || '',
                "VisitReason": $scope.Appointmentinfo.VisitReason || '',
                "CPTCode": SurgeryDetail.ProcedureCode || Surgery.ProcedureCode || TempSurgery.ProcedureCode || '',
                "SurgeryName": SurgeryDetail.Description || Surgery.Description || TempSurgery.SurgeryName || '',
                "AdditionalSurgeryName": '',
                "Diagnosis": Diagnosis,
                "OrganName": GetEyeName(SurgeryDetail.OrganId || temp.OrganId) || '',
                "SurgeryEyeStatusId": SurgeryDetail.EyeOrder || 0,
                "SurgeryDate": SurgeryDetail.AscAppointmentDate || '',
                "Surgeon": SurgeryDetail.SurgeonName || temp.ASCSurgeryTemplateUserName || '',
                "Anesthetist": SurgeryDetail.AnesthetistName || ''
            };
        }


