        $scope.loadCoordinatorOrderTemplates = function (val, DoctorID) {
            let req = {
                "ParentOrganizationId": $scope.ParenthospitalId,
                "HospitalID": $scope.HospitalId,
                "DoctorId": DoctorID,
                "SearchText": val || "",
                "PageNumber": $scope.AscTemplateScreenObj.Pageno || 1,
                "PageSize": 500,
                "CPTCODE": val || '',
            }
            let creq = {
                "ParentOrganizationId": $scope.ParenthospitalId,
                "HospitalID": $scope.HospitalId,
                "DoctorId": DoctorID,
                "SearchText": val || "",
                "PageNumber": $scope.AscTemplateScreenObj.Pageno || 1,
                "PageSize": 500,
                "CPTCODE": val || '',
                "PatientId": $scope.PatientId || 0,
            }
            $q.all([
                eHnoteSurgeryService.GetAscSurgeryOrderTemplates(req),
                eHnoteSurgeryService.GetAscCoordinatorSurgeryOrderTemplates(creq)
            ]).then(function (res) {

                $scope.AscTemplateScreenObj.TemplateList = [];

                let surgeryList = res[0].data.TemplateList || [];
                let coordinatorListResp = res[1].data.TemplateList || [];

                // ✅ 1. Get selected items (ONLY ONCE)
                let SelectedTemplist = [];

                ($scope.AdvisedOrderDetailsArray || []).forEach(oitem => {
                    if (!oitem.IsEditData) return;

                    (oitem.OrderDetails || []).forEach(ditem => {
                        if (ditem.ISSelectedOrderDetailItem) {
                            SelectedTemplist.push(ditem);
                        }
                    });
                });

                if (!SelectedTemplist.length) return;

                let OrgSurgeryId = SelectedTemplist[0].OrgDescriptionId || 0;
                let organId = Number(SelectedTemplist[0].OrganId) || 0;

                // ✅ 2. Coordinator filter
                let coordinatorList = (coordinatorListResp || []).filter(mitem => {

                    if (mitem.ASCSurgeryTemplateUserId !== DoctorID) return false;

                    return (mitem.SurgeryArray || []).some(s =>
                        s.OrgSurgeryId === OrgSurgeryId
                    );
                });

                // ✅ 3. Source selection
                let sourceList = coordinatorList.length ? coordinatorList : surgeryList;

                // ✅ 4. Template filter
                let AscTemplateList = (sourceList || []).filter(item =>
                    item.ASCSurgeryTemplateUserId === DoctorID &&
                    Number(item.OrganId) === organId
                );

                // ✅ 5. Final result
                AscTemplateList.forEach(mitem => {

                    let templist = (mitem.SurgeryArray || []).filter(s =>
                        s.OrgSurgeryId === OrgSurgeryId
                    );

                    if (templist.length) {
                        //$scope.IsDisiableButtonInd = true;

                        $scope.AscTemplateScreenObj.TemplateList.push({
                            ...mitem,
                            SurgeryArray: templist
                        });
                    }
                });

                $scope.AsctemplateObj = {};
            });
        }



