        $scope.openLocationPosteriorPopup = function (mitem, parentItem, organId) {

            if (!$scope.NewPosteriorFindingsMasterArray || !mitem) {
                return;
            }

            var masterFinding = $scope.NewPosteriorFindingsMasterArray.find(function (f) {
                return Number(f.InvFindingId) === Number(mitem.InvFindingId);
            });

            if (!masterFinding) {
                return;
            }

            if (!angular.isArray(masterFinding.FindingsValues) ||
                masterFinding.FindingsValues.length === 0) {
                return;
            }

            var currentRemark = null;

            if (parentItem && angular.isArray(parentItem.RemarksArray)) {

                currentRemark = parentItem.RemarksArray.find(function (r) {

                    return Number(r.InvFindingId) === Number(mitem.InvFindingId) &&
                        Number(r.OrganId) === Number(organId) &&
                        r.ActiveInd === "Y";

                });

            }

            if (!currentRemark) {
                return;
            }

            $scope.locationPopupFinding = mitem;
            $scope.locationPopupRemark = currentRemark;
            $scope.locationPopupOrganId = organId;

            // Master copy
            $scope.locationPopupSubOptions = angular.copy(masterFinding.FindingsValues);

            // Default unselect
            angular.forEach($scope.locationPopupSubOptions, function (opt) {
                opt._selected = false;
            });

            // Restore previously selected values
            if (angular.isArray(currentRemark.SubFindingList)) {

                angular.forEach(currentRemark.SubFindingList, function (sub) {

                    if (sub.ActiveInd !== "Y") return;
                    if (!sub.IsCheckFindingValue) return;

                    var match = $scope.locationPopupSubOptions.find(function (opt) {

                        return Number(opt.InvFindingLevelId) === Number(sub.InvFindingLevelId);

                        // If required use both:
                        // return Number(opt.InvFindingId) === Number(sub.InvFindingId) &&
                        //        Number(opt.InvFindingLevelId) === Number(sub.InvFindingLevelId);

                    });

                    if (match) {
                        match._selected = true;
                    }

                });

            }

            console.table($scope.locationPopupSubOptions);
            console.table(currentRemark.SubFindingList);

            $uibModal.open({

                templateUrl: "locationPopup.html",
                keyboard: false,
                backdrop: "static",
                scope: $scope,
                windowClass: "modal__twentyfive--",

                controller: function ($scope, $uibModalInstance) {

                    $scope.uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    };
                    $scope.doneLocationPopup = function () {

                        var oldList = $scope.locationPopupRemark.SubFindingList || [];

                        angular.forEach($scope.locationPopupSubOptions, function (opt) {

                            var existing = oldList.find(function (x) {
                                return Number(x.InvFindingLevelId) === Number(opt.InvFindingLevelId);
                            });

                            if (opt._selected) {

                                if (existing) {

                                    existing.IsCheckFindingValue = true;
                                    existing.ActiveInd = "Y";
                                    existing.DeleteInd = "N";

                                }
                                else {

                                    oldList.push({
                                        PosteriorSegmentRemarksLevelId: 0,   // <-- Posterior identity
                                        InvFindingId: opt.InvFindingId,
                                        InvFindingLevelId: opt.InvFindingLevelId,
                                        LevelType: opt.LevelType,
                                        FindingValue: opt.FindingValue,
                                        ActiveInd: "Y",
                                        DeleteInd: "N",
                                        IsCheckFindingValue: true
                                    });

                                }

                            }
                            else {

                                if (existing) {

                                    if (existing.PosteriorSegmentRemarksLevelId == 0) {

                                        var idx = oldList.indexOf(existing);
                                        if (idx != -1)
                                            oldList.splice(idx, 1);

                                    } else {

                                        existing.ActiveInd = "N";
                                        existing.DeleteInd = "Y";
                                        existing.IsCheckFindingValue = false;

                                    }

                                }

                            }

                        });

                        $scope.locationPopupRemark.SubFindingList = oldList;

                        $uibModalInstance.close();

                    };

                }

            });

        };


