        $scope.CopyToOSS = function (Mitem, item, organ, CategoryId) {


            var tabPopoverParent = Mitem || "";
            var tabPopoverItem = item || '';

            if (!tabPopoverParent || !tabPopoverItem) return;         // ← Add this
            if (!tabPopoverParent.RemarksArray) {                     // ← Add this
                tabPopoverParent.RemarksArray = [];
            }


            var temparray = $filter("filter")($scope.FindingCheckValuesList, { "CategoryId": CategoryId }, true);

            let abnormalcount = 0;

            if (Mitem.RemarksArray.length > 0) {
                angular.forEach(Mitem.RemarksArray, function (hitem, index) {
                    angular.forEach(temparray, function (tempitem) {
                        if (hitem.InvFindingId === tempitem.InvFindingId && hitem.OrganId == organ) {
                            if (hitem.RemarksId === 0) {
                                Mitem.RemarksArray.splice(index, 1);
                            } else {
                                hitem.ActiveInd = 'N';
                            }
                        }
                    });
                });
            }

            // Check if the item already exists in RemarksArray and update Notes
            var existingItem = $filter("filter")(Mitem.RemarksArray, function (remark) {
                return remark.InvFindingId === item.InvFindingId && remark.OrganId === organ && remark.ActiveInd === 'Y';
            })[0]; // Take the first match if found

            if (existingItem) {

                existingItem.Notes = item.Notes || '';
                existingItem.ActiveInd = 'Y';

                // Latest Sub Findings ni overwrite cheyyi
                existingItem.SubFindingList = angular.copy(item.SubFindingList || []);

                angular.forEach(existingItem.SubFindingList, function (sf) {
                    sf.AnteriorSegmentRemarksLevelId = 0;
                    sf.PosteriorSegmentRemarksLevelId = 0;
                });

            }
            else {
                // If item doesn't exist, add a new one
                var newSubFindings = angular.copy(item.SubFindingList || []);
                angular.forEach(newSubFindings, function (aitem) {
                    aitem.AnteriorSegmentRemarksLevelId = 0;
                    aitem.PosteriorSegmentRemarksLevelId = 0;
                });
                var obj = {
                    "RemarksId": 0,
                    "InvFindingId": item.InvFindingId || 0,
                    "FindingValue": item.FindingValue || '',
                    "OrganId": organ,
                    "FindingId": item.FindingId || 0,
                    "FindingName": item.FindingName || '',
                    "Notes": item.Notes || '',
                    "DiagnosisRiskLevel": "",
                    "ActiveInd": "Y",
                    "SubFindingList": newSubFindings,
                    "StampsArray": [],
                };

                item.StampsArray = item.StampsArray || [];
                if (item.StampsArray.length > 0) {
                    var filteredStamps = item.StampsArray.filter(function (stamp) {
                        return stamp.OrganId === obj.OrganId;
                    });
                    obj.StampsArray = filteredStamps || [];
                }

                if (abnormalcount == 0) {
                    Mitem.RemarksArray.push(obj);
                }
            }
            if (CategoryId == 5) {
                angular.forEach($scope.Anteriorfavariotes, function (item) {
                    item.IsChecked = false;
                });
                angular.forEach($scope.AnteriorLeftfavariotes, function (item) {
                    item.IsChecked = false;
                });

                angular.forEach($scope.AnteriorSegmentArrayNew, function (mainitem) {
                    angular.forEach(mainitem.RemarksArray, function (Aitem) {

                        if (Aitem.OrganId == 1 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.Anteriorfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        }
                        else if (Aitem.OrganId == 2 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.AnteriorLeftfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        }

                    });
                });
                angular.forEach($scope.AnteriorSegmentArrayNew, function (mitem) {
                    if (mitem.RemarksArray.length > 0) {
                        angular.forEach(mitem.RemarksArray, function (subitem) {
                            if (subitem.OrganId == 1 && subitem.ActiveInd == 'Y') {
                                let match = $scope.Anteriorfavariotes.filter(function (localItem) {
                                    return localItem.InvFindingId == subitem.InvFindingId;
                                }) || [];
                                if (match.length > 0) {
                                    subitem.IsFavoriteInd = true;
                                }
                            } else if (subitem.OrganId == 2 && subitem.ActiveInd == 'Y') {
                                let match = $scope.AnteriorLeftfavariotes.filter(function (localItem) {
                                    return localItem.InvFindingId == subitem.InvFindingId;
                                }) || [];
                                if (match.length > 0) {
                                    subitem.IsFavoriteInd = true;
                                }
                            }

                        });
                    }

                });

            }
            else if (CategoryId == 6) {
                angular.forEach($scope.Posteriorfavariotes, function (item) {
                    item.IsChecked = false;
                });
                angular.forEach($scope.PosteriorLeftfavariotes, function (item) {
                    item.IsChecked = false;
                });
                angular.forEach($scope.PoteriorSegmentArrayNew, function (mainitem) {
                    angular.forEach(mainitem.RemarksArray, function (Aitem) {
                        if (Aitem.OrganId == 1 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.Posteriorfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        } else if (Aitem.OrganId == 2 && Aitem.ActiveInd == 'Y') {
                            angular.forEach($scope.PosteriorLeftfavariotes, function (item, index) {
                                if (Aitem.InvFindingId == item.InvFindingId) {
                                    item.IsChecked = true;
                                }
                            });
                        }

                    });
                });

                angular.forEach($scope.PoteriorSegmentArrayNew, function (mitem) {
                    if (mitem.RemarksArray.length > 0) {
                        angular.forEach(mitem.RemarksArray, function (subitem) {
                            if (subitem.OrganId == 1 && subitem.ActiveInd == 'Y') {
                                let match = $scope.Posteriorfavariotes.filter(function (localItem) {
                                    return localItem.InvFindingId == subitem.InvFindingId;
                                }) || [];
                                if (match.length > 0) {
                                    subitem.IsFavoriteInd = true;
                                }
                            } else if (subitem.OrganId == 2 && subitem.ActiveInd == 'Y') {
                                let match = $scope.PosteriorLeftfavariotes.filter(function (localItem) {
                                    return localItem.InvFindingId == subitem.InvFindingId;
                                }) || [];
                                if (match.length > 0) {
                                    subitem.IsFavoriteInd = true;
                                }
                            }

                        });
                    }

                });

            }

            $scope.SyncIsNormalOnCopy(CategoryId);
        };


        $scope.addDiagnosisForFindingValueTabVersion = function (tabPopoverItem, tabPopoverParent) {

            if (!tabPopoverItem || !tabPopoverParent) return;
            /* captured because the modal controller below takes its own $scope parameter */
            var mainScope = $scope;
            if (!tabPopoverParent.InvestigationId) return;

            var GOrganId = parseFloat(tabPopoverItem.OrganId) || 1;
            var obj1 = {
                "InvFindingId": tabPopoverItem.InvFindingId || 0,
                "FindingId": tabPopoverParent.InvestigationId,
                "OrganizationId": $scope.HospitalId,
                "OrganId": GOrganId
            };

            eHnotePatientDataService.GetOrgDiagnosisByFindingId(obj1).then(function (resp) {
                if (resp.data.status == "Success") {
                    if (resp.data.DiagnosisList.length > 0) {

                        $scope.SearchDiagnosisList = resp.data.DiagnosisList || [];

                        angular.forEach($scope.SearchDiagnosisList, function (item) {

                            item.IsChecked = false;
                            item.InvestigationId = tabPopoverItem.InvestigationId;
                            item.InvestigationDesc = tabPopoverItem.InvestigationDesc;
                            item.InvFindingId = tabPopoverItem.InvFindingId;
                            item.OrganId = item.OrganId || null;
                            item.Organ = tabPopoverItem.OrganId || null;
                        });

                        // ✅ Anterior saved diagnosis → IsChecked = true restore
                        if ($scope.AnteriorSegmentArrayNew && $scope.AnteriorSegmentArrayNew.length > 0) {
                            angular.forEach($scope.AnteriorSegmentArrayNew, function (finding) {
                                if (finding.InvestigationId != tabPopoverItem.FindingId) return;
                                angular.forEach(finding.RemarksArray, function (remark) {
                                    if (remark.InvFindingId != tabPopoverItem.InvFindingId) return;
                                    if (remark.OrganId != GOrganId) return;
                                    if (remark.ActiveInd != 'Y') return;

                                    remark.DiagnosisList = (remark.DiagnosisList || []).filter(function (i) {
                                        return i.DeleteInd === 'N';
                                    });

                                    angular.forEach(remark.DiagnosisList, function (savedDiag) {
                                        angular.forEach($scope.SearchDiagnosisList, function (suggestedDiag) {
                                            if (savedDiag.DiagnosisId == suggestedDiag.DiagnosisId) {
                                                suggestedDiag.IsChecked = true; // ✅ restore
                                            }
                                        });
                                    });
                                });
                            });
                        }

                        // ✅ Posterior saved diagnosis → IsChecked = true restore
                        if ($scope.PoteriorSegmentArrayNew && $scope.PoteriorSegmentArrayNew.length > 0) {
                            angular.forEach($scope.PoteriorSegmentArrayNew, function (finding) {
                                if (finding.InvestigationId != tabPopoverItem.FindingId) return;
                                angular.forEach(finding.RemarksArray, function (remark) {
                                    if (remark.InvFindingId != tabPopoverItem.InvFindingId) return;
                                    if (remark.OrganId != GOrganId) return;
                                    if (remark.ActiveInd != 'Y') return;

                                    remark.DiagnosisList = (remark.DiagnosisList || []).filter(function (i) {
                                        return i.DeleteInd === 'N';
                                    });

                                    angular.forEach(remark.DiagnosisList, function (savedDiag) {
                                        angular.forEach($scope.SearchDiagnosisList, function (suggestedDiag) {
                                            if (savedDiag.DiagnosisId == suggestedDiag.DiagnosisId) {
                                                suggestedDiag.IsChecked = true; // ✅ restore
                                            }
                                        });
                                    });
                                });
                            });
                        }

                        // Modal open
                        $scope.suggestedDxData = {
                            data: {
                                OrganId: GOrganId,
                                FindingValue: tabPopoverItem.FindingValue || tabPopoverItem.FindingDescription || '',
                                DiagnosisList: $scope.SearchDiagnosisList
                            }
                        };

                        let mInstanceAdd = $uibModal.open({
                            "templateUrl": "suggestedDiagnosisPopup.html",
                            "keyboard": false,
                            "backdrop": "static",
                            "scope": $scope,
                            "windowClass": "modal__thirtyfive--",
                            "controller": function ($scope, $uibModalInstance) {

                                $scope.diagnosisList = $scope.suggestedDxData.data.DiagnosisList || [];

                                $scope.uibclose = function () {
                                    $uibModalInstance.dismiss("cancel");
                                };

                                $scope.SaveSelectedDiagnosis = function (popoverItem) {
                                    var selected = $scope.diagnosisList.filter(function (dx) {
                                        return dx.IsChecked;
                                    });

                                    if (selected.length === 0) {
                                        alertify.error("Please select at least one diagnosis");
                                        return;
                                    }

                                    // ✅ tabPopoverItem DiagnosisList లో save చేయి
                                    tabPopoverItem.DiagnosisList = tabPopoverItem.DiagnosisList || [];

                                    angular.forEach(selected, function (dx) {
                                        var exists = tabPopoverItem.DiagnosisList.filter(function (d) {
                                            return d.DiagnosisId == dx.DiagnosisId && d.DeleteInd === 'N';
                                        }).length > 0;

                                        if (!exists) {
                                            tabPopoverItem.DiagnosisList.push({
                                                DiagnosisId: dx.DiagnosisId,
                                                ICD10CODE: dx.ICD10CODE || '',
                                                ICD10DIAGNAME: dx.ICD10DIAGNAME || '',
                                                OrganId: GOrganId,
                                                DeleteInd: 'N',
                                                IsSelected: true
                                            });
                                        }
                                    });

                                    // ✅ Uncheck చేసినవి DeleteInd = 'Y' గా mark చేయి
                                    angular.forEach($scope.diagnosisList, function (dx) {
                                        if (!dx.IsChecked) {
                                            var existing = tabPopoverItem.DiagnosisList.filter(function (d) {
                                                return d.DiagnosisId == dx.DiagnosisId;
                                            })[0];
                                            if (existing) {
                                                existing.DeleteInd = 'Y';
                                            }
                                        }
                                    });

                                    /* same gap as the web/desktop Done button - the modal only wrote
                                       tabPopoverItem.DiagnosisList, so the picked diagnosis never reached
                                       Assessment & Plan -> Provisional. mainScope is the controller scope;
                                       this $scope is the modal child scope, which shadows the name. */
                                    mainScope.SaveSelectedDiagnosis();
                                    $uibModalInstance.close(selected);
                                };
                            }
                        });

                    } else {
                        alertify.error("No Adviced Diagnosis");
                        return false;
                    }
                }
            }, function (err) {
                console.log(err);
            });

            $scope.AddToCache();
        };




        $scope.saveNoteToRemark = function (tabPopoverItem, tabPopoverParent, $event) {

            if ($event) $event.stopPropagation();

            if (!tabPopoverItem || !tabPopoverParent) return;

            if (!tabPopoverParent.RemarksArray) {
                tabPopoverParent.RemarksArray = [];
            }

            var matchedRemark = tabPopoverParent.RemarksArray.filter(function (r) {
                return r.InvFindingId == tabPopoverItem.InvFindingId &&
                    r.OrganId == tabPopoverItem.OrganId &&
                    r.ActiveInd == 'Y';
            })[0];

            if (matchedRemark) {

                matchedRemark.Notes = tabPopoverItem._editingNote || '';

            } else {

                matchedRemark = {
                    InvFindingId: tabPopoverItem.InvFindingId,
                    OrganId: tabPopoverItem.OrganId,
                    ActiveInd: 'Y',
                    Notes: tabPopoverItem._editingNote || ''
                };

                tabPopoverParent.RemarksArray.push(matchedRemark);
            }

            // popover preview kosam kuda update cheyyi
            tabPopoverItem.Notes = matchedRemark.Notes;

            tabPopoverItem.IsShowNotesTextBox = false;

            $scope.AddToCache();
        };







        $scope.ToggleFindingASValue = function (selectedinv, item, CategoryId, Organ) {
            if (Organ == 'OD') {
                selectedinv.SelectedEye = 1;
            } else if (Organ == 'OS') {
                selectedinv.SelectedEye = 2;
            }

            selectedinv.ODAnteriorSearch = '';
            selectedinv.OSAnteriorSearch = '';

            var organId = selectedinv.SelectedEye;

            // Check if already exists in RemarksArray with ActiveInd:'Y'
            var alreadySelected = false;
            var parentItem = null;

            angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                if (Mitem.InvestigationId == item.FindingId) {
                    parentItem = Mitem;
                    angular.forEach(Mitem.RemarksArray, function (Ritem) {
                        if (Ritem.InvFindingId === item.InvFindingId &&
                            Ritem.OrganId == organId &&
                            Ritem.ActiveInd == 'Y') {
                            alreadySelected = true;
                        }
                    });
                }
            });

            if (alreadySelected) {
                // UNSELECT — splice or ActiveInd:'N'
                angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                    if (Mitem.InvestigationId == item.FindingId) {
                        var indexToRemove = -1;
                        angular.forEach(Mitem.RemarksArray, function (Ritem, idx) {
                            if (Ritem.InvFindingId === item.InvFindingId &&
                                Ritem.OrganId == organId &&
                                Ritem.ActiveInd == 'Y') {
                                if (Ritem.RemarksId === 0) {
                                    indexToRemove = idx;
                                } else {
                                    Ritem.ActiveInd = 'N';
                                }
                                if (organId == 1) {
                                    Mitem.IsOdGridViewShow = false;
                                } else {
                                    Mitem.IsOsGridViewShow = false;
                                }
                            }
                        });
                        if (indexToRemove > -1) {
                            Mitem.RemarksArray.splice(indexToRemove, 1);
                        }
                    }
                });
            } else {




                var count = [];
                var i = 0;
                var temparray = $filter("filter")($scope.FindingCheckValuesList, { "CategoryId": CategoryId }, true);

                if ($scope.AnteriorSegmentArrayNew.length > 0) {
                    angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                        Mitem.ODSearchObj = '';
                        Mitem.OSSearchObj = '';
                        if (Mitem.RemarksArray.length > 0) {
                            angular.forEach(Mitem.RemarksArray, function (Ritem) {
                                Ritem.IsShowNotesTextBox = false;
                            });
                        }
                    });
                    angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                        if (Mitem.RemarksArray.length > 0) {
                            count = $filter("filter")(Mitem.RemarksArray, function (fitem, index) { return fitem.InvFindingId === item.InvFindingId && fitem.OrganId === selectedinv.SelectedEye && fitem.ActiveInd == 'Y' });
                            if (count.length !== 0) {
                                i++;
                            }
                        }
                    });
                    angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem, index) {
                        if (Mitem.RemarksArray.length > 0) {
                            angular.forEach(Mitem.RemarksArray, function (hitem, index) {
                                angular.forEach(temparray, function (tempitem, index1) {
                                    if (hitem.OrganId == selectedinv.SelectedEye && hitem.InvFindingId === tempitem.InvFindingId && item.FindingId == Mitem.InvestigationId) {
                                        if (hitem.RemarksId === 0) {
                                            Mitem.RemarksArray.splice(index, 1);
                                        }
                                        else {
                                            hitem.ActiveInd = 'N';
                                        }

                                        if (selectedinv.SelectedEye == 1) {
                                            Mitem.IsOdGridViewShow = false;
                                        } else {
                                            Mitem.IsOsGridViewShow = false;
                                        }

                                    }
                                });

                            });
                        }
                    });
                }

                var temparray = $filter("filter")($scope.FindingCheckValuesList, { "CategoryId": CategoryId }, true);

                var obj = {
                    "RemarksId": 0,
                    "InvFindingId": item.InvFindingId || 0,
                    "FindingValue": item.FindingValue || '',
                    "OrganId": organId,
                    "FindingId": item.FindingId || 0,
                    "FindingName": item.FindingName || '',
                    "DiagnosisRiskLevel": "",
                    "ActiveInd": "Y",
                    "Notes": "",
                    "IsShowNotesTextBox": false,
                    "SubFindingList": [],
                    "StampsArray": [],
                    "IsFavoriteInd": item.IsFavoriteInd || false,
                };

                // Filter stamps
                if (item.StampsArray && item.StampsArray.length > 0) {
                    obj.StampsArray = item.StampsArray.filter(function (stamp) {
                        return stamp.OrganId === organId;
                    });
                }

                var GridList = $filter("filter")(temparray, function (fitem) {
                    return fitem.InvFindingId === item.InvFindingId;
                });

                var existingParent = $filter("filter")($scope.AnteriorSegmentArrayNew, function (m) {
                    return m.InvestigationId == item.FindingId;
                });

                if (existingParent.length == 0) {

                    var object = {
                        "PatientFindingAnteriorId": 0,
                        "IsNormal": false,
                        "CategoryId": 5,
                        "CategoryDesc": "Anterior Segment",
                        "InvestigationId": item.FindingId || 0,
                        "InvestigationDesc": item.FindingName || "",
                        "OrderBY": item.OrderBY || 0,
                        "ActiveInd": "Y",
                        "SelectedGlobalSearch": "",
                        "SelectedRightEye": 1,
                        "SelectedLeftEye": 0,
                        "RemarksArray": [],
                        "ODSearchObj": "",
                        "OSSearchObj": "",
                        "IsOdGridViewShow": organId == 1 ? GridList.length > 0 : false,
                        "IsOsGridViewShow": organId == 2 ? GridList.length > 0 : false,
                    };
                    object.RemarksArray.push(obj);
                    $scope.AnteriorSegmentArrayNew.push(object);
                } else {
                    // Existing parent లో push చేయండి
                    angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                        if (Mitem.InvestigationId == item.FindingId) {
                            Mitem.OrderBY = item.OrderBY || 0;
                            if (organId == 1) {
                                Mitem.IsOdGridViewShow = GridList.length > 0;
                                $scope.cacheStorageItem.AnteriorODIsNormal = false;
                            } else {
                                Mitem.IsOsGridViewShow = GridList.length > 0;
                                $scope.cacheStorageItem.AnteriorOSIsNormal = false;
                            }
                            Mitem.RemarksArray.push(obj);
                        }
                    });
                }

                $scope.cacheStorageItem.AnteriorIsNormal = false;
            }

            // Favorites sync — OD
            if (Organ == 'OD') {
                angular.forEach($scope.Anteriorfavariotes, function (fav) {
                    fav.IsChecked = false;
                });
                angular.forEach($scope.AnteriorSegmentArrayNew, function (Mitem) {
                    angular.forEach(Mitem.RemarksArray, function (Aitem) {
                        angular.forEach($scope.Anteriorfavariotes, function (fav) {
                            if (Aitem.InvFindingId == fav.InvFindingId &&
                                Aitem.OrganId == 1 &&
                                Aitem.ActiveInd == 'Y') {
                                fav.IsChecked = true;
                            }
                        });
                    });
                });
            }

            // Favorites sync — OS
            if (Organ == 'OS') {
                angular.forEach($scope.AnteriorLeftfavariotes, function (favItem) {
                    favItem.IsChecked = $scope.AnteriorSegmentArrayNew.some(function (Mitem) {
                        return Mitem.RemarksArray.some(function (Aitem) {
                            return Aitem.InvFindingId == favItem.InvFindingId &&
                                Aitem.OrganId == 2 &&
                                Aitem.ActiveInd == 'Y';
                        });
                    });
                });
            }
            $scope.refreshAllPairedRemarks();
            $scope.newAnteriorObj.AnteriorSearchObj = '';
            $scope.newAnteriorObj.OSAnteriorSearchObj = '';
        };


