        $scope.isFindingSelected = function (remarksArray, invFindingId, organId) {
            return remarksArray.some(function (x) {
                return Number(x.InvFindingId) === Number(invFindingId) &&
                    Number(x.OrganId) === Number(organId) &&
                    x.ActiveInd === "Y";
            });
        };


        $scope.isCDRSelected = function (item, mitem, organId) {
            if (!mitem || !mitem.FindingValue) return false;

            var parts = mitem.FindingValue.split(' ');
            var value = parts[0] || "";
            var valuetype = parts[1] || "";

            if (organId == 1) {
                if (valuetype == 'V.T.') return item.RVertical == value;
                if (valuetype == 'HZ') return item.RHorizontal == value;
                if (valuetype == 'DPS') return item.RDPS == value;
            } else if (organId == 2) {
                if (valuetype == 'V.T.') return item.LVertical == value;
                if (valuetype == 'HZ') return item.LHorizontal == value;
                if (valuetype == 'DPS') return item.LDPS == value;
            }
            return false;
        };


        $scope.ToggleSelectFevFinding = function (newObj, catid, Mitem, type, aspsitem) {
            let organid = 0;
            if (type == 'OD') {
                organid = 1;
            }
            if (type == 'OS') {
                organid = 2;
            }

            if (catid == 5) {
                Mitem.IsChecked = !Mitem.IsChecked;  // false;
                if (Mitem.IsChecked) {
                    //$scope.ChangeNewSearchValue(catid, Mitem, type);
                    $scope.ToggleFindingASValue(newObj, Mitem, catid, type)
                    //    Mitem.IsChecked = true;
                } else {
                    angular.forEach(aspsitem.RemarksArray, function (hitem, index) {
                        if (hitem.InvFindingId === Mitem.InvFindingId && hitem.OrganId == organid) {
                            if (hitem.RemarksId === 0) {
                                aspsitem.RemarksArray.splice(index, 1);
                            }
                            else {
                                hitem.ActiveInd = 'N';
                            }
                            if (catid === 5) {
                                $scope.cacheStorageItem.AnteriorODIsNormal = false;
                                $scope.cacheStorageItem.AnteriorIsNormal = false;
                            }

                        }
                    });

                }

            } else if (catid == 6) {
                Mitem.IsChecked = !Mitem.IsChecked || false;
                if (Mitem.IsChecked) {
                    //$scope.ChangeNewSearchValue(catid, Mitem, type);
                    $scope.ToggleFindingPSValue(newObj, Mitem, catid, type)
                    //    Mitem.IsChecked = true;
                } else {
                    angular.forEach(aspsitem.RemarksArray, function (hitem, index) {
                        if (hitem.InvFindingId === Mitem.InvFindingId && hitem.OrganId == organid) {
                            if (hitem.RemarksId === 0) {
                                aspsitem.RemarksArray.splice(index, 1);
                            }
                            else {
                                hitem.ActiveInd = 'N';
                            }

                            if (catid === 6) {
                                $scope.cacheStorageItem.PosteriorODIsNormal = false;
                                $scope.cacheStorageItem.PosteriorIsNormal = false;
                            }
                        }
                    });
                }
            }

        }


        var anteriorPanel = null;
        var scrollSyncPromise = null;
        var isProgrammaticScroll = false;


        function initAnteriorPanel() {
            // Old listener cleanup first
            if (anteriorPanel) {
                anteriorPanel.removeEventListener("scroll", onAnteriorScroll);
                anteriorPanel = null;
            }

            var panel = document.getElementById("anteriorScrollPanel");
            if (panel) {
                anteriorPanel = panel;
                anteriorPanel.addEventListener("scroll", onAnteriorScroll);
                console.log("anteriorPanel initialized ✅");
                return true;
            }
            return false;
        }

        // First load
        $timeout(function () {
            if (!initAnteriorPanel()) {
                console.warn("anteriorScrollPanel not found after 500ms");
            }
        }, 500);

        // ✅ Popup open event - mee popup open function lo ee line add cheyyi
        // Example: $scope.openAnteriorPopup = function() { ... }
        // Aa function lo call cheyyi:
        $scope.reinitAnteriorPanel = function () {
            isProgrammaticScroll = false;

            // DOM render avvadam ki wait cheyyi
            $timeout(function () {
                if (!initAnteriorPanel()) {
                    // Retry once more if not found
                    $timeout(function () {
                        initAnteriorPanel();
                    }, 300);
                }
            }, 200); // 200ms - popup animation complete avutundi
        };

        function onAnteriorScroll() {
            if (isProgrammaticScroll) return;
            if (scrollSyncPromise) {
                $timeout.cancel(scrollSyncPromise);
            }
            scrollSyncPromise = $timeout($scope.syncAnteriorSection, 50);
        }

        $scope.syncAnteriorSection = function () {

            if (!anteriorPanel) {
                initAnteriorPanel();

                $timeout(function () {
                    if (anteriorPanel) $scope.syncAnteriorSection();
                }, 100);
                return;
            }
            // ✅ Panel missing unte reinit try cheyyi
            if (!anteriorPanel) {
                initAnteriorPanel();
                return;
            }

            var sections = anteriorPanel.querySelectorAll(".anteriorSection");
            if (!sections || sections.length === 0) return;

            var panelRect = anteriorPanel.getBoundingClientRect();

            // ✅ height 0 unte panel not visible - reinit + retry
            if (panelRect.height === 0) {
                console.warn("Panel height 0 - reinitializing");
                initAnteriorPanel();
                return;
            }

            var current = null;
            angular.forEach(sections, function (sec) {
                var secRect = sec.getBoundingClientRect();
                var relativeTop = secRect.top - panelRect.top;
                var relativeBottom = relativeTop + secRect.height;
                if (relativeTop <= 20 && relativeBottom > 20) {
                    current = sec;
                }
            });

            if (!current) return;

            var id = parseInt(current.id.replace("sectionAnterior", ""));
            if ($scope.activeAnteriorId === id) return;

            var matchedItem = null;
            var matchedIndex = -1;

            angular.forEach($scope.AnteriorSegmentArrayNew, function (item, index) {
                if (item.InvestigationId === id) {
                    matchedItem = item;
                    matchedIndex = index;
                }
            });

            if (!matchedItem) return;

            $scope.$applyAsync(function () {
                $scope.selectedAnteriorItem = matchedItem;
                $scope.activeAnteriorId = id;
                $scope.activeAnteriorIndex = matchedIndex;
            });

            var leftItem = document.getElementById("leftAnterior" + id);
            if (leftItem) {
                isProgrammaticScroll = true;
                leftItem.scrollIntoView({ behavior: "smooth", block: "nearest" });
                $timeout(function () {
                    isProgrammaticScroll = false;
                }, 500);
            }
        };

        $scope.$on("$destroy", function () {
            if (anteriorPanel) {
                anteriorPanel.removeEventListener("scroll", onAnteriorScroll);
            }
            if (scrollSyncPromise) {
                $timeout.cancel(scrollSyncPromise);
            }
            isProgrammaticScroll = false;
        });


        $scope.reinitAnteriorPanel();

        $scope.selectAnteriorItem = function (item, index) {

            $scope.activeAnteriorIndex = index;
            $scope.activeAnteriorId = item.InvestigationId;
            $scope.currentAnteriorSectionName = item.InvestigationDesc;
            $scope.ExamTab = 1;
            $scope.hide = false;

            $scope.anteriorSearch.query = '';

            // Always get the latest object from the main array
            var selected = $scope.AnteriorSegmentArrayNew.find(function (x) {
                return x.InvestigationId == item.InvestigationId &&
                    x.ActiveInd == "Y";
            });

            $scope.selectedAnteriorItem = selected || item;

            // Refresh values in tablet
            $scope.refreshSelectedAnteriorFinding();

            $timeout(function () {

                initAnteriorPanel();

                var id = $scope.activeAnteriorId;

                var leftEl =
                    document.getElementById("leftAnterior" + id);

                if (leftEl) {
                    leftEl.scrollIntoView({
                        behavior: "auto",
                        block: "nearest"
                    });
                }

                var rightEl =
                    document.getElementById("sectionAnterior" + id);

                if (rightEl && anteriorPanel) {
                    anteriorPanel.scrollTo({
                        top: rightEl.offsetTop - anteriorPanel.offsetTop,
                        behavior: "auto"
                    });
                }

            }, 100);
        };



        $scope.refreshSelectedAnteriorFinding = function () {
            if (!$scope.activeAnteriorId || !$scope.AnteriorSegmentArrayNew) {
                return;
            }

            var selected = $scope.AnteriorSegmentArrayNew.find(function (item) {
                return item.InvestigationId == $scope.activeAnteriorId &&
                    item.ActiveInd == "Y";
            });

            if (!selected) {
                return;
            }

            // Keep the selected object synchronized with the main array
            $scope.selectedAnteriorItem = selected;

            $scope.currentAnteriorSectionName =
                selected.InvestigationDesc || "";

            // Force Angular to update the tablet view
            $scope.$evalAsync(function () {
                $scope.selectedAnteriorItem = selected;
                $scope.activeAnteriorId = selected.InvestigationId;
            });
        };

