        // 1. Watch
        $scope.$watch('anteriorSearch.query', function (newVal) {
            if (!newVal || newVal.trim() === '') {
                $scope.showGlobalSearch = false;
                $scope.globalSearchGrouped = [];
                $scope.globalSearchCurrentResults = [];
                $scope.globalSearchHasResults = false;
                $scope.globalSearchCurrentHasResults = false;


                isProgrammaticScroll = true;
                $timeout(function () {
                    isProgrammaticScroll = false;
                }, 300);
                return;
            }
            $scope.performGlobalAnteriorSearch(newVal.trim());
        });
        $scope.performGlobalAnteriorSearch = function (query) {
            var q = query.toLowerCase();
            var currentId = $scope.activeAnteriorId;
            var currentResults = [];
            var otherGrouped = [];

            angular.forEach($scope.AnteriorSegmentArrayNew, function (section) {
                if (section.ActiveInd !== 'Y') return;
                var matchedItems = [];
                var addedIds = {}; // duplicate avoid

                var addItem = function (item, isFav) {
                    var key = item.InvFindingId || item.FindingDescription;
                    if (addedIds[key]) return;
                    addedIds[key] = true;

                    // ✅ ADD THESE 3 LINES ONLY
                    var remarksArray = section.RemarksArray || [];
                    item.selectedOD = remarksArray.filter(function (r) { return r.InvFindingId === item.InvFindingId && r.OrganId === 1 && r.ActiveInd === 'Y'; }).length > 0;
                    item.selectedOS = remarksArray.filter(function (r) { return r.InvFindingId === item.InvFindingId && r.OrganId === 2 && r.ActiveInd === 'Y'; }).length > 0;

                    matchedItems.push({ item: item, isFav: !!isFav });
                };

                if (section.InvestigationId === 6) {
                    // MRD
                    angular.forEach($scope.MRDvaluesFilteredArray, function (item) {
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, false);
                    });
                } else {
                    // Favorites first
                    angular.forEach($scope.Anteriorfavariotes, function (item) {
                        if (item.FindingId !== section.InvestigationId) return;
                        if (!item.IsFavoriteInd) return;
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, true);
                    });

                    // Master array
                    angular.forEach($scope.NewAnteriorFindingsMasterArray, function (item) {
                        if (item.FindingId !== section.InvestigationId) return;
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, false);
                    });
                }

                if (matchedItems.length > 0) {
                    if (section.InvestigationId === currentId) {
                        currentResults = matchedItems;
                    } else {
                        otherGrouped.push({
                            sectionName: section.InvestigationDesc,
                            InvestigationId: section.InvestigationId,
                            items: matchedItems,
                            isMRD: section.InvestigationId === 6
                        });
                    }
                }
            });

            $scope.globalSearchCurrentResults = currentResults;
            $scope.globalSearchCurrentHasResults = currentResults.length > 0;
            $scope.globalSearchGrouped = otherGrouped;
            $scope.globalSearchHasResults = currentResults.length > 0 || otherGrouped.length > 0;
            $scope.showGlobalSearch = true;
            $scope.currentSectionName = '';
            angular.forEach($scope.AnteriorSegmentArrayNew, function (s) {
                if (s.InvestigationId === currentId) $scope.currentSectionName = s.InvestigationDesc;
            });
        };



