        $scope.selectGlobalSearchFinding = function (invId, item, isMRD, eye) {

            if (isMRD) {
                $scope.ChangeFindingASValue1($scope.newAnteriorObj, item, 6, eye);
            } else {
                $scope.ToggleFindingASValue($scope.newAnteriorObj, item, 5, eye);
            }

            // ✅ Icon toggle for search results UI
            if (eye === 'OD') {
                item.selectedOD = !item.selectedOD;
            } else {
                item.selectedOS = !item.selectedOS;
            }


            var matchedItem = null, matchedIndex = -1;
            angular.forEach($scope.AnteriorSegmentArrayNew, function (s, idx) {
                if (s.InvestigationId === invId && s.ActiveInd === 'Y') {
                    matchedItem = s;
                    matchedIndex = idx;
                }
            });

            if ($scope.anteriorSearch.query) {
                $scope.performGlobalAnteriorSearch($scope.anteriorSearch.query.trim());
            }

            // NO scroll, NO navigate, NO search clear
        };



