        var posteriorPanel = null;
        var posteriorScrollSyncPromise = null;
        var posteriorProgrammaticScroll = false;

        $scope.posteriorSearch = { query: '' };
        $scope.globalPosteriorGrouped = [];
        $scope.globalPosteriorCurrentResults = [];
        $scope.showPosteriorGlobalSearch = false;
        $scope.globalPosteriorHasResults = false;
        $scope.globalPosteriorCurrentHasResults = false;
        $scope.currentPosteriorSectionName = '';

        function initPosteriorPanel() {
            if (posteriorPanel) {
                posteriorPanel.removeEventListener("scroll", onPosteriorScroll);
                posteriorPanel = null;
            }

            var panel = document.getElementById("posteriorScrollPanel");
            if (panel) {
                posteriorPanel = panel;
                posteriorPanel.addEventListener("scroll", onPosteriorScroll);
                console.log("posteriorPanel initialized ✅");
                return true;
            }
            return false;
        }

        // First load
        $timeout(function () {
            if (!initPosteriorPanel()) {
                console.warn("posteriorScrollPanel not found after 500ms");
            }
        }, 500);

        $scope.reinitPosteriorPanel = function () {
            posteriorProgrammaticScroll = false;
            $timeout(function () {
                if (!initPosteriorPanel()) {
                    $timeout(function () {
                        initPosteriorPanel();
                    }, 300);
                }
            }, 200);
        };

        function onPosteriorScroll() {
            if (posteriorProgrammaticScroll) return;
            if (posteriorScrollSyncPromise) {
                $timeout.cancel(posteriorScrollSyncPromise);
            }
            posteriorScrollSyncPromise = $timeout($scope.syncPosteriorSection, 50);
        }

