        $scope.syncPosteriorSection = function () {
            if (!posteriorPanel) {
                initPosteriorPanel();

                $timeout(function () {
                    if (posteriorPanel) $scope.syncPosteriorSection();
                }, 100);
                return;
            }

            var sections = posteriorPanel.querySelectorAll(".posteriorSection");
            if (!sections || sections.length === 0) return;

            var panelRect = posteriorPanel.getBoundingClientRect();

            if (panelRect.height === 0) {
                console.warn("Posterior panel height 0 - reinitializing");
                initPosteriorPanel();
                return;
            }

            var current = null;
            angular.forEach(sections, function (sec) {
                var secRect = sec.getBoundingClientRect();
                var relativeTop = secRect.top - panelRect.top;
                var relativeBottom = relativeTop + secRect.height;
                if (relativeTop <= 20 && relativeBottom > 20) {
                    current = sec;
                }
            });

            if (!current) return;

            var id = parseInt(current.id.replace("sectionPosterior", ""));
            if ($scope.activePosteriorId === id) return;

            var matchedItem = null;
            var matchedIndex = -1;

            angular.forEach($scope.PoteriorSegmentArrayNew, function (item, index) {
                if (item.InvestigationId === id) {
                    matchedItem = item;
                    matchedIndex = index;
                }
            });

            if (!matchedItem) return;

            $scope.$applyAsync(function () {
                $scope.selectedPosteriorItem = matchedItem;
                $scope.activePosteriorId = id;
                $scope.activePosteriorIndex = matchedIndex;
                $scope.currentPosteriorSectionName = matchedItem.InvestigationDesc;
            });

            var leftItem = document.getElementById("leftPosterior" + id);
            if (leftItem) {
                posteriorProgrammaticScroll = true;
                leftItem.scrollIntoView({ behavior: "smooth", block: "nearest" });
                $timeout(function () {
                    posteriorProgrammaticScroll = false;
                }, 500);
            }
        };

        $scope.$on("$destroy", function () {
            if (posteriorPanel) {
                posteriorPanel.removeEventListener("scroll", onPosteriorScroll);
            }
            if (posteriorScrollSyncPromise) {
                $timeout.cancel(posteriorScrollSyncPromise);
            }
            posteriorProgrammaticScroll = false;
        });

        $scope.reinitPosteriorPanel();

        $scope.selectPosteriorItem = function (item, index) {
            $scope.activePosteriorIndex = index;
            $scope.activePosteriorId = item.InvestigationId;
            $scope.currentPosteriorSectionName = item.InvestigationDesc;
            $scope.ExamTab = 2;
            $scope.posteriorSearch.query = '';

            // Always get the latest object from the main array
            var selected = $scope.PoteriorSegmentArrayNew.find(function (x) {
                return x.InvestigationId == item.InvestigationId &&
                    x.ActiveInd == "Y";
            });
            $scope.selectedPosteriorItem = selected || item;

            // Refresh values in tablet
            $scope.refreshSelectedPosteriorFinding();

            $timeout(function () {
                initPosteriorPanel();
                var id = $scope.activePosteriorId;

                var leftEl = document.getElementById("leftPosterior" + id);
                if (leftEl) {
                    leftEl.scrollIntoView({
                        behavior: "auto",
                        block: "nearest"
                    });
                }

                var rightEl = document.getElementById("sectionPosterior" + id);
                if (rightEl && posteriorPanel) {
                    posteriorPanel.scrollTo({
                        top: rightEl.offsetTop - posteriorPanel.offsetTop,
                        behavior: "auto"
                    });
                }
            }, 100);
        };

        $scope.refreshSelectedPosteriorFinding = function () {
            if (!$scope.activePosteriorId || !$scope.PoteriorSegmentArrayNew) {
                return;
            }

            var selected = $scope.PoteriorSegmentArrayNew.find(function (item) {
                return item.InvestigationId == $scope.activePosteriorId &&
                    item.ActiveInd == "Y";
            });

            if (!selected) {
                return;
            }

            // Keep the selected object synchronized with the main array
            $scope.selectedPosteriorItem = selected;
            $scope.currentPosteriorSectionName = selected.InvestigationDesc || "";

            // Force Angular to update the tablet view
            $scope.$evalAsync(function () {
                $scope.selectedPosteriorItem = selected;
                $scope.activePosteriorId = selected.InvestigationId;
            });
        };


        $scope.$watch('posteriorSearch.query', function (newVal) {
            if (!newVal || newVal.trim() === '') {
                $scope.showPosteriorGlobalSearch = false;
                $scope.globalPosteriorGrouped = [];
                $scope.globalPosteriorCurrentResults = [];
                $scope.globalPosteriorHasResults = false;
                $scope.globalPosteriorCurrentHasResults = false;

                posteriorProgrammaticScroll = true;
                $timeout(function () {
                    posteriorProgrammaticScroll = false;
                }, 300);
                return;
            }
            $scope.performGlobalPosteriorSearch(newVal.trim());
        });

        $scope.performGlobalPosteriorSearch = function (query) {
            var q = query.toLowerCase();
            var currentId = $scope.activePosteriorId;
            var currentResults = [];
            var otherGrouped = [];

            angular.forEach($scope.PoteriorSegmentArrayNew, function (section) {
                if (section.ActiveInd !== 'Y') return;

                var matchedItems = [];
                var addedIds = {};

                var addItem = function (item, isFav) {
                    var key = item.InvFindingId || item.FindingDescription;
                    if (addedIds[key]) return;
                    addedIds[key] = true;

                    var remarksArray = section.RemarksArray || [];
                    item.selectedOD = remarksArray.filter(function (r) {
                        return r.InvFindingId === item.InvFindingId && r.OrganId === 1 && r.ActiveInd === 'Y';
                    }).length > 0;
                    item.selectedOS = remarksArray.filter(function (r) {
                        return r.InvFindingId === item.InvFindingId && r.OrganId === 2 && r.ActiveInd === 'Y';
                    }).length > 0;

                    matchedItems.push({ item: item, isFav: !!isFav });
                };

                if (section.InvestigationId === 32) {
                    // CDR — same role as MRD in Anterior
                    angular.forEach($scope.PosteriorRightEyeArray, function (item) {
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, false);
                    });
                } else {
                    // Favorites first
                    angular.forEach($scope.Posteriorfavariotes, function (item) {
                        if (item.FindingId !== section.InvestigationId) return;
                        if (!item.IsFavoriteInd) return;
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, true);
                    });

                    // Master array
                    angular.forEach($scope.NewPosteriorFindingsMasterArray, function (item) {
                        if (item.FindingId !== section.InvestigationId) return;
                        if ((item.FindingDescription || '').toLowerCase().indexOf(q) !== -1)
                            addItem(item, false);
                    });
                }

                if (matchedItems.length > 0) {
                    if (section.InvestigationId === currentId) {
                        currentResults = matchedItems;
                    } else {
                        otherGrouped.push({
                            sectionName: section.InvestigationDesc,
                            InvestigationId: section.InvestigationId,
                            items: matchedItems,
                            isCDR: section.InvestigationId === 32
                        });
                    }
                }
            });

            $scope.globalPosteriorCurrentResults = currentResults;
            $scope.globalPosteriorCurrentHasResults = currentResults.length > 0;
            $scope.globalPosteriorGrouped = otherGrouped;
            $scope.globalPosteriorHasResults = currentResults.length > 0 || otherGrouped.length > 0;
            $scope.showPosteriorGlobalSearch = true;

            $scope.currentPosteriorSectionName = '';
            angular.forEach($scope.PoteriorSegmentArrayNew, function (s) {
                if (s.InvestigationId === currentId) $scope.currentPosteriorSectionName = s.InvestigationDesc;
            });
        };

