        $scope.selectGlobalPosteriorFinding = function (invId, item, isCDR, eye) {

            if (isCDR) {
                $scope.ChangeFindingPSValue($scope.newPosteriorObj, item, 32, eye);
            } else {
                $scope.ToggleFindingPSValue($scope.newPosteriorObj, item, 6, eye);
            }

            // ✅ Icon toggle for search results UI
            if (eye === 'OD') {
                item.selectedOD = !item.selectedOD;
            } else {
                item.selectedOS = !item.selectedOS;
            }


            if ($scope.posteriorSearch.query) {
                $scope.performGlobalPosteriorSearch($scope.posteriorSearch.query.trim());
            }

            // NO scroll, NO navigate, NO search clear, NO posteriorProgrammaticScroll
        };


