        $scope.addFindingPopup = function (Type, obj, organ, catid, passedObject) {
            passedObject = passedObject || {};
            $scope.AddNew = $uibModal.open({
                "templateUrl": "addNewFinding.html",
                "backdrop": "static",
                "keyboard": false,
                "windowClass": "modal__threeTwentyPx--",
                "resolve": {
                    "AnteriorDetails": function () { return $scope.cacheStorageItem.AnteriorDetails },
                    "PosteriorDetails": function () { return $scope.cacheStorageItem.PosteriorDetails },
                    "Anteriorobj": function () { return $scope.newAnteriorObj },
                    "Posteriorobj": function () { return $scope.newPosteriorObj },
                    "Type": function () { return Type },
                    "obj": function () { return obj },
                    "organ": function () { return organ },
                    "catid": function () { return catid },
                    "passedObject": function () { return passedObject },
                    "ExamLogObj": function () { return $scope.ExamLogObj },
                },
                "controller": function ($scope, $uibModal, eHnoteMasterDataService, AnteriorDetails, PosteriorDetails, Anteriorobj, Posteriorobj, Type, $uibModalInstance, passedObject, ExamLogObj) {
                    $scope.AnteriorDetails = AnteriorDetails || [];
                    $scope.PosteriorDetails = PosteriorDetails || [];
                    $scope.newAnteriorObj = Anteriorobj || '';
                    $scope.newPosteriorObj = Posteriorobj || '';
                    $scope.Type = Type || "";
                    $scope.obj = obj || "";
                    $scope.organ = organ || "";
                    $scope.catid = catid || "";
                    $scope.Object = passedObject;
                    $scope.ExamLogObj = ExamLogObj || '';
                    var doctorinfo = eHnoteMasterDataService.getUserInfo();

                    $scope.AnteriorPosteriorObj = {
                        "ShowAddNewBtn": false,
                        "type": '',
                        "InvestigationDesc": '',
                        "FindingValue": '',
                        "FindingValuesArray": [],
                        "InvestigationId": 0,
                        "CategoryId": ''
                    };

                    if ($scope.Type == 'Anterior' || $scope.Type == 'GridViewAnterior') {
                        $scope.AnteriorPosteriorObj.CategoryId = $scope.newAnteriorObj.CatId || 5;
                        $scope.AnteriorPosteriorObj.InvestigationId = $scope.Object?.InvestigationId || 0;
                        $scope.AnteriorPosteriorObj.InvestigationDesc = $scope.Object?.InvestigationDesc || "";
                        $scope.AnteriorPosteriorObj.type = ($scope.Type == 'GridViewAnterior') ? 'Anterior' : $scope.Type;
                        $scope.AnteriorPosteriorObj.FindingValue = $scope.obj;
                        $scope.AnteriorPosteriorObj.FindingValuesArray = $scope.AnteriorDetails;

                        if ($scope.Type == 'GridViewAnterior') {
                            var TempArray = $filter("filter")($scope.AnteriorPosteriorObj.FindingValuesArray, { "InvestigationId": $scope.newAnteriorObj.SelectedExaminactionINVId1 }, true) || [];
                            if (TempArray.length > 0) {
                                $scope.AnteriorPosteriorObj.InvestigationId = TempArray[0].InvestigationId;
                                $scope.AnteriorPosteriorObj.InvestigationDesc = TempArray[0].InvestigationDesc;
                            }
                        }
                    }
                    else if ($scope.Type == 'Posterior' || $scope.Type == 'GridViewPosterior') {
                        $scope.AnteriorPosteriorObj.CategoryId = $scope.newPosteriorObj.CatId || 6;
                        $scope.AnteriorPosteriorObj.InvestigationId = $scope.Object?.InvestigationId || 0;
                        $scope.AnteriorPosteriorObj.InvestigationDesc = $scope.Object?.InvestigationDesc || "";
                        $scope.AnteriorPosteriorObj.type = ($scope.Type == 'GridViewPosterior') ? 'Posterior' : $scope.Type;
                        $scope.AnteriorPosteriorObj.FindingValue = $scope.obj;
                        $scope.AnteriorPosteriorObj.FindingValuesArray = $scope.PosteriorDetails.filter(function (item) { return item.InvestigationId !== 32 });

                        if ($scope.Type == 'GridViewPosterior') {
                            var TempArray = $filter("filter")($scope.AnteriorPosteriorObj.FindingValuesArray, { "InvestigationId": $scope.newPosteriorObj.SelectedExaminactionINVId1 }, true) || [];
                            if (TempArray.length > 0) {
                                $scope.AnteriorPosteriorObj.InvestigationId = TempArray[0].InvestigationId;
                                $scope.AnteriorPosteriorObj.InvestigationDesc = TempArray[0].InvestigationDesc;
                            }
                        }
                    }

                    // Pills come from FindingValuesArray (same list as left-nav).
                    // Default-select the pill matching the section the modal was opened from (e.g. "Lids").
                    $scope.SelectedPillId = $scope.AnteriorPosteriorObj.InvestigationId || 0;

                    $scope.isSectionSelected = function (item) {
                        return $scope.SelectedPillId === item.InvestigationId;
                    };

                    $scope.selectSectionPill = function (item) {
                        $scope.SelectedPillId = item.InvestigationId;
                        $scope.AnteriorPosteriorObj.InvestigationId = item.InvestigationId;
                        $scope.AnteriorPosteriorObj.InvestigationDesc = item.InvestigationDesc;
                    };

                    $scope.onSelectFindingValue = function (id, item) {
                        var TempArray = $filter("filter")($scope.AnteriorPosteriorObj.FindingValuesArray, { "InvestigationId": id }, true) || [];
                        if (TempArray.length > 0) {
                            item.InvestigationId = TempArray[0].InvestigationId;
                            item.InvestigationDesc = TempArray[0].InvestigationDesc;
                        }
                    };

                    $scope.SaveFindingValues = function () {
                        $scope.ExamLogObj.LogArray = [];

                        // Finding name now comes from the selected pill, not free text
                        if (!$scope.AnteriorPosteriorObj.InvestigationDesc || $scope.AnteriorPosteriorObj.InvestigationDesc.trim() == "") {
                            alertify.error("Please Select a Section");
                            return false;
                        }
                        if ($scope.AnteriorPosteriorObj.FindingValue == "") {
                            alertify.error("Please Enter Finding Value");
                            return false;
                        }

                        var params = {
                            "UserId": doctorinfo.doctorid,
                            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                            "OrganizationFindingValueId": 0,
                            "MasterFindingValueId": 0,
                            "DeleteInd": "N",
                            "CategoryId": $scope.AnteriorPosteriorObj.CategoryId || 0,
                            "CategoryName": $scope.AnteriorPosteriorObj.type,
                            "FindingId": $scope.AnteriorPosteriorObj.InvestigationId || 0,
                            "FindingName": $scope.AnteriorPosteriorObj.InvestigationDesc || '',
                            "OrganizationFindingId": 0,
                            "FindingValue": $scope.AnteriorPosteriorObj.FindingValue || "",
                            "IsFavoriteInd": false,
                            "Logs": {},
                        }

                        if ($scope.AnteriorPosteriorObj.InvestigationDesc !== "" && $scope.AnteriorPosteriorObj.FindingValue !== "") {
                            let newDescription = `${$scope.AnteriorPosteriorObj.InvestigationDesc} : ${$scope.AnteriorPosteriorObj.FindingValue} is Added`;
                            let obj = {
                                "LogId": 0,
                                "ModuleId": 1,
                                "ModuleName": "OUTPatient",
                                "SubModuleId": 52,
                                "SubModuleName": "Examinations",
                                "ScreenType": $scope.AnteriorPosteriorObj.type + "(Add New)" || '',
                                "ActionType": "Added",
                                "OldActionDescription": "",
                                "NewActionDescription": newDescription,
                                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                            };
                            $scope.ExamLogObj.LogArray.push(obj);
                        }

                        if ($scope.ExamLogObj.LogArray.length > 0) {
                            params.Logs = $scope.ExamLogObj || {};
                        }

                        eHnotePatientDataService.AddUpdateOrgFindingValues(params).then(function (resp) {
                            if (resp.data.Status === 'Success') {
                                resp.data.rows = resp.data.rows || [];
                                $scope.TempArray = [];
                                if (resp.data.rows.length > 0) {
                                    $scope.TempArray = resp.data.rows[0];
                                }
                                alertify.success("Save successfully");
                                $uibModalInstance.close($scope.TempArray);
                            }
                            else {
                                alertify.error(resp.data.Message);
                            }
                        });
                    }

                    $scope.closeuibpopup = function () {
                        $uibModalInstance.dismiss("cancel");

                        $scope.newAnteriorObj.ODAnteriorSearch = '';
                        $scope.newAnteriorObj.OSAnteriorSearch = '';
                        $scope.newPosteriorObj.ODPosteriorSearch = '';
                        $scope.newPosteriorObj.OSPosteriorSearch = '';
                        $scope.anteriorSearch.query = '';
                        $scope.posteriorSearch.query = '';
                    }
                }
            });

            $scope.AddNew.result.then(function (resp) {
                $scope.GetAnteriorOrgFindingValues();
                $scope.GetPosteriorOrgFindingValues();
                $scope.newAnteriorObj.AnteriorSearchObj = '';
                $scope.newPosteriorObj.PosteriorSearchObj = '';
                $scope.newAnteriorObj.OSAnteriorSearchObj = '';
                $scope.newPosteriorObj.OSPosteriorSearchObj = '';
                $scope.anteriorSearch.query = '';
                $scope.posteriorSearch.query = '';

                // Auto-navigate the left-nav to the section the finding was actually saved under
                // (the user may have switched the pill from "Lids" to "Lashes" inside the modal,
                // so we must follow the *saved* CategoryId/InvestigationId, not the one we opened with).
                if (resp) {
                    var savedCategoryName = resp.CategoryName || resp.type || '';
                    var savedFindingId = resp.FindingId || resp.InvestigationId || 0;

                    if (savedCategoryName == 'Anterior' || savedCategoryName == 'GridViewAnterior') {
                        $scope.ChangeAsPsTabs(1);
                        var anteriorMatch = $filter("filter")($scope.AnteriorSegmentArrayNew, { "InvestigationId": savedFindingId }, true) || [];
                        if (anteriorMatch.length > 0) {
                            var anteriorIndex = $scope.AnteriorSegmentArrayNew.indexOf(anteriorMatch[0]);
                            $scope.selectAnteriorItem(anteriorMatch[0], anteriorIndex);
                        }
                    }
                    else if (savedCategoryName == 'Posterior' || savedCategoryName == 'GridViewPosterior') {
                        $scope.ChangeAsPsTabs(2);
                        var posteriorMatch = $filter("filter")($scope.PoteriorSegmentArrayNew, { "InvestigationId": savedFindingId }, true) || [];
                        if (posteriorMatch.length > 0) {
                            var posteriorIndex = $scope.PoteriorSegmentArrayNew.indexOf(posteriorMatch[0]);
                            $scope.selectPosteriorItem(posteriorMatch[0], posteriorIndex);
                        }
                    }
                }
            }, function () { });
        }

