        /*Fields the Edit Diagnosis popup can change; copied to the original diagnosis only on Save Changes*/
        var DiagnosisPopupFields = [
            "LocationId1", "Location1", "LocationId2", "Location2",
            "DiagnosisStatusId1", "DiagnosisStatus1", "SortOrderId1", "VerificationStatusId1", "EndDate1",
            "DiagnosisStatusId2", "DiagnosisStatus2", "SortOrderId2", "VerificationStatusId2", "EndDate2",
            "SeverityId1", "SeverityName1", "SeverityId2", "SeverityId", "SeverityName",
            "CareEpisodeId", "CareEpisodeName", "PriorityId", "IsLocation2Added", "SnomedCodeObject"
        ];

        /*Edit Diagnosis popup: single-select groups that are cleared by clicking the selected option again*/
        var DiagnosisToggleGroups = {
            "SeverityId1": { "Clear": ["SeverityName1"], "OnSelect": "changeODSeverity" },
            "SeverityId2": { "Clear": ["SeverityId", "SeverityName"], "OnSelect": "changeOSSeverity" },
            "DiagnosisStatusId1": { "Clear": ["DiagnosisStatus1", "SortOrderId1", "VerificationStatusId1", "EndDate1"], "OnSelect": "changeRDiagnosisStatus" },
            "DiagnosisStatusId2": { "Clear": ["DiagnosisStatus2", "SortOrderId2", "VerificationStatusId2", "EndDate2"], "OnSelect": "changeLDiagnosisStatus" },
            "CareEpisodeId": { "Clear": ["CareEpisodeName"], "OnSelect": "fIsSummaryShow" },
            "PriorityId": { "Clear": [], "OnSelect": "changePriority" }
        };

        $scope.ToggleDiagnosisOption = function (obj, field, value) {
            if (!obj) {
                return;
            }
            var group = DiagnosisToggleGroups[field] || {};

            if (obj[field] == value) {
                /*Clicking the selected option unselects it*/
                obj[field] = null;
                angular.forEach(group.Clear || [], function (clearField) {
                    obj[clearField] = null;
                });
                return;
            }

            /*Selecting an option replaces the one selected before it*/
            obj[field] = value;
            if (angular.isFunction($scope[group.OnSelect])) {
                $scope[group.OnSelect](obj, value);
            }
        };

        var CopyDiagnosisPopupFields = function (source, destination) {
            if (!source || !destination) {
                return;
            }
            angular.forEach(DiagnosisPopupFields, function (field) {
                if (source.hasOwnProperty(field)) {
                    destination[field] = angular.copy(source[field]);
                }
            });
        };

        $scope.editPopup = function (item, index) {
            index = index || undefined;
            let mInstanceAdd = $uibModal.open({
                "templateUrl": "editPopup.html",
                "keyboard": false,
                "backdrop": "static",
                "scope": $scope,
                "windowClass": "modal__fifty--",
                "resolve": {
                    "GetSeverityList": function () { return $scope.GetSeverityList; },
                    "AssesmentPlanStatusList": function () { return $scope.AssesmentPlanStatusList; },
                    "CareEpisodeList": function () { return $scope.CareEpisodeList; },
                    "GetPriorityList": function () { return $scope.GetPriorityList; },
                    "Mainobj": function () { return obj; }

                },
                "controller": function ($scope, $uibModalInstance, GetSeverityList, AssesmentPlanStatusList, CareEpisodeList, GetPriorityList) {
                    $scope.GetSeverityList = GetSeverityList || [];
                    $scope.AssesmentPlanStatusList = AssesmentPlanStatusList || [];
                    $scope.CareEpisodeList = CareEpisodeList || [];
                    $scope.GetPriorityList = GetPriorityList || [];


                    var assessmentList = $scope.AssessmentplanpopupObj.AssessmentListArray || [];

                    /*Diagnosis being edited: the selected one, or the row just added*/
                    var originalItem = item || (assessmentList.length > 0
                        ? assessmentList[assessmentList.length - 1]
                        : null);

                    /*Values prepared on the controller scope for a newly added diagnosis*/
                    var newDiagnosisDefaults = $scope.AssessmentDiagnosispopupObj;

                    /*The popup edits a temporary copy, so Cancel/Close leave the original diagnosis unchanged*/
                    $scope.AssessmentDiagnosispopupObj = angular.copy(originalItem) || {};
                    if (item == undefined) {
                        CopyDiagnosisPopupFields(newDiagnosisDefaults, $scope.AssessmentDiagnosispopupObj);
                    }
                    $scope.OriginalDiagnosisItem = originalItem;

                    $scope.uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    };
                    $scope.SaveAssessmentchanges = function (item) {
                        if (item.LocationId1 == 0 && item.LocationId2 == 0) {
                            alertify.error("Please Select Organ For Diagnosis");
                            return false;
                        }

                        CopyDiagnosisPopupFields(item, originalItem);

                        $uibModalInstance.close(originalItem);
                    }
                }
            });
        };

